INSERT INTO public.industries ("siteId", id, slug, name, "nameEn", "nameJa", "nameKo", "nameFr", "nameAr", tagline, "taglineEn", "taglineJa", "taglineKo", "taglineFr", "taglineAr", description, "descriptionEn", "descriptionJa", "descriptionKo", "descriptionFr", "descriptionAr", challenges, "challengesEn", "challengesJa", "challengesKo", "challengesFr", "challengesAr", solutions, "solutionsEn", "solutionsJa", "solutionsKo", "solutionsFr", "solutionsAr", products, "productsEn", "productsJa", "productsKo", "productsFr", "productsAr", cases, "casesEn", "casesJa", "casesKo", "casesFr", "casesAr", image, video, icon, "sortOrder", status, "seoTitle", "seoTitleEn", "seoTitleJa", "seoTitleKo", "seoTitleFr", "seoTitleAr", "seoDescription", "seoDescriptionEn", "seoDescriptionJa", "seoDescriptionKo", "seoDescriptionFr", "seoDescriptionAr", "seoKeywords", "seoKeywordsEn", "seoKeywordsJa", "seoKeywordsKo", "seoKeywordsFr", "seoKeywordsAr", "geoRegion", "geoCity", "solutionFile", "solutionFileName", "solutionFileNameEn", "solutionFileNameJa", "solutionFileNameKo", "solutionFileNameFr", "solutionFileNameAr", "relatedProductSlugs", "relatedIndustrySlugs", "createdAt", "updatedAt") VALUES (NULL, 10, 'solar-photovoltaic', 'Solar & Photovoltaic', 'Solar & Photovoltaic', 'ソーラー&太陽光発電', '태양광 및 태양광', 'Solaire et photovoltaïque', 'الطاقة الشمسية والضوئية', 'High-reliability fluid components for cell manufacturing', 'High-reliability fluid components for cell manufacturing', 'セル製造用高信頼性流体部品', '세포 제조용 고신뢰성 유체 부품', 'Composants fluides à haute fiabilité pour la fabrication de cellules', 'مكونات السوائل عالية الموثوقية لتصنيع الخلايا', 'For diffusion, PECVD and laser-selective emitter lines, VALTRIX delivers cost-effective yet UHP-compliant fittings and valves that maintain gas purity across high-volume cell production.', 'For diffusion, PECVD and laser-selective emitter lines, VALTRIX delivers cost-effective yet UHP-compliant fittings and valves that maintain gas purity across high-volume cell production.', '拡散、PECVD、レーザー選択エミッタライン向けに、VALTRIX は、コスト効率が高く、UHP 準拠の継手とバルブを提供し、大量のセル生産全体でガス純度を維持します。', '확산, PECVD 및 레이저 선택적 이미터 라인의 경우 VALTRIX는 대용량 셀 생산 전반에 걸쳐 가스 순도를 유지하는 비용 효율적이면서도 UHP를 준수하는 피팅과 밸브를 제공합니다.', 'Pour les lignes d''émetteurs de diffusion, PECVD et laser sélectif, VALTRIX fournit des raccords et des vannes rentables mais conformes à l''UHP qui maintiennent la pureté du gaz dans la production de cellules de haut volume.', 'بالنسبة لخطوط الانتشار و PECVD والباعث الانتقائي بالليزر ، توفر VALTRIX تجهيزات وصمامات فعالة من حيث التكلفة ولكنها متوافقة مع UHP والتي تحافظ على نقاء الغاز عبر إنتاج الخلايا ذات الحجم الكبير.', '["Up-time: high-volume lines cannot tolerate unscheduled leak downtime."]', '["Up-time: high-volume lines cannot tolerate unscheduled leak downtime."]', NULL, NULL, NULL, NULL, '[{"desc": "UHP-compliant fittings and valves that maintain gas purity across high-volume cell production.", "title": "High-Reliability Components"}]', '[{"desc": "UHP-compliant fittings and valves that maintain gas purity across high-volume cell production.", "title": "High-Reliability Components"}]', NULL, NULL, NULL, NULL, '[]', '[]', NULL, NULL, NULL, NULL, '[]', '[]', NULL, NULL, NULL, NULL, '/uploads/oem/bsm-mr4.jpg', NULL, NULL, 4, 'published', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-09-07 11:57:42.102', '2026-09-07 12:02:41.909');
INSERT INTO public.industries ("siteId", id, slug, name, "nameEn", "nameJa", "nameKo", "nameFr", "nameAr", tagline, "taglineEn", "taglineJa", "taglineKo", "taglineFr", "taglineAr", description, "descriptionEn", "descriptionJa", "descriptionKo", "descriptionFr", "descriptionAr", challenges, "challengesEn", "challengesJa", "challengesKo", "challengesFr", "challengesAr", solutions, "solutionsEn", "solutionsJa", "solutionsKo", "solutionsFr", "solutionsAr", products, "productsEn", "productsJa", "productsKo", "productsFr", "productsAr", cases, "casesEn", "casesJa", "casesKo", "casesFr", "casesAr", image, video, icon, "sortOrder", status, "seoTitle", "seoTitleEn", "seoTitleJa", "seoTitleKo", "seoTitleFr", "seoTitleAr", "seoDescription", "seoDescriptionEn", "seoDescriptionJa", "seoDescriptionKo", "seoDescriptionFr", "seoDescriptionAr", "seoKeywords", "seoKeywordsEn", "seoKeywordsJa", "seoKeywordsKo", "seoKeywordsFr", "seoKeywordsAr", "geoRegion", "geoCity", "solutionFile", "solutionFileName", "solutionFileNameEn", "solutionFileNameJa", "solutionFileNameKo", "solutionFileNameFr", "solutionFileNameAr", "relatedProductSlugs", "relatedIndustrySlugs", "createdAt", "updatedAt") VALUES (NULL, 7, 'semiconductor', 'Semiconductor Manufacturing', 'Semiconductor Manufacturing', '半導体製造', '반도체 제조', 'Fabrication de semi-conducteurs', 'تصنيع أشباه الموصلات', 'Ultra-high-purity fluid control for wafer fabs', 'Ultra-high-purity fluid control for wafer fabs', 'ウエハファブの超高純度流体制御', 'wafer fabs를 위한 초고순도 유체 제어', 'Contrôle de fluide ultra-haute pureté pour tissus de plaquettes', 'التحكم في السوائل فائقة النقاء لمصانع الرقاقة', 'VALTRIX supplies UHP-grade fittings, diaphragm valves and regulators engineered for semiconductor process tools and gas delivery systems. All wetted parts are 316L stainless steel with electro-polished surfaces, helium-leak tested to semiconductor standards.', 'VALTRIX supplies UHP-grade fittings, diaphragm valves and regulators engineered for semiconductor process tools and gas delivery systems. All wetted parts are 316L stainless steel with electro-polished surfaces, helium-leak tested to semiconductor standards.', 'VALTRIXは、半導体プロセスツールやガス供給システム用に設計されたUHPグレードの継手、ダイヤフラムバルブ、レギュレータを供給しています。すべての濡れた部品は、電気研磨された表面を備えた316Lステンレス鋼で、半導体規格に従ってヘリウム漏れがテストされています。', 'VALTRIX는 반도체 공정 공구 및 가스 공급 시스템을 위해 설계된 UHP 등급 피팅, 다이어프램 밸브 및 레귤레이터를 공급합니다. 모든 젖은 부품은 전기 연마 표면을 가진 316L 스테인리스 스틸이며, 반도체 표준에 따라 헬륨 누출 테스트되었습니다.', 'VALTRIX fournit des raccords de qualité UHP, des vannes à membrane et des régulateurs conçus pour les outils de procédé à semi-conducteurs et les systèmes de distribution de gaz. Toutes les pièces mouillées sont en acier inoxydable 316L avec des surfaces électropolies, testées en hélium-fuite selon les normes de semi-conducteurs.', 'توفر VALTRIX تجهيزات من فئة UHP وصمامات الحجاب الحاجز والمنظمات المصممة لأدوات معالجة أشباه الموصلات وأنظمة توصيل الغاز. جميع الأجزاء المبللة مصنوعة من الفولاذ المقاوم للصدأ 316L بأسطح مصقولة كهربائيًا ، تم اختبارها لتسرب الهيليوم وفقًا لمعايير أشباه الموصلات.', '["Trace contamination control: moisture, oxygen and particles above ppb levels degrade process yield; components must be leak-tight below 1x10-9 scc/s He.", "Particle generation: mechanical wear in the wetted flow path creates particles that contaminate wafers.", "Process gas compatibility: corrosive and pyrophoric gases demand materials and surface finishes that resist attack."]', '["Trace contamination control: moisture, oxygen and particles above ppb levels degrade process yield; components must be leak-tight below 1x10-9 scc/s He.", "Particle generation: mechanical wear in the wetted flow path creates particles that contaminate wafers.", "Process gas compatibility: corrosive and pyrophoric gases demand materials and surface finishes that resist attack."]', NULL, NULL, NULL, NULL, '[{"desc": "VCR fittings, diaphragm valves and regulators with EP surfaces for process tool gas lines.", "title": "UHP Component Range"}, {"desc": "Every component helium leak tested to semiconductor standards before cleanroom packaging.", "title": "100% Leak Testing"}]', '[{"desc": "VCR fittings, diaphragm valves and regulators with EP surfaces for process tool gas lines.", "title": "UHP Component Range"}, {"desc": "Every component helium leak tested to semiconductor standards before cleanroom packaging.", "title": "100% Leak Testing"}]', NULL, NULL, NULL, NULL, '["VCR Face Seal Fittings", "Diaphragm Valves", "Pressure Reducers", "Gas Filters"]', '["VCR Face Seal Fittings", "Diaphragm Valves", "Pressure Reducers", "Gas Filters"]', NULL, NULL, NULL, NULL, '[{"desc": "Supplied 1,200+ VCR components for a 12-inch fab gas panel retrofit with zero leak rework.", "title": "Fab gas panel retrofit"}]', '[{"desc": "Supplied 1,200+ VCR components for a 12-inch fab gas panel retrofit with zero leak rework.", "title": "Fab gas panel retrofit"}]', NULL, NULL, NULL, NULL, '/uploads/home/hero-cleanroom.jpg', NULL, NULL, 1, 'published', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-09-07 11:57:42.091', '2026-09-07 12:02:41.903');
INSERT INTO public.industries ("siteId", id, slug, name, "nameEn", "nameJa", "nameKo", "nameFr", "nameAr", tagline, "taglineEn", "taglineJa", "taglineKo", "taglineFr", "taglineAr", description, "descriptionEn", "descriptionJa", "descriptionKo", "descriptionFr", "descriptionAr", challenges, "challengesEn", "challengesJa", "challengesKo", "challengesFr", "challengesAr", solutions, "solutionsEn", "solutionsJa", "solutionsKo", "solutionsFr", "solutionsAr", products, "productsEn", "productsJa", "productsKo", "productsFr", "productsAr", cases, "casesEn", "casesJa", "casesKo", "casesFr", "casesAr", image, video, icon, "sortOrder", status, "seoTitle", "seoTitleEn", "seoTitleJa", "seoTitleKo", "seoTitleFr", "seoTitleAr", "seoDescription", "seoDescriptionEn", "seoDescriptionJa", "seoDescriptionKo", "seoDescriptionFr", "seoDescriptionAr", "seoKeywords", "seoKeywordsEn", "seoKeywordsJa", "seoKeywordsKo", "seoKeywordsFr", "seoKeywordsAr", "geoRegion", "geoCity", "solutionFile", "solutionFileName", "solutionFileNameEn", "solutionFileNameJa", "solutionFileNameKo", "solutionFileNameFr", "solutionFileNameAr", "relatedProductSlugs", "relatedIndustrySlugs", "createdAt", "updatedAt") VALUES (NULL, 8, 'biopharmaceutical', 'Biopharmaceutical', 'Biopharmaceutical', 'バイオ医薬品', '바이오 제약', 'biopharmaceutique', 'الصيدلانية الحيوية', 'Cleanable, drainable fluid systems for pharma processes', 'Cleanable, drainable fluid systems for pharma processes', '製薬プロセス用の洗浄可能で排水可能な流体システム', '제약 공정을 위한 청소 가능한 배수 가능한 유체 시스템', 'Systèmes de fluide nettoyables et drainables pour les procédés pharmaceutiques', 'أنظمة السوائل القابلة للتنظيف والتصريف للعمليات الصيدلانية', 'From WFI distribution to chromatography skids, VALTRIX provides sanitary-grade flow control components with smooth surface finishes, crevice-free construction and full material traceability.', 'From WFI distribution to chromatography skids, VALTRIX provides sanitary-grade flow control components with smooth surface finishes, crevice-free construction and full material traceability.', 'WFI 分配からクロマトグラフィー スキッドまで、VALTRIX は、滑らかな表面仕上げ、隙間のない構造、完全な材料トレーサビリティを備えた衛生的なグレードのフロー制御コンポーネントを提供します。', 'WFI 분포에서 크로마토그래피 스키드에 이르기까지 VALTRIX는 부드러운 표면 마감, 틈새 없는 구조 및 완전한 재료 추적 가능성을 갖춘 위생 등급의 흐름 제어 구성 요소를 제공합니다.', 'De la distribution WFI aux patins de chromatographie, VALTRIX fournit des composants de contrôle de débit de qualité sanitaire avec des finitions de surface lisses, une construction sans fissures et une traçabilité complète des matériaux.', 'من توزيع WFI إلى انزلاقات الكروماتوغرافيا ، توفر VALTRIX مكونات التحكم في التدفق من الدرجة الصحية مع تشطيبات سطحية ناعمة وبناء خالي من الشقوق وإمكانية تتبع المواد بالكامل.', '["CIP/SIP compatibility: components must withstand repeated clean-in-place and steam-in-place cycles.", "Dead-leg elimination: stagnant zones harbour microbial growth and violate GMP expectations."]', '["CIP/SIP compatibility: components must withstand repeated clean-in-place and steam-in-place cycles.", "Dead-leg elimination: stagnant zones harbour microbial growth and violate GMP expectations."]', NULL, NULL, NULL, NULL, '[{"desc": "Crevice-free, drainable flow paths with smooth surface finishes for sterile processes.", "title": "Sanitary Design"}]', '[{"desc": "Crevice-free, drainable flow paths with smooth surface finishes for sterile processes.", "title": "Sanitary Design"}]', NULL, NULL, NULL, NULL, '["Sanitary Diaphragm Valves", "Welded Fittings"]', '["Sanitary Diaphragm Valves", "Welded Fittings"]', NULL, NULL, NULL, NULL, '[]', '[]', NULL, NULL, NULL, NULL, '/uploads/oem/ft5-mr4.jpg', NULL, NULL, 2, 'published', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-09-07 11:57:42.096', '2026-09-07 12:02:41.906');
INSERT INTO public.industries ("siteId", id, slug, name, "nameEn", "nameJa", "nameKo", "nameFr", "nameAr", tagline, "taglineEn", "taglineJa", "taglineKo", "taglineFr", "taglineAr", description, "descriptionEn", "descriptionJa", "descriptionKo", "descriptionFr", "descriptionAr", challenges, "challengesEn", "challengesJa", "challengesKo", "challengesFr", "challengesAr", solutions, "solutionsEn", "solutionsJa", "solutionsKo", "solutionsFr", "solutionsAr", products, "productsEn", "productsJa", "productsKo", "productsFr", "productsAr", cases, "casesEn", "casesJa", "casesKo", "casesFr", "casesAr", image, video, icon, "sortOrder", status, "seoTitle", "seoTitleEn", "seoTitleJa", "seoTitleKo", "seoTitleFr", "seoTitleAr", "seoDescription", "seoDescriptionEn", "seoDescriptionJa", "seoDescriptionKo", "seoDescriptionFr", "seoDescriptionAr", "seoKeywords", "seoKeywordsEn", "seoKeywordsJa", "seoKeywordsKo", "seoKeywordsFr", "seoKeywordsAr", "geoRegion", "geoCity", "solutionFile", "solutionFileName", "solutionFileNameEn", "solutionFileNameJa", "solutionFileNameKo", "solutionFileNameFr", "solutionFileNameAr", "relatedProductSlugs", "relatedIndustrySlugs", "createdAt", "updatedAt") VALUES (NULL, 9, 'led-display', 'LED & Display', 'LED & Display', 'LED・ディスプレイ', 'LED & 디스플레이', 'LED & affichage', 'LED & العرض', 'Precise gas control for epitaxy and thin-film processes', 'Precise gas control for epitaxy and thin-film processes', 'エピタキシーおよび薄膜プロセスのための精密ガス制御', '에피탁시 및 박막 공정을 위한 정밀 가스 제어', 'Contrôle précis des gaz pour les procédés d''épitaxie et de couches minces', 'التحكم الدقيق في الغاز لعمليات الإيبيتاكسي والأغشية الرقيقة', 'MOCVD and sputtering processes require stable, repeatable gas delivery. VALTRIX regulators and mass-flow-ready manifolds maintain tight pressure control for epitaxial growth and PVD chambers.', 'MOCVD and sputtering processes require stable, repeatable gas delivery. VALTRIX regulators and mass-flow-ready manifolds maintain tight pressure control for epitaxial growth and PVD chambers.', 'MOCVD およびスパッタリング プロセスでは、安定した繰り返し可能なガス供給が必要です。VALTRIX レギュレーターとマスフロー対応マニホールドは、エピタキシャル成長および PVD チャンバーの厳密な圧力制御を維持します。', 'MOCVD 및 스퍼터링 공정은 안정적이고 반복 가능한 가스 공급이 필요합니다. VALTRIX 조절기와 질량 흐름 준비 매니폴드는 에피택셜 성장 및 PVD 챔버에 대한 긴밀한 압력 제어를 유지합니다.', 'Les processus de MOCVD et de pulvérisation nécessitent une alimentation de gaz stable et répétable. Les régulateurs VALTRIX et les collecteurs prêts au débit de masse maintiennent un contrôle de pression strict pour la croissance épitaxiale et les chambres PVD.', 'تتطلب عمليات MOCVD والرش توصيل غاز مستقر وقابل للتكرار. تحافظ منظمات VALTRIX والمشعبات الجاهزة للتدفق الكتلي على تحكم محكم في الضغط للنمو الخارجي وغرف PVD.', '["Pressure stability: epitaxial film quality depends on micro-level pressure stability of hydride gases."]', '["Pressure stability: epitaxial film quality depends on micro-level pressure stability of hydride gases."]', NULL, NULL, NULL, NULL, '[{"desc": "Compact regulators and manifolds maintain tight pressure control for MOCVD and sputtering.", "title": "Stable Gas Delivery"}]', '[{"desc": "Compact regulators and manifolds maintain tight pressure control for MOCVD and sputtering.", "title": "Stable Gas Delivery"}]', NULL, NULL, NULL, NULL, '["Compact Regulators"]', '["Compact Regulators"]', NULL, NULL, NULL, NULL, '[]', '[]', NULL, NULL, NULL, NULL, '/uploads/oem/ft4-mr4.png', NULL, NULL, 3, 'published', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-09-07 11:57:42.099', '2026-09-07 12:02:41.908');
INSERT INTO public.industries ("siteId", id, slug, name, "nameEn", "nameJa", "nameKo", "nameFr", "nameAr", tagline, "taglineEn", "taglineJa", "taglineKo", "taglineFr", "taglineAr", description, "descriptionEn", "descriptionJa", "descriptionKo", "descriptionFr", "descriptionAr", challenges, "challengesEn", "challengesJa", "challengesKo", "challengesFr", "challengesAr", solutions, "solutionsEn", "solutionsJa", "solutionsKo", "solutionsFr", "solutionsAr", products, "productsEn", "productsJa", "productsKo", "productsFr", "productsAr", cases, "casesEn", "casesJa", "casesKo", "casesFr", "casesAr", image, video, icon, "sortOrder", status, "seoTitle", "seoTitleEn", "seoTitleJa", "seoTitleKo", "seoTitleFr", "seoTitleAr", "seoDescription", "seoDescriptionEn", "seoDescriptionJa", "seoDescriptionKo", "seoDescriptionFr", "seoDescriptionAr", "seoKeywords", "seoKeywordsEn", "seoKeywordsJa", "seoKeywordsKo", "seoKeywordsFr", "seoKeywordsAr", "geoRegion", "geoCity", "solutionFile", "solutionFileName", "solutionFileNameEn", "solutionFileNameJa", "solutionFileNameKo", "solutionFileNameFr", "solutionFileNameAr", "relatedProductSlugs", "relatedIndustrySlugs", "createdAt", "updatedAt") VALUES (NULL, 12, 'research-labs', 'Research Laboratories', 'Research Laboratories', '研究所', '연구 실험실', 'Laboratoires de recherche', 'مختبرات البحوث', 'Reliable gas systems for R&D and pilot plants', 'Reliable gas systems for R&D and pilot plants', 'R&Dおよびパイロットプラント向けの信頼性の高いガスシステム', 'R&D 및 파일럿 플랜트를 위한 신뢰할 수 있는 가스 시스템', 'Systèmes de gaz fiables pour la R&D et les usines pilotes', 'أنظمة غاز موثوقة للبحث والتطوير والمصانع التجريبية', 'Universities, national labs and pilot facilities rely on VALTRIX for flexible, modular gas handling — from bench-top manifolds to complete analytical instrument gas panels.', 'Universities, national labs and pilot facilities rely on VALTRIX for flexible, modular gas handling — from bench-top manifolds to complete analytical instrument gas panels.', '大学、国立研究所、パイロット施設は、ベンチトップマニホールドから完全な分析機器のガスパネルまで、柔軟でモジュラー型のガス処理をVALTRIXに依存しています。', '대학, 국립 연구소 및 파일럿 시설은 벤치탑 매니폴드에서 완전한 분석 기기 가스 패널에 이르기까지 유연하고 모듈식 가스 처리를 위해 VALTRIX에 의존합니다.', 'Les universités, les laboratoires nationaux et les installations pilotes comptent sur VALTRIX pour une manipulation flexible et modulaire des gaz, des collecteurs de banc aux panneaux de gaz d''instruments analytiques complets.', 'تعتمد الجامعات والمختبرات الوطنية والمرافق التجريبية على VALTRIX للتعامل المرن والمعياري مع الغاز - من المشعبات الموجودة على الطاولة إلى ألواح الغاز التحليلية الكاملة.', '[]', '[]', NULL, NULL, NULL, NULL, '[{"desc": "Flexible bench-top manifolds and complete analytical instrument gas panels for R&D facilities.", "title": "Modular Gas Handling"}]', '[{"desc": "Flexible bench-top manifolds and complete analytical instrument gas panels for R&D facilities.", "title": "Modular Gas Handling"}]', NULL, NULL, NULL, NULL, '[]', '[]', NULL, NULL, NULL, NULL, '[]', '[]', NULL, NULL, NULL, NULL, '/uploads/oem/IE-TB8.png', NULL, NULL, 6, 'published', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-09-07 11:57:42.107', '2026-09-07 12:02:41.911');
INSERT INTO public.industries ("siteId", id, slug, name, "nameEn", "nameJa", "nameKo", "nameFr", "nameAr", tagline, "taglineEn", "taglineJa", "taglineKo", "taglineFr", "taglineAr", description, "descriptionEn", "descriptionJa", "descriptionKo", "descriptionFr", "descriptionAr", challenges, "challengesEn", "challengesJa", "challengesKo", "challengesFr", "challengesAr", solutions, "solutionsEn", "solutionsJa", "solutionsKo", "solutionsFr", "solutionsAr", products, "productsEn", "productsJa", "productsKo", "productsFr", "productsAr", cases, "casesEn", "casesJa", "casesKo", "casesFr", "casesAr", image, video, icon, "sortOrder", status, "seoTitle", "seoTitleEn", "seoTitleJa", "seoTitleKo", "seoTitleFr", "seoTitleAr", "seoDescription", "seoDescriptionEn", "seoDescriptionJa", "seoDescriptionKo", "seoDescriptionFr", "seoDescriptionAr", "seoKeywords", "seoKeywordsEn", "seoKeywordsJa", "seoKeywordsKo", "seoKeywordsFr", "seoKeywordsAr", "geoRegion", "geoCity", "solutionFile", "solutionFileName", "solutionFileNameEn", "solutionFileNameJa", "solutionFileNameKo", "solutionFileNameFr", "solutionFileNameAr", "relatedProductSlugs", "relatedIndustrySlugs", "createdAt", "updatedAt") VALUES (NULL, 11, 'hydrogen-energy', 'Hydrogen Energy', 'Hydrogen Energy', '水素エネルギー', '수소 에너지', 'énergie hydrogène', 'طاقة الهيدروجين', 'Leak-tight components for hydrogen systems', 'Leak-tight components for hydrogen systems', '水素システム用リークタイト部品', '수소 시스템을 위한 누출 방지 부품', 'Composants étanches pour systèmes à hydrogène', 'مكونات مقاومة للتسرب لأنظمة الهيدروجين', 'From electrolyser skids to refuelling stations, VALTRIX components are designed and helium-tested for hydrogen service, including high-pressure reducer applications up to 3500 psig inlet.', 'From electrolyser skids to refuelling stations, VALTRIX components are designed and helium-tested for hydrogen service, including high-pressure reducer applications up to 3500 psig inlet.', '電解液スキッドから給油ステーションまで、VALTRIX コンポーネントは、最大 3500 psig 入口の高圧減速機アプリケーションを含む水素サービス用に設計およびヘリウムテストされています。', '전해기 스키드에서 급유 스테이션에 이르기까지 VALTRIX 구성 요소는 최대 3,500psig 입구의 고압 감속기 애플리케이션을 포함하여 수소 서비스를 위해 설계 및 헬륨 테스트를 받았습니다.', 'Des patins d''électrolyseur aux stations de ravitaillement, les composants VALTRIX sont conçus et testés sur l''hélium pour le service à l''hydrogène, y compris les applications de réducteurs de haute pression jusqu''à 3500 psig d''entrée.', 'من انزلاقات المحلل الكهربائي إلى محطات التزود بالوقود ، تم تصميم مكونات VALTRIX واختبارها على الهيليوم لخدمة الهيدروجين ، بما في ذلك تطبيقات مخفض الضغط العالي حتى مدخل 3500 رطل لكل بوصة مربعة.', '["Leak integrity: hydrogen''s small molecule demands superior leak-tightness."]', '["Leak integrity: hydrogen''s small molecule demands superior leak-tightness."]', NULL, NULL, NULL, NULL, '[{"desc": "Components designed and helium-tested for hydrogen service, including 3500 psig inlet reducers.", "title": "Leak-Tight System"}]', '[{"desc": "Components designed and helium-tested for hydrogen service, including 3500 psig inlet reducers.", "title": "Leak-Tight System"}]', NULL, NULL, NULL, NULL, '["High-Pressure Reducers"]', '["High-Pressure Reducers"]', NULL, NULL, NULL, NULL, '[]', '[]', NULL, NULL, NULL, NULL, '/uploads/oem/GJ_1.jpg', NULL, NULL, 5, 'published', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-09-07 11:57:42.104', '2026-09-07 12:02:41.91');


