INSERT INTO public.products ("siteId", id, "tabId", "categoryId", slug, model, name, "nameEn", "nameJa", "nameKo", "nameFr", "nameAr", subtitle, "subtitleEn", "subtitleJa", "subtitleKo", "subtitleFr", "subtitleAr", summary, "summaryEn", "summaryJa", "summaryKo", "summaryFr", "summaryAr", description, "descriptionEn", "descriptionJa", "descriptionKo", "descriptionFr", "descriptionAr", features, "featuresEn", "featuresJa", "featuresKo", "featuresFr", "featuresAr", images, price, "priceTiers", "isParts", "coverImage", video, frames360, "manualUrl", "priceMin", "priceMax", "priceUnit", moq, "priceNote", "priceNoteEn", "priceNoteJa", "priceNoteKo", "priceNoteFr", "priceNoteAr", specs, "sortOrder", status, "publishedAt", "createdAt", "updatedAt", "seoTitle", "seoTitleJa", "seoTitleKo", "seoTitleFr", "seoTitleAr", "seoTitleEn", "seoDescription", "seoDescriptionJa", "seoDescriptionKo", "seoDescriptionFr", "seoDescriptionAr", "seoDescriptionEn", "seoKeywords", "seoKeywordsJa", "seoKeywordsKo", "seoKeywordsFr", "seoKeywordsAr", "seoKeywordsEn", "geoRegion", "geoCity") VALUES (NULL, 26, 36, 8, 'weld-fitting-b-series', '316L-BE/BT/ID/IT/IV Series', '长焊接接头 B 系列', 'Long Weld Joint B Series', 'ロング溶接継手 Bシリーズ', '긴 용접 조인트 B 시리즈', 'Joint soudé long série B', 'المفاصل الملحومة الطويلة السلسلة B', '直通/弯头/三通/四通全系列对焊接头', 'Straight-through / Elbow / Three-way / Four-way full range of butt welded joints', 'スルー/エルボ/ティー/フォーウェイのフルシリーズの突き合わせ溶接ヘッド', '통과/팔꿈치/티/네 방향 버트 용접 조인트의 전체 범위', 'Gamme complète de joints de soudage à butte à travers/coude/tee/quatre voies', 'مجموعة كاملة من المفاصل الملحومة بعقب من خلال / الكوع / تي اتجاه / رباعي', 'B 系列长焊接接头涵盖直通、45° 弯头、90° 弯头、变径弯头、三通、变径三通、立体三通、四通及焊接环等 11 种形式。端部平直无毛刺以保证对准性，关键部位 100% 视觉检验，内表面电解抛光可选 Ra5μin。适用于高纯与超高纯气体管路系统。', 'The B series long welded joints cover 11 types, including straight-through, 45° elbow, 90° elbow, diameter-changing elbow, three-way, diameter-changing three-way, three-dimensional three-way, four-way, and welded ring. The ends are straight and burr-free to ensure alignment, key areas are 100% visually inspected, and the inner surface can be electrolytically polished at Ra5μin. Suitable for high-purity and ultra-high-purity gas pipeline systems.', 'Bシリーズ長溶接継手は、直通、45°エルボ、90°エルボ、可変エルボ、ティー、可変ティー、立体ティー、四方、溶接リングなど11種類の形式をカバーしています。端部はバリのないまっすぐな位置合わせ、重要な部分は 100% 目視検査され、内面は電解研磨でオプション Ra5μin です。高純度と超高純度ガスパイプラインシステムに適しています。', 'B 시리즈 긴 용접 조인트는 스루, 45° 엘보, 90° 엘보, 변경 엘보, 티, 변경 티, 입체 티, 4 방향 및 용접 링 등 11 가지 형태를 포함합니다. 정렬을 보장하기 위해 끝부분이 평평하고 버가 없으며 주요 부분은 100% 시각적으로 검사되며 내부 표면은 Ra5μin으로 전해 연마됩니다. 고순도 및 초고순도 가스 파이프라인 시스템에 적합합니다.', 'Les joints soudés longs de la série B couvrent 11 types, dont le coude droit, le coude à 45°, le coude à 90°, le coude à diamètre réducteur, le tee, le tee à diamètre réducteur, le tee tridimensionnel, le four-way et l''anneau de soudage. Les extrémités sont plates et sans bavures pour assurer l''alignement, les parties clés sont inspectées visuellement à 100% et le polissage électrolytique de la surface intérieure est optionnel Ra5 μ in. Convient aux systèmes de gazoducs de haute pureté et d''ultra-haute pureté.', 'تغطي الوصلات الملحومة الطويلة من السلسلة B 11 شكلًا بما في ذلك الكوع المستقيم ، والكوع 45 درجة ، والكوع 90 درجة ، والكوع المخفف ، والتي ، والتي المخفف ، والتي ثلاثية الأبعاد ، وأربعة اتجاهات وحلقات اللحام. النهايات مستقيمة وخالية من الاختباء لضمان المحاذاة ، والفحص البصري بنسبة 100% للأجزاء الرئيسية ، والتلميع الكهربائي للسطح الداخلي اختياري Ra5μin. مناسبة لأنظمة خطوط أنابيب الغاز عالية النقاء والفائقة النقاء.', '<p>B 系列长焊接接头专为半导体超高纯管路设计，加工精确、端部平直无毛刺，保证与管径精确匹配。每个接头带有永久可追溯标识。</p><p>材料可选 316L、316L VAR、316L VIM-VAR，浸润面粗糙度 Ra5μin（0.13μm）至 Ra15μin（0.4μm），工艺规范覆盖标准（GP）、高纯（HP）与超高纯（UHP）。工作温度范围 -198℃ 至 538℃。</p>', '<p>The B series long solder joints are designed specifically for ultra-high purity semiconductor pipelines, featuring precise machining, straight ends, and no burrs, ensuring precise matching with the pipe diameter. Each connector has a permanent traceability identification.</p><p>Materials available are 316L, 316L VAR, and 316L VIM-VAR, with impregnated surface roughness ranging from Ra5μin (0.13μm) to Ra15μin (0.4μm), and process specifications covering standard (GP), high purity (HP), and ultra-high purity (UHP). Operating temperature range -198℃ to 538℃.</p>', '<p>B シリーズの長い溶接継手は、半導体超高純度パイプライン用に特別に設計されており、正確な加工とバリのないまっすぐな端を備えており、パイプ直径との正確な一致を保証します。各ジョイントには永続的なトレーサビリティロゴが付いています。</p><p>材料は 316L、316L VAR、316L VIM-VAR から選択でき、浸潤面粗さは Ra5μin (0.13μm) ~ Ra15μin (0.4μm)、プロセス仕様は標準 (GP)、高純度 (HP)、超高純度 (UHP) をカバーします。動作温度範囲 -198℃~538℃。</p>', '<p>B 시리즈 긴 용접 조인트는 반도체 초고순도 파이프라인을 위해 특별히 설계되었으며 정확한 가공과 버가 없는 직선형 끝으로 파이프 직경과 정확한 일치를 보장합니다. 각 커넥터에는 영구 추적 가능 로고가 있습니다.</p><p>재료 선택 사항: 316L, 316L VAR, 316L VIM-VAR, 침윤 표면 거칠기 Ra5μin(0.13μm) ~ Ra15μin(0.4μm), 공정 사양은 표준(GP), 고순도(HP) 및 초고순도(UHP)를 포함합니다. 작동 온도 범위 -198℃에서 538℃.</p>', '<p>Les joints soudés longs de la série B sont spécialement conçus pour les pipelines semi-conducteurs ultra-haute pureté, avec un traitement précis et des extrémités droites et sans bavures, garantissant une correspondance précise avec le diamètre du tuyau. Chaque joint porte une identification traçable en permanence.</p><p>Les matériaux sont disponibles en 316L, 316L VAR et 316L VIM-VAR. La rugosité de la surface d''infiltration est de Ra5 μ in (0,13 μ m) à Ra15 μ in (0,4 μ m). Les spécifications du processus couvrent la norme (GP), la haute pureté (HP) et l''ultra-haute pureté (UHP). Plage de température de fonctionnement-198°C à 538°C.</p>', '<p>تم تصميم الوصلات الملحومة الطويلة من السلسلة B خصيصًا لخطوط أنابيب أشباه الموصلات فائقة النقاء ، مع معالجة دقيقة ونهايات مستقيمة وخالية من الاختباء ، مما يضمن مطابقة دقيقة لقطر الأنبوب. يحتوي كل موصل على شعار دائم قابل للتتبع.</p><p>المواد اختيارية 316L ، 316L VAR ، 316L VIM-VAR ، خشونة سطح التسلل Ra5μin (0.13μm) إلى Ra15μin (0.4μm)، وتغطي مواصفات العملية القياسية (GP)، والنقاء العالي (HP) والنقاء العالي للغاية (UHP). نطاق درجة حرارة التشغيل من -198℃ إلى 538℃.</p>', '["端部平直无毛刺，提高对准性", "100% 视觉检验，永久追溯标识", "内表面电解抛光 Ra5μin 可选", "316L VAR / VIM-VAR 材料可选", "GP / HP / UHP 三种工艺规范"]', '["Straight, burr-free ends improve alignment", "100% visual inspection, permanent traceability marking", "Inner surface electrolytic polishing Ra5μin optional", "316L VAR / VIM-VAR materials optional", "GP / HP / UHP three process specifications"]', '["バリのないまっすぐな端部でアライメントを向上", "100%目視検査、永久トレーサビリティマーク", "内面電解研磨 Ra5μin オプション", "316L VAR / VIM-VAR 材料オプション", "GP / HP / UHP の3つのプロセス仕様"]', '["버 없이 끝 부분이 평평하여 정렬 향상", "100% 시각 검사, 영구 추적 표시", "내면 전해 연마 Ra5μin 선택 사항", "316L VAR / VIM-VAR 소재 선택 사항", "GP / HP / UHP 3가지 공정 사양"]', '["Extrémités droites et sans bavures pour un alignement amélioré", "Inspection visuelle 100%, identité de traçabilité permanente", "Polissage électrolytique de la surface intérieure Ra5 μ in en option", "316L VAR/VIM-VAR Matériel facultatif", "GP/HP/UHP Trois spécifications de processus"]', '["نهاية مستقيمة وخالية من الاختباء ، محاذاة محسنة", "فحص بصري 100%، علامة تتبع دائمة", "تلميع كهربائي للسطح الداخلي Ra5μin اختياري", "مادة 316L VAR / VIM-VAR اختيارية", "GP / HP / UHP ثلاث مواصفات عملية"]', NULL, NULL, NULL, false, '/uploads/oem/BE.jpg', NULL, NULL, NULL, NULL, NULL, NULL, 1, NULL, NULL, NULL, NULL, NULL, NULL, '[{"name": "形式", "value": "直通、45°/90°弯头、三通、四通等 11 种", "nameAr": "شكل", "nameEn": "Form", "nameFr": "Formulaire", "nameJa": "フォーム", "nameKo": "형식", "valueAr": "11 نوعًا من خلال ، 45 درجة/90 درجة الكوع ، تي اتجاه ، رباعي اتجاه ، إلخ.", "valueEn": "11 types, including straight-through, 45°/90° elbow, three-way, and four-way", "valueFr": "11 types de coude droit, 45°/90°, tee, quatre voies, etc.", "valueJa": "スルー、45°/90°エルボ、ティー、4ウェイなど11種類", "valueKo": "스루, 45°/90° 엘보, 티, 4방향 등 11종"}, {"name": "工作压力", "value": "按规格最高 8500psig", "nameAr": "ضغط العمل", "nameEn": "working pressure", "nameFr": "Pression de travail", "nameJa": "仕事のストレス", "nameKo": "업무 스트레스", "valueAr": "حسب المواصفات حتى 8500 رطل لكل بوصة مربعة", "valueEn": "Maximum 8500psig per specification", "valueFr": "Jusqu''à 8500psig par spécification", "valueJa": "スペックで最大 8500psig", "valueKo": "사양별 최대 8500psig"}, {"name": "材料", "value": "316L / 316L VAR / 316L VIM-VAR", "nameAr": "المواد", "nameEn": "Material", "nameFr": "Matériel", "nameJa": "素材", "nameKo": "재료", "valueAr": "316L / 316L فار / 316L فيم-فار", "valueEn": "316L/316L VAR/316L VIM-VAR", "valueFr": "316L/316L VAR/316L VIM-VAR", "valueJa": "316L / 316L VAR / 316L VIM-VAR", "valueKo": "316L / 316L VAR / 316L VIM-VAR"}, {"name": "表面粗糙度", "value": "Ra5 ~ Ra15μin", "nameAr": "خشونة السطح", "nameEn": "surface roughness", "nameFr": "Rugosité de surface", "nameJa": "表面粗さ", "nameKo": "표면 거칠기", "valueAr": "Ra5 ~ Ra15μin", "valueEn": "Ra5~Ra15μin", "valueFr": "Ra5~ Ra15 μ In", "valueJa": "Ra5 ~ Ra15μin", "valueKo": "Ra5 ~ Ra15μin"}, {"name": "工作温度", "value": "-198℃ ~ 538℃", "nameAr": "درجة حرارة العمل", "nameEn": "Operating temperature", "nameFr": "Température de fonctionnement", "nameJa": "動作温度", "nameKo": "작동 온도", "valueAr": "-198℃~538℃", "valueEn": "-198℃~538℃", "valueFr": "-198℃ ~538℃", "valueJa": "-198℃~538℃", "valueKo": "-198℃~538℃"}]', 26, 'published', '2026-09-08 18:51:45.299', '2026-09-08 18:51:45.299', '2026-09-08 18:51:45.299', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO public.products ("siteId", id, "tabId", "categoryId", slug, model, name, "nameEn", "nameJa", "nameKo", "nameFr", "nameAr", subtitle, "subtitleEn", "subtitleJa", "subtitleKo", "subtitleFr", "subtitleAr", summary, "summaryEn", "summaryJa", "summaryKo", "summaryFr", "summaryAr", description, "descriptionEn", "descriptionJa", "descriptionKo", "descriptionFr", "descriptionAr", features, "featuresEn", "featuresJa", "featuresKo", "featuresFr", "featuresAr", images, price, "priceTiers", "isParts", "coverImage", video, frames360, "manualUrl", "priceMin", "priceMax", "priceUnit", moq, "priceNote", "priceNoteEn", "priceNoteJa", "priceNoteKo", "priceNoteFr", "priceNoteAr", specs, "sortOrder", status, "publishedAt", "createdAt", "updatedAt", "seoTitle", "seoTitleJa", "seoTitleKo", "seoTitleFr", "seoTitleAr", "seoTitleEn", "seoDescription", "seoDescriptionJa", "seoDescriptionKo", "seoDescriptionFr", "seoDescriptionAr", "seoDescriptionEn", "seoKeywords", "seoKeywordsJa", "seoKeywordsKo", "seoKeywordsFr", "seoKeywordsAr", "seoKeywordsEn", "geoRegion", "geoCity") VALUES (NULL, 27, 35, 7, 'o-ring-face-seal-o-series', '316L-OJ-OR Series', 'O 形圈面密封接头 O 系列', 'O-Ring Face Seal Connector O Series', 'Oリング面シール継手Oシリーズ', 'O-링 표면 씰 조인트 O 시리즈', 'Joint d''étanchéité de surface torique série O', 'ختم وجه الحلقة O سلسلة O', 'O 形圈密封，真空至高压可靠密封', 'O-ring seal for reliable sealing from vacuum to high pressure', 'O リング シール、真空から高圧までの信頼性の高いシール', 'O-링 씰, 진공에서 고압까지 신뢰할 수 있는 씰', 'Joint torique, joint fiable sous vide à haute pression', 'ختم حلقة O ، ختم موثوق به من الفراغ إلى الضغط العالي', 'O 系列 O 形圈面密封接头，O 形圈保证从真空到高压的完美密封，尺寸范围 1/8" 至 1"。螺母端测试孔便于泄漏测试，内螺纹螺母镀银，标准表面粗糙度 Ra10μin。可选多种 O 形圈材料以适应不同温度与介质。', 'O-Series O-Ring Face Seal Connectors, O-Rings ensure perfect sealing from vacuum to high pressure, size range 1/8" to 1". The nut end test hole facilitates leak testing, the internal threaded nut is silver-plated, and the standard surface roughness is Ra10μin. A variety of O-ring materials are available to accommodate different temperatures and media.', 'O シリーズ O リング フェース シール ジョイント、O リングは真空から高圧まで完璧なシールを保証し、サイズは 1/8 インチから 1 インチです。ナット端のテスト穴は漏れ試験を容易にし、雌ネジナットは銀メッキされており、標準表面粗さはRa10μinです。さまざまな温度や媒体に合わせて、さまざまな O リング材料を選択できます。', 'O 시리즈 O-링 페이스 씰 피팅, O-링은 진공에서 고압까지 완벽한 밀봉을 보장하며 크기는 1/8"에서 1"입니다. 누출 테스트를 위한 너트 끝 테스트 구멍, 암나사 너트는 은 도금, 표준 표면 거칠기 Ra10μin입니다. 다양한 온도와 매체에 맞게 다양한 O-링 재료를 사용할 수 있습니다.', 'Joint d''étanchéité de surface à bague torique série O, la bague torique garantit une étanchéité parfaite du vide à la haute pression, dans une plage de tailles de 1/8 "à 1". Les trous d''essai à l''extrémité de l''écrou facilitent les tests de fuite, les écrous filetés internes sont plaqués argent et la rugosité de surface standard est Ra10 μ in. Une variété de matériaux toriques sont disponibles pour s''adapter à différentes températures et milieux.', 'وصلات ختم وجه الحلقة O من سلسلة O ، تضمن الحلقات O إغلاقًا مثاليًا من الفراغ إلى الضغط العالي ، بأحجام تتراوح من 1/8 بوصة إلى 1 بوصة. فتحات اختبار نهاية الصامولة تسهل اختبار التسرب ، والصامولة الأنثوية مطلية بالفضة ، وخشونة السطح القياسية Ra10μin. تتوفر مجموعة متنوعة من مواد الحلقة O لاستيعاب درجات الحرارة والوسائط المختلفة.', '<p>O 系列面密封接头采用 O 形圈密封，保证从真空到高压的可靠密封性能；与接管光滑连接确保良好密封。每个接头使用氦气进行泄漏测试，最大允许泄漏率 4x10⁻⁹ stdcm³/s。</p><p>O 形圈可选 FKM（70/90 硬度）、PTFE、丁腈橡胶、全氟橡胶、乙丙橡胶，工作温度 -45℃ 至 287℃。内螺纹螺母镀银，易于安装与维护。</p>', '<p>The O-series face sealing joints use O-ring seals to ensure reliable sealing performance from vacuum to high pressure; A smooth connection with the nozzle ensures a good seal. Each connector was leak tested using helium with a maximum allowable leak rate of 4x10⁻⁹ stdcm³/s.</p><p>O-rings are available in FKM (70/90 hardness), PTFE, nitrile rubber, perfluorine rubber, and ethylene propylene rubber, with operating temperatures ranging from -45℃ to 287℃. The internal thread nuts are silver-plated, making them easy to install and maintain.</p>', '<p>O シリーズ フェース シール ジョイントは O リング シールを採用しており、真空から高圧まで信頼性の高いシール性能を保証します。ノズルとの滑らかな接続により、良好なシールが保証されます。各継手はヘリウムガスを使用して漏れ試験を行い、最大許容漏れ速度は 4x10⁻⁺ stdcm³/s です。</p><p>O リングは FKM (硬度 70/90)、PTFE、ニトリルゴム、パーフルオロゴム、エチレンプロピレンゴムから選択でき、動作温度は -45℃ ~ 287℃ です。メスネジナットは銀メッキされており、取り付けとメンテナンスが簡単です。</p>', '<p>O 시리즈 페이스 씰 조인트는 O 링 씰을 사용하여 진공에서 고압까지 신뢰할 수 있는 씰링 성능을 보장합니다. 노즐과의 부드러운 연결은 좋은 밀봉을 보장합니다. 각 피팅은 헬륨 가스를 사용하여 누출 테스트를 실시했으며 최대 허용 누출 속도는 4x10⁻⁺ stdcm³/s입니다.</p><p>O 링은 선택 FKM (70/90 경도), PTFE, NBR, PFR, 에틸렌 프로필렌 고무, 작동 온도 -45℃에서 287℃. 암나사 너트는 실버 도금으로 되어 있어 설치와 유지 관리가 쉽습니다.</p>', '<p>Le joint d''étanchéité de surface de la série O adopte un joint torique pour garantir des performances d''étanchéité fiables du vide à la haute pression; La liaison lisse avec le tube assure une bonne étanchéité. Chaque joint a été testé en hélium avec un taux de fuite maximum admissible de 4x10⁻⁶ stdcm³/s.</p><p>FKM (dureté 70/90), PTFE, caoutchouc nitrile, caoutchouc perfluoré, caoutchouc éthylène-propylène sont disponibles pour la bague torique et la température de fonctionnement est de-45 ℃ à 287 ℃. L''écrou fileté femelle est plaqué argent, facile à installer et à entretenir.</p>', '<p>يتم إغلاق وصلات ختم الوجه من سلسلة O بحلقة O لضمان أداء ختم موثوق به من الفراغ إلى الضغط العالي ؛ الاتصال السلس مع الفوهة يضمن ختم جيد. يتم اختبار كل وصلة للتسرب باستخدام الهيليوم بحد أقصى للتسرب المسموح به هو 4x10⁻⁺ stdcm³/s.</p><p>O-ring اختياري FKM (70/90 صلابة)، PTFE ، مطاط النتريل ، مطاط البيرفلور ، مطاط الإيثيلين بروبيلين ، درجة حرارة التشغيل من -45 درجة مئوية إلى 287 درجة مئوية. الجوز الأنثوي مطلي بالفضة لسهولة التركيب والصيانة.</p>', '["O 形圈密封，真空至高压", "螺母端测试孔便于泄漏测试", "内螺纹螺母镀银", "氦气泄漏测试 4x10⁻⁹ stdcm³/s", "尺寸范围 1/8\" 至 1\""]', '["O-ring seal, vacuum to high pressure", "Nut end test hole for easy leak testing", "Internal threaded nut silver plated", "Helium leak test 4x10⁻⁹ stdcm³/s", "Size range 1/8\" to 1\""]', '["O リング シール、真空から高圧", "漏れ試験を容易にするナット端のテスト穴", "雌ネジナットは銀メッキ", "ヘリウム漏れ試験 4x10⁻⁺ stdcm³/s", "サイズ範囲 1/8\" ~ 1\""]', '["O-링 씰, 진공에서 고압까지", "누출 테스트를 용이하게 하는 너트 끝 테스트 구멍", "암나사 너트는 은 도금", "헬륨 누출 테스트 4x10⁻⁺ stdcm³/s", "크기 범위 1/8\" ~ 1\""]', '["Joint torique, sous vide à haute pression", "Trou d''essai à l''extrémité de l''écrou pour un essai de fuite facile", "Écrou fileté femelle plaqué argent", "Essai de fuite d''hélium 4x10⁻⁶ stdcm³/s", "Gamme de tailles 1/8 \"à 1\""]', '["ختم حلقة O ، فراغ إلى الضغط العالي", "فتحة اختبار نهاية الجوز لسهولة اختبار التسرب", "الصامولة الأنثوية مطلية بالفضة", "اختبار تسرب الهيليوم 4x10⁻⁺ stdcm³/s", "نطاق الحجم من 1/8 بوصة إلى 1 بوصة"]', NULL, NULL, NULL, false, '/uploads/oem/GG_1.jpg', NULL, NULL, NULL, NULL, NULL, NULL, 1, NULL, NULL, NULL, NULL, NULL, NULL, '[{"name": "工作压力", "value": "最高 11200psig", "nameAr": "ضغط العمل", "nameEn": "working pressure", "nameFr": "Pression de travail", "nameJa": "仕事のストレス", "nameKo": "업무 스트레스", "valueAr": "ما يصل إلى 11200 رطل لكل بوصة مربعة", "valueEn": "Maximum 11200psig", "valueFr": "Jusqu''à 11200psig", "valueJa": "最大 11200psig", "valueKo": "최대 11200psig"}, {"name": "O 形圈材料", "value": "FKM / PTFE / 丁腈 / 全氟 / 乙丙", "nameAr": "مادة O-ring", "nameEn": "O-ring material", "nameFr": "Matériau de bague torique", "nameJa": "Oリング材料", "nameKo": "O-링 재료", "valueAr": "فكم / بتف / نيتريل / بيرفلور / إيثيلين بروبيلين", "valueEn": "FKM/PTFE / Nitrile / Perfluorine / Ethylene-propylene", "valueFr": "FKM/PTFE /butyronitrile/perfluor/éthylène-propylène", "valueJa": "FKM / PTFE/ ニトリル / パーフルオロ / エチレンプロピレン", "valueKo": "FKM / PTFE / 니트릴 / 퍼플루오로 / 에틸렌프로필렌"}, {"name": "工作温度", "value": "-45℃ ~ 287℃（视 O 形圈）", "nameAr": "درجة حرارة العمل", "nameEn": "Operating temperature", "nameFr": "Température de fonctionnement", "nameJa": "動作温度", "nameKo": "작동 온도", "valueAr": "-45 درجة مئوية ~ 287 درجة مئوية (حلقة O بصرية)", "valueEn": "-45℃ ~ 287℃ (Optical O-ring)", "valueFr": "-45℃ ~287℃ (voir la bague torique)", "valueJa": "-45℃ ~ 287℃ (Oリングを见る)", "valueKo": "-45℃ ~ 287℃ (오링 보기)"}, {"name": "泄漏率", "value": "≤ 4x10⁻⁹ stdcm³/s（氦）", "nameAr": "معدل التسرب", "nameEn": "leakage rate", "nameFr": "Taux de fuite", "nameJa": "漏れ率", "nameKo": "누출율", "valueAr": "≤ 4x10⁻⁺ stdcm³/s (الهيليوم)", "valueEn": "≤ 4x10⁻⁹ stdcm³/s (helium)", "valueFr": "≤4x10⁻⁶ stdcm³/s (hélium)", "valueJa": "≤ 4x10⁻⁺ stdcm³/s (ヘリウム)", "valueKo": "≤ 4x10⁻⁺ stdcm³/s (헬륨)"}, {"name": "材料", "value": "316L / 316SS", "nameAr": "المواد", "nameEn": "Material", "nameFr": "Matériel", "nameJa": "素材", "nameKo": "재료", "valueAr": "316L / 316SS", "valueEn": "316L/316SS", "valueFr": "316L/316SS", "valueJa": "316L / 316SS", "valueKo": "316L / 316SS"}]', 27, 'published', '2026-09-08 18:51:45.304', '2026-09-08 18:51:45.304', '2026-09-08 18:51:45.304', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO public.products ("siteId", id, "tabId", "categoryId", slug, model, name, "nameEn", "nameJa", "nameKo", "nameFr", "nameAr", subtitle, "subtitleEn", "subtitleJa", "subtitleKo", "subtitleFr", "subtitleAr", summary, "summaryEn", "summaryJa", "summaryKo", "summaryFr", "summaryAr", description, "descriptionEn", "descriptionJa", "descriptionKo", "descriptionFr", "descriptionAr", features, "featuresEn", "featuresJa", "featuresKo", "featuresFr", "featuresAr", images, price, "priceTiers", "isParts", "coverImage", video, frames360, "manualUrl", "priceMin", "priceMax", "priceUnit", moq, "priceNote", "priceNoteEn", "priceNoteJa", "priceNoteKo", "priceNoteFr", "priceNoteAr", specs, "sortOrder", status, "publishedAt", "createdAt", "updatedAt", "seoTitle", "seoTitleJa", "seoTitleKo", "seoTitleFr", "seoTitleAr", "seoTitleEn", "seoDescription", "seoDescriptionJa", "seoDescriptionKo", "seoDescriptionFr", "seoDescriptionAr", "seoDescriptionEn", "seoKeywords", "seoKeywordsJa", "seoKeywordsKo", "seoKeywordsFr", "seoKeywordsAr", "seoKeywordsEn", "geoRegion", "geoCity") VALUES (NULL, 28, 35, 7, 'cf-flange-weld-fitting', '316L-CF16-TB4 Series', 'CF 法兰焊接接头', 'CF Flange Weld Joint', 'CF フランジ溶接継手', 'CF 플랜지 용접 조인트', 'Joint soudé à bride CF', 'وصلات لحام شفة CF', 'CF 法兰转对焊 / 波纹管连接', 'CF flange butt welding / bellows connection', 'CFフランジから突合せ溶接/ベローズ接続', 'CF 플랜지 - 버트 용접 / 벨로우 연결', 'Bride CF au soudage à butte/raccordement soufflet', 'CF شفة إلى لحام بعقب / وصلة منفاخ', 'CF 法兰焊接接头，CF16 / CF25 / CF40 法兰与对焊接管、波纹管组合，金属垫片密封，适用于超高真空与超高纯工艺系统，提供法兰转 1/4"-1/2" 对焊及波纹管等多种形式。', 'CF flange welded joints, CF16 / CF25 / CF40 flanges are combined with butt welded pipes and bellows, sealed with metal gaskets. They are suitable for ultra-high vacuum and ultra-high purity process systems and offer various forms such as flange rotation 1/4"-1/2" butt welding and bellows.', 'CF フランジ溶接継手、CF16/CF25/CF40 フランジと突合せ溶接パイプ、コルゲートパイプの組み合わせ、金属ガスケットシール、超高真空および超高純度プロセスシステムに適しており、フランジから 1/4"-1/2"を提供します。突合せ溶接やコルゲートパイプなどのさまざまな形式。', 'CF 플랜지 용접 조인트, CF16/CF25/CF40 플랜지와 버트 용접 파이프, 벨로우 조합, 금속 개스킷 밀봉, 초고진공 및 초고순도 공정 시스템에 적합, 플랜지에서 1/4"-1/2" 버트 용접 및 벨로우 및 기타 형태.', 'Joint soudé à bride CF, bride CF16/CF25/CF40 combinée avec tuyau soudé à butte et soufflet, joint de joint métallique, adapté aux systèmes de processus à ultra-haut vide et à ultra-haute pureté, fournissant une rotation de bride 1/4 "-1/2" Diverses formes telles que le soudage à butte et le soufflet.', 'وصلة ملحومة بشفة CF ، شفة CF16 / CF25 / CF40 مدمجة مع أنابيب ملحومة بعقب وأنابيب مموجة ، مختومة بحشية معدنية ، مناسبة لأنظمة معالجة الفراغ العالي للغاية والنقاء العالي للغاية ، وتوفير شفة إلى 1/4 "-1/2" اللحام بعقب والمنفاخ وأشكال أخرى.', '<p>CF 法兰焊接接头为超高真空与超高纯工艺系统提供可靠金属密封连接，法兰面精度高，配合对焊接管、波纹管实现灵活布局。</p><p>材料 316L，可选 CF16、CF25、CF40 法兰规格，焊接端适配 1/4"、3/8"、1/2" 英制管与 6-12mm 公制管。</p>', '<p>CF flange welded joints provide reliable metal sealing connections for ultra-high vacuum and ultra-high purity process systems. They offer high flange surface precision and allow for flexible layout of welded pipes and bellows.</p><p>Material 316L, optional CF16, CF25, CF40 flange specifications, welded end compatible with 1/4", 3/8", 1/2" Imperial pipes and 6-12mm metric pipes.</p>', '<p>CFフランジ溶接継手は超高真空と超高純度プロセスシステムに信頼性の高い金属シール接続を提供し、フランジ面の精度が高く、突き合わせ溶接管、ベローズと協力して柔軟なレイアウトを実現します。</p><p>材質 316L、オプションの CF16、CF25、CF40 フランジ仕様、溶接端は 1/4 インチ、3/8 インチ、1/2 インチ チューブと 6 ~ 12mm メートル チューブに適合します。</p>', '<p>CF 플랜지 용접 조인트는 초고진공 및 초고순도 공정 시스템에 신뢰할 수 있는 금속 밀봉 연결을 제공하며, 플랜지 표면의 정밀도가 높고, 접합 용접 파이프, 벨로우와 협력하여 유연한 레이아웃을 실현한다.</p><p>물자 316L, 선택적 CF16, CF25, CF40 플랜지 사양, 용접 끝은 1/4", 3/8", 1/2" 인치 파이프와 6-12mm 미터 파이프에 적합합니다.</p>', '<p>Les joints soudés à brides CF fournissent des connexions d''étanchéité métalliques fiables pour les systèmes de processus à vide ultra-haut et à pureté ultra-haute. La surface de la bride a une précision élevée et coopère avec des tuyaux soudés et des soufflets pour obtenir une disposition flexible.</p><p>Matériau 316L, spécifications de bride CF16, CF25, CF40 optionnelles, extrémité soudée adaptée aux tuyaux imperiaux 1/4 ", 3/8", 1/2 "et aux tuyaux métriques 6-12 mm.</p>', '<p>توفر الوصلات الملحومة بشفة CF اتصالات مانعة للتسرب معدنية موثوقة لأنظمة معالجة الفراغ العالي للغاية والنقاء العالي للغاية ، ويتميز سطح الحافة بدقة عالية ويمكنه تحقيق تخطيط مرن مع الأنابيب الملحومة والمنفاخ.</p><p>المواد 316L ، مواصفات شفة اختيارية CF16 ، CF25 ، CF40 ، نهاية ملحومة مناسبة لأنابيب بوصة مقاس 1/4 بوصة ، 3/8 بوصة ، 1/2 بوصة وأنابيب مترية مقاس 6-12 مم.</p>', '["CF 金属垫片密封", "法兰转对焊 / 波纹管", "316L 材料", "超高真空兼容"]', '["CF Metal Gasket Seal", "Flange Butt Weld / Bellows", "316L Material", "Ultra High Vacuum Compatible"]', '["CF 金属ガスケットシール", "フランジから突合せ溶接/ベローズ", "316L 材料", "超高真空対応"]', '["CF 금속 개스킷 씰", "플랜지 - 버트 용접 / 벨로우즈", "316L 소재", "초고진공 호환"]', '["Joint de joint métallique CF", "Bride à soudage à butte/soufflet", "Matériel 316L", "Compatible avec ultra-haut vide"]', '["ختم حشية معدنية CF", "لحام شفة إلى بعقب / أنبوب مموج", "مادة 316L", "متوافق مع فراغ عالي للغاية"]', NULL, NULL, NULL, false, '/uploads/oem/GJ_1.jpg', NULL, NULL, NULL, NULL, NULL, NULL, 1, NULL, NULL, NULL, NULL, NULL, NULL, '[{"name": "法兰规格", "value": "CF16 / CF25 / CF40", "nameAr": "مواصفات شفة", "nameEn": "flange specification", "nameFr": "Spécifications des brides", "nameJa": "フランジ仕様", "nameKo": "플랜지 사양", "valueAr": "CF16 / CF25 / CF40", "valueEn": "CF16 / CF25 / CF40", "valueFr": "CF16/CF25/CF40", "valueJa": "CF16/CF25/CF40", "valueKo": "CF16/CF25/CF40"}, {"name": "焊接端", "value": "1/4\" ~ 1/2\" 对焊、波纹管", "nameAr": "نهاية اللحام", "nameEn": "welded end", "nameFr": "extrémité soudée", "nameJa": "溶接端", "nameKo": "용접 끝", "valueAr": "1/4 \"~ 1/2\" لحام بعقب ، منفاخ", "valueEn": "1/4\" ~ 1/2\" butt welding, corrugated pipe", "valueFr": "Soudage à butte 1/4 \"~1/2\", soufflet", "valueJa": "1/4\" ~ 1/2\" 突合せ溶接、ベローズ", "valueKo": "1/4\" ~ 1/2\" 버트 용접, 벨로우즈"}, {"name": "材料", "value": "316L", "nameAr": "المواد", "nameEn": "Material", "nameFr": "Matériel", "nameJa": "素材", "nameKo": "재료", "valueAr": "316 لتر", "valueEn": "316L", "valueFr": "316L", "valueJa": "316L", "valueKo": "316L"}, {"name": "密封形式", "value": "金属垫片", "nameAr": "نموذج الختم", "nameEn": "sealed form", "nameFr": "Forme scellée", "nameJa": "シールフォーム", "nameKo": "밀봉 형태", "valueAr": "حشية معدنية", "valueEn": "metal gasket", "valueFr": "Joints métalliques", "valueJa": "金属ガスケット", "valueKo": "금속 개스킷"}]', 28, 'published', '2026-09-08 18:51:45.305', '2026-09-08 18:51:45.305', '2026-09-08 18:51:45.305', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO public.products ("siteId", id, "tabId", "categoryId", slug, model, name, "nameEn", "nameJa", "nameKo", "nameFr", "nameAr", subtitle, "subtitleEn", "subtitleJa", "subtitleKo", "subtitleFr", "subtitleAr", summary, "summaryEn", "summaryJa", "summaryKo", "summaryFr", "summaryAr", description, "descriptionEn", "descriptionJa", "descriptionKo", "descriptionFr", "descriptionAr", features, "featuresEn", "featuresJa", "featuresKo", "featuresFr", "featuresAr", images, price, "priceTiers", "isParts", "coverImage", video, frames360, "manualUrl", "priceMin", "priceMax", "priceUnit", moq, "priceNote", "priceNoteEn", "priceNoteJa", "priceNoteKo", "priceNoteFr", "priceNoteAr", specs, "sortOrder", status, "publishedAt", "createdAt", "updatedAt", "seoTitle", "seoTitleJa", "seoTitleKo", "seoTitleFr", "seoTitleAr", "seoTitleEn", "seoDescription", "seoDescriptionJa", "seoDescriptionKo", "seoDescriptionFr", "seoDescriptionAr", "seoDescriptionEn", "seoKeywords", "seoKeywordsJa", "seoKeywordsKo", "seoKeywordsFr", "seoKeywordsAr", "seoKeywordsEn", "geoRegion", "geoCity") VALUES (NULL, 29, 37, 9, 'dv3-low-pressure-high-flow', '316L-DV3 Series', '低压大流量隔膜阀', 'low-pressure high-flow diaphragm valve', '低圧大流量ダイヤフラムバルブ', '저압 대유량 다이어프램 밸브', 'Vanne à membrane basse pression et grand débit', 'صمام الحجاب الحاجز ذو الضغط المنخفض', '低压大流量，CV 2.8', 'Low voltage, high flow, CV 2.8', '低圧大流量、CV 2.8', '낮은 압력과 큰 흐름, CV 2.8', 'Basse pression et débit élevé, CV 2.8', 'ضغط منخفض وتدفق كبير ، السيرة الذاتية 2.8', 'DV3 系列低压大流量隔膜阀，工作压力最高 1.72MPa，流量系数 CV 2.8。全封闭阀座设计具有优越的抗膨胀和防污染能力，内部无螺纹和弹簧，可完全清扫流道，钴镍合金隔膜提高强度和抗腐蚀性，适用于超高纯气体大流量输送。', 'The DV3 series low-pressure, high-flow diaphragm valves have a maximum working pressure of 1.72MPa and a flow coefficient of CV 2.8. The fully enclosed valve seat design has superior anti-expansion and anti-contamination capabilities. It has no internal threads or springs and can completely clean the flow channel. The cobalt-nickel alloy diaphragm improves strength and corrosion resistance, making it suitable for high-flow transport of ultra-high purity gas.', 'DV3 シリーズ低圧大流量ダイヤフラムバルブ、最大作動圧力 1.72MPa、流量係数 CV 2.8。完全に密閉されたシート設計は優れた耐膨張性と耐汚染性を備えており、内部にはねじ山やばねがなく、流路を完全に掃除でき、コバルトニッケル合金ダイヤフラムは強度と耐食性を向上させ、超高純度ガスの大流量輸送に適しています。', 'DV3 시리즈 저압 대유량 다이어프램 밸브, 최대 작동 압력 1.72MPa, 유량 계수 CV 2.8. 완전히 밀폐된 밸브 시트 디자인은 우수한 팽창 방지 및 오염 방지 기능을 갖추고 있으며, 내부에는 나사산과 스프링이 없어 유동 채널을 완전히 청소할 수 있으며, 코발트 니켈 합금 다이어프램은 강도와 부식 저항을 향상시키고 초고순도', 'Vanne à membrane basse pression et grand débit série DV3, pression de fonctionnement maximale de 1,72 MPa, coefficient de débit CV 2,8. La conception du siège de vanne entièrement fermé présente des capacités anti-dilatation et anti-pollution supérieures. Il n''y a pas de filetage et de ressort à l''intérieur, ce qui peut nettoyer complètement le canal d''écoulement. Le diaphragme en alliage cobalt-nickel améliore la résistance et la résistance à la corrosion et convient au transport à grand débit de gaz ultra-haute pureté.', 'صمامات الحجاب الحاجز ذات الضغط المنخفض والتدفق الكبير من سلسلة DV3 مع ضغط عمل يصل إلى 1.72MPa ومعامل تدفق CV 2.8. يتميز تصميم المقعد المغلق بالكامل بقدرة فائقة على مقاومة التوسع والتلوث ، ولا يوجد خيوط ونوابض داخلية ، يمكنها تنظيف قناة التدفق بالكامل ، وغشاء سبائك الكوبالت والنيكل يحسن القوة ومقاومة التآكل ، وهو مناسب لنقل التدفق الكبير للغاز عالي النقاء.', '<p>DV3 系列低压大流量隔膜阀内部容积小、极少颗粒生成，全封闭阀座设计具有优越的抗膨胀和防污染能力。内部无螺纹和弹簧，可完全清扫流道。</p><p>钴镍合金隔膜提高强度和抗腐蚀性，使用寿命长。手动或气动类型可选，适用于超高纯应用。</p>', '<p>The DV3 series low-pressure, high-flow diaphragm valves have a small internal volume, minimal particle formation, and a fully enclosed valve seat design with superior anti-expansion and anti-contamination capabilities. There are no threads or springs inside, and the flow channel can be completely cleaned.</p><p>Cobalt-nickel alloy diaphragm improves strength and corrosion resistance, and has a long service life. Manual or pneumatic types are available for ultra-high purity applications.</p>', '<p>DV3 シリーズの低圧大流量ダイヤフラム バルブは、内部容積が小さく、粒子の発生がほとんどなく、完全に密閉されたシート設計により、優れた耐膨張性と耐汚染性を備えています。内部にはネジやスプリングがなく、ランナーを完全に掃除できます。</p><p>コバルトニッケル合金セパレータは強度と耐食性を向上させ、長寿命です。手動または空気圧タイプは、超高純度アプリケーションに適しています。</p>', '<p>DV3 시리즈 저압 대유량 다이어프램 밸브는 내부 부피가 작고 입자 생성이 거의 없으며 완전히 밀폐된 밸브 시트 설계는 우수한 팽창 및 오염 방지 기능을 제공합니다. 내부에는 나사산과 스프링이 없어 러너를 완전히 청소합니다.</p><p>코발트-니켈 합금 분리막은 강도와 내식성을 향상시키고 수명이 길다. 수동 또는 공압 유형은 초고순도 응용 프로그램을 위해 선택 사항입니다.</p>', '<p>Les vannes à membrane basse pression et grand débit de la série DV3 ont un petit volume interne, très peu de particules sont générées et la conception du siège entièrement fermée présente des capacités anti-expansion et anti-pollution supérieures. Sans filetage ni ressort à l''intérieur, le canal d''écoulement peut être complètement nettoyé.</p><p>Le séparateur en alliage cobalt-nickel améliore la résistance et la résistance à la corrosion et offre une longue durée de vie. Type manuel ou pneumatique disponible pour des applications ultra haute pureté.</p>', '<p>تتميز صمامات الحجاب الحاجز ذات الضغط المنخفض والتدفق الكبير من سلسلة DV3 بحجم داخلي صغير وتوليد عدد قليل جدًا من الجسيمات ، كما أن تصميم المقعد المغلق بالكامل يتميز بقدرات فائقة على مقاومة التمدد والتلوث. لا توجد خيوط أو نوابض داخلية لتنظيف قناة المتدفق بالكامل.</p><p>يحسن فاصل سبائك الكوبالت والنيكل القوة ومقاومة التآكل وله عمر خدمة طويل. نوع يدوي أو هوائي اختياري للتطبيقات فائقة النقاء.</p>', '["大流量 CV 2.8", "全封闭阀座设计", "内部无螺纹和弹簧", "钴镍合金隔膜", "手动 / 气动可选"]', '["High Flow CV 2.8", "Fully Enclosed Seat Design", "No Internal Threads and Springs", "Cobalt-Nickel Alloy Diaphragm", "Manual/Pneumatic Optional"]', '["大流量CV 2.8", "完全に密閉されたシート設計", "内部にねじやばねがない", "コバルトニッケル合金ダイヤフラム", "手動/空気圧オプション"]', '["큰 유량 CV 2.8", "완전 밀폐된 시트 설계", "내부 스레드 및 스프링 없음", "코발트 니켈 합금 다이어프램", "수동 / 공압 옵션"]', '["CV de débit élevé 2.8", "Conception de siège entièrement fermée", "Sans filetage et ressort à l''intérieur", "Séparateur en alliage cobalt-nickel", "Manuel/pneumatique en option"]', '["تدفق كبير CV 2.8", "تصميم مقعد مغلق بالكامل", "لا توجد خيوط أو نوابض داخلية", "غشاء من سبائك الكوبالت والنيكل", "يدوي / هوائي اختياري"]', NULL, NULL, NULL, false, '/uploads/oem/dv22a-mr8.jpg', NULL, NULL, NULL, NULL, NULL, NULL, 1, NULL, NULL, NULL, NULL, NULL, NULL, '[{"name": "工作压力", "value": "MAX. 1.72MPa", "nameAr": "ضغط العمل", "nameEn": "working pressure", "nameFr": "Pression de travail", "nameJa": "仕事のストレス", "nameKo": "업무 스트레스", "valueAr": "ماكس. 1.72 ميجا باسكال", "valueEn": "MAX. 1.72MPa", "valueFr": "MAX. 1,72 MPa", "valueJa": "マックス1.72MPa", "valueKo": "최대. 1.72MPa"}, {"name": "流量系数 CV", "value": "2.8", "nameAr": "معامل التدفق السيرة الذاتية", "nameEn": "Flow coefficient CV", "nameFr": "Coefficient de débit CV", "nameJa": "流量係数 CV", "nameKo": "유량 계수 CV", "valueAr": "2.8", "valueEn": "2.8", "valueFr": "2.8", "valueJa": "2.8", "valueKo": "2.8"}, {"name": "阀座材料", "value": "PCTFE / PFA", "nameAr": "مواد مقعد الصمام", "nameEn": "valve seat material", "nameFr": "Matériau du siège", "nameJa": "バルブシート材料", "nameKo": "밸브 시트 재료", "valueAr": "PCTFE / PFA", "valueEn": "PCTFE/PFA", "valueFr": "PCTFE/PFA", "valueJa": "PCTFE / PFA", "valueKo": "PCTFE / PFA"}, {"name": "工作温度", "value": "-23℃ ~ 150℃", "nameAr": "درجة حرارة العمل", "nameEn": "Operating temperature", "nameFr": "Température de fonctionnement", "nameJa": "動作温度", "nameKo": "작동 온도", "valueAr": "-23℃~150℃", "valueEn": "-23℃~150℃", "valueFr": "-23℃ ~150℃", "valueJa": "-23℃~150℃", "valueKo": "-23℃~150℃"}, {"name": "泄漏率", "value": "≤ 5x10⁻¹⁰ stdcm³/s（阀座 ≤ 1x10⁻⁹）", "nameAr": "معدل التسرب", "nameEn": "leakage rate", "nameFr": "Taux de fuite", "nameJa": "漏れ率", "nameKo": "누출율", "valueAr": "≤ 5x10⁻¹⁰ stdcm³/s (مقعد الصمام ≤ 1x10⁻⁺)", "valueEn": "≤ 5x10⁻¹⁰ stdcm³/s (valve seat ≤ 1x10⁻⁹)", "valueFr": "≤5x10⁻¹⁻⁰ stdcm³/s (siège ≤1x10⁻⁵)", "valueJa": "≤ 5x10⁻¹⁰ stdcm³/s (シート ≤ 1x10⁻⁰)", "valueKo": "≤ 5x10⁻¹⁰ stdcm³/s (밸브 시트 ≤ 1x10⁻⁺)"}]', 29, 'published', '2026-09-08 18:51:45.305', '2026-09-08 18:51:45.305', '2026-09-08 18:51:45.305', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO public.products ("siteId", id, "tabId", "categoryId", slug, model, name, "nameEn", "nameJa", "nameKo", "nameFr", "nameAr", subtitle, "subtitleEn", "subtitleJa", "subtitleKo", "subtitleFr", "subtitleAr", summary, "summaryEn", "summaryJa", "summaryKo", "summaryFr", "summaryAr", description, "descriptionEn", "descriptionJa", "descriptionKo", "descriptionFr", "descriptionAr", features, "featuresEn", "featuresJa", "featuresKo", "featuresFr", "featuresAr", images, price, "priceTiers", "isParts", "coverImage", video, frames360, "manualUrl", "priceMin", "priceMax", "priceUnit", moq, "priceNote", "priceNoteEn", "priceNoteJa", "priceNoteKo", "priceNoteFr", "priceNoteAr", specs, "sortOrder", status, "publishedAt", "createdAt", "updatedAt", "seoTitle", "seoTitleJa", "seoTitleKo", "seoTitleFr", "seoTitleAr", "seoTitleEn", "seoDescription", "seoDescriptionJa", "seoDescriptionKo", "seoDescriptionFr", "seoDescriptionAr", "seoDescriptionEn", "seoKeywords", "seoKeywordsJa", "seoKeywordsKo", "seoKeywordsFr", "seoKeywordsAr", "seoKeywordsEn", "geoRegion", "geoCity") VALUES (NULL, 30, 37, 9, 'dv4-high-pressure-low-flow', '316L-DV4 Series', '高压小流量隔膜阀', 'high-pressure low-flow diaphragm valve', '高圧小流量ダイヤフラムバルブ', '고압 소유량 다이어프램 밸브', 'Vanne à membrane haute pression et petit débit', 'ارتفاع الضغط صمام الحجاب الحاجز صغير التدفق', '高压 20.7MPa，小流量 CV 0.26', 'High pressure 20.7MPa, low flow CV 0.26', '高圧20.7MPa、小流量CV 0.26', '고압 20.7MPa, 작은 유량 CV 0.26', 'Haute pression 20,7 MPa, petit débit CV 0,26', 'الضغط العالي 20.7 ميجا باسكال ، تدفق صغير CV 0.26', 'DV4 系列高压小流量隔膜阀，工作压力最高 20.7MPa（3000psig），流量系数 CV 0.26。全封闭阀座设计，内部无螺纹和弹簧，钴镍合金隔膜，内通径 4.1mm，适用于高压高纯气体精密控制。', 'DV4 series high-pressure low-flow diaphragm valves, with a maximum operating pressure of 20.7MPa (3000psig) and a flow coefficient of CV 0.26. Fully enclosed valve seat design, no internal threads or springs, cobalt-nickel alloy diaphragm, internal diameter 4.1mm, suitable for precise control of high-pressure and high-purity gases.', 'DV4 シリーズ高圧小流量ダイヤフラムバルブ、最大動作圧力 20.7MPa (3000psig)、流量係数 CV 0.26。完全に密閉されたバルブシート設計、内部にネジやスプリングがなく、コバルトニッケル合金ダイヤフラム、内径4.1mm、高圧高純度ガスの精密制御に適しています。', 'DV4 시리즈 고압 소유량 다이어프램 밸브, 최대 작동 압력 20.7MPa(3000psig), 유량 계수 CV 0.26. 내부에 나사산 및 스프링이 없는 완전히 밀폐된 밸브 시트 설계, 코발트-니켈 합금 다이어프램, 내부 직경 4.1mm, 고압 및 고순도 가스의 정밀 제어에 적합합니다.', 'Vanne à membrane haute pression et faible débit série DV4, pression de fonctionnement maximale de 20,7 MPa (3000 psig), coefficient de débit CV 0,26. Conception de siège de vanne entièrement fermée, sans filetage ni ressort à l''intérieur, diaphragme en alliage cobalt-nickel, diamètre intérieur de 4,1 mm, adapté au contrôle de précision des gaz haute pression et haute pureté.', 'صمامات الحجاب الحاجز ذات الضغط العالي والتدفق الصغير من سلسلة DV4 مع ضغط عمل يصل إلى 20.7 ميجا باسكال (3000 رطل لكل بوصة مربعة) ومعامل تدفق CV 0.26. تصميم مقعد مغلق بالكامل ، بدون خيوط ونوابض داخلية ، غشاء من سبائك الكوبالت والنيكل ، قطر داخلي 4.1 مم ، مناسب للتحكم الدقيق في الغاز عالي الضغط وعالي النقاء.', '<p>DV4 系列高压小流量隔膜阀内部容积小、极少颗粒生成，全封闭阀座设计具有优越的抗膨胀和防污染能力。内部无螺纹和弹簧，可完全清扫流道。</p><p>钴镍合金隔膜提高强度和抗腐蚀性。PCTFE 或 PI 阀座可选，手动或气动类型可选，适用于超高纯高压应用。</p>', '<p>The DV4 series high-pressure low-flow diaphragm valves have a small internal volume and minimal particle formation, and the fully enclosed valve seat design has superior anti-expansion and anti-contamination capabilities. There are no threads or springs inside, and the flow channel can be completely cleaned.</p><p>Cobalt-nickel alloy diaphragm improves strength and corrosion resistance. Optional PCTFE or PI seats, manual or pneumatic types for ultra-high pure high pressure applications.</p>', '<p>DV4 シリーズの高圧小流量ダイヤフラム バルブは、内部容積が小さく、粒子の発生がほとんどなく、完全に密閉されたシート設計により、優れた耐膨張性と耐汚染性を備えています。内部にはネジやスプリングがなく、ランナーを完全に掃除できます。</p><p>コバルトニッケル合金セパレータは、強度と耐食性を向上させます。PCTFE または PI シートはオプションで、超高純度高圧アプリケーションに適した手動または空気圧タイプも利用できます。</p>', '<p>DV4 시리즈 고압 소유량 다이어프램 밸브는 내부 부피가 작고 입자 생성이 거의 없으며 완전히 밀폐된 밸브 시트 설계는 우수한 팽창 및 오염 방지 기능을 제공합니다. 내부에는 나사산과 스프링이 없어 러너를 완전히 청소합니다.</p><p>코발트-니켈 합금 분리막은 강도와 내식성을 향상시킨다. PCTFE 또는 PI 시트 옵션, 수동 또는 공압 유형 옵션, 초고순도 고압 애플리케이션에 적합합니다.</p>', '<p>Les vannes à membrane haute pression et à faible débit de la série DV4 ont un petit volume interne, très peu de particules sont générées et la conception du siège entièrement fermée présente des capacités anti-expansion et anti-pollution supérieures. Sans filetage ni ressort à l''intérieur, le canal d''écoulement peut être complètement nettoyé.</p><p>Le séparateur en alliage cobalt-nickel améliore la résistance et la résistance à la corrosion. Le siège PCTFE ou PI est disponible en option, manuel ou pneumatique pour des applications haute pression de pureté ultra-élevée.</p>', '<p>تتميز صمامات الحجاب الحاجز ذات الضغط العالي والتدفق الصغير من سلسلة DV4 بحجم داخلي صغير وتوليد عدد قليل جدًا من الجسيمات ، ويتميز تصميم المقعد المغلق بالكامل بقدرات فائقة على مقاومة التمدد والتلوث. لا توجد خيوط أو نوابض داخلية لتنظيف قناة المتدفق بالكامل.</p><p>يحسن فاصل سبائك الكوبالت والنيكل القوة ومقاومة التآكل. مقعد PCTFE أو PI اختياري ، نوع يدوي أو هوائي اختياري لتطبيقات الضغط العالي فائقة النقاء.</p>', '["高压 20.7MPa", "小流量 CV 0.26", "全封闭阀座设计", "内部无螺纹和弹簧", "钴镍合金隔膜"]', '["High pressure 20.7MPa", "Low flow CV 0.26", "Fully enclosed valve seat design", "No internal threads and springs", "Cobalt-nickel alloy diaphragm"]', '["高圧 20.7MPa", "小流量 CV 0.26", "全密閉シート設計", "内部ねじやばねなし", "コバルトニッケル合金ダイヤフラム"]', '["고압 20.7MPa", "작은 유량 CV 0.26", "완전 밀폐 시트 설계", "내부 나사 및 스프링 없음", "코발트 니켈 합금 다이어프램"]', '["Haute pression 20,7MPa", "Petit débit CV 0,26", "Conception de siège entièrement fermée", "Sans filetage et ressort à l''intérieur", "Séparateur en alliage cobalt-nickel"]', '["الضغط العالي 20.7 ميجا باسكال", "السيرة الذاتية للتدفق الصغير 0.26", "تصميم مقعد مغلق بالكامل", "لا يوجد خيوط ونوابض داخلية", "غشاء من سبائك الكوبالت والنيكل"]', NULL, NULL, NULL, false, '/uploads/oem/dv12a-mr4.jpg', NULL, NULL, NULL, NULL, NULL, NULL, 1, NULL, NULL, NULL, NULL, NULL, NULL, '[{"name": "工作压力", "value": "MAX. 20.7MPa（3000psig）", "nameAr": "ضغط العمل", "nameEn": "working pressure", "nameFr": "Pression de travail", "nameJa": "仕事のストレス", "nameKo": "업무 스트레스", "valueAr": "ماكس. 20.7 ميجا باسكال (3000psig)", "valueEn": "MAX. 20.7MPa (3000psig)", "valueFr": "MAX. 20,7 MPa (3000 psig)", "valueJa": "マックス20.7MPa（3000psig）", "valueKo": "최대. 20.7MPa (3000psig)"}, {"name": "流量系数 CV", "value": "0.26", "nameAr": "معامل التدفق السيرة الذاتية", "nameEn": "Flow coefficient CV", "nameFr": "Coefficient de débit CV", "nameJa": "流量係数 CV", "nameKo": "유량 계수 CV", "valueAr": "0.26", "valueEn": "0.26", "valueFr": "0.26", "valueJa": "0.26", "valueKo": "0.26"}, {"name": "内通径", "value": "4.1mm", "nameAr": "القطر الداخلي", "nameEn": "inner diameter", "nameFr": "diamètre interne", "nameJa": "インナーパス", "nameKo": "내부 직경", "valueAr": "4.1 ملم", "valueEn": "4.1mm", "valueFr": "4,1 mm", "valueJa": "4.1mm", "valueKo": "4.1mm"}, {"name": "阀座材料", "value": "PCTFE / PI", "nameAr": "مواد مقعد الصمام", "nameEn": "valve seat material", "nameFr": "Matériau du siège", "nameJa": "バルブシート材料", "nameKo": "밸브 시트 재료", "valueAr": "PCTFE / PI", "valueEn": "PCTFE/PI", "valueFr": "PCTFE/PI", "valueJa": "PCTFE / PI", "valueKo": "PCTFE / PI"}, {"name": "泄漏率", "value": "≤ 5x10⁻¹⁰ stdcm³/s", "nameAr": "معدل التسرب", "nameEn": "leakage rate", "nameFr": "Taux de fuite", "nameJa": "漏れ率", "nameKo": "누출율", "valueAr": "≤ 5x10⁻¹⁰ stdcm³/s", "valueEn": "≤ 5x10⁻¹⁰ stdcm³/s", "valueFr": "≤5x10⁻¹⁰ stdcm³/s", "valueJa": "≤ 5x10⁻¹⁰ stdcm³/s", "valueKo": "≤ 5x10⁻¹⁰ stdcm³/s"}]', 30, 'published', '2026-09-08 18:51:45.306', '2026-09-08 18:51:45.306', '2026-09-08 18:51:45.306', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO public.products ("siteId", id, "tabId", "categoryId", slug, model, name, "nameEn", "nameJa", "nameKo", "nameFr", "nameAr", subtitle, "subtitleEn", "subtitleJa", "subtitleKo", "subtitleFr", "subtitleAr", summary, "summaryEn", "summaryJa", "summaryKo", "summaryFr", "summaryAr", description, "descriptionEn", "descriptionJa", "descriptionKo", "descriptionFr", "descriptionAr", features, "featuresEn", "featuresJa", "featuresKo", "featuresFr", "featuresAr", images, price, "priceTiers", "isParts", "coverImage", video, frames360, "manualUrl", "priceMin", "priceMax", "priceUnit", moq, "priceNote", "priceNoteEn", "priceNoteJa", "priceNoteKo", "priceNoteFr", "priceNoteAr", specs, "sortOrder", status, "publishedAt", "createdAt", "updatedAt", "seoTitle", "seoTitleJa", "seoTitleKo", "seoTitleFr", "seoTitleAr", "seoTitleEn", "seoDescription", "seoDescriptionJa", "seoDescriptionKo", "seoDescriptionFr", "seoDescriptionAr", "seoDescriptionEn", "seoKeywords", "seoKeywordsJa", "seoKeywordsKo", "seoKeywordsFr", "seoKeywordsAr", "seoKeywordsEn", "geoRegion", "geoCity") VALUES (NULL, 31, 37, 9, 'dv5-high-pressure-medium-flow', '316L-DV5 Series', '高压中流量隔膜阀', 'high pressure medium flow diaphragm valve', '高圧中流量ダイヤフラムバルブ', '고압 중유량 다이어프램 밸브', 'Vanne à membrane à débit moyen haute pression', 'صمام الحجاب الحاجز عالي الضغط ومتوسط التدفق', '手动 24.1MPa / 气动 20.7MPa，CV 0.8', 'Manual 24.1MPa / Pneumatic 20.7MPa, CV 0.8', '手動 24.1MPa / 空気圧 20.7MPa、CV 0.8', '수동 24.1MPa / 공압 20.7MPa, CV 0.8', 'Manuel 24.1MPa/pneumatique 20.7MPa, CV 0.8', 'يدوي 24.1 ميجا باسكال / هوائي 20.7 ميجا باسكال ، CV 0.8', 'DV5 系列高压中流量隔膜阀，手动工作压力最高 24.1MPa，气动工作压力最高 20.7MPa，流量系数 CV 0.8。全封闭阀座设计，钴镍合金隔膜，适用于高压高纯气体中流量控制。', 'DV5 series high-pressure medium-flow diaphragm valves have a maximum manual working pressure of 24.1MPa, a maximum pneumatic working pressure of 20.7MPa, and a flow coefficient CV of 0.8. Fully enclosed valve seat design, cobalt-nickel alloy diaphragm, suitable for flow control in high-pressure, high-purity gases.', 'DV5 シリーズ高圧中流量ダイヤフラムバルブ、手動作動圧力最大 24.1MPa、空気圧作動圧力最大 20.7MPa、流量係数 CV 0.8。完全に密閉された弁座設計、コバルトニッケル合金ダイヤフラム、高圧高純度ガスの流量制御に適しています。', 'DV5 시리즈 고압 중간 유량 다이어프램 밸브, 수동 작동 압력 최대 24.1MPa, 공압 작동 압력 최대 20.7MPa, 유량 계수 CV 0.8. 완전히 밀폐된 밸브 시트 설계, 코발트-니켈 합금 다이어프램, 고압 고순도 가스의 유량 제어에 적합합니다', 'Vanne à membrane à débit moyen haute pression série DV5, pression de travail manuelle jusqu''à 24,1 MPa, pression de travail pneumatique jusqu''à 20,7 MPa, coefficient de débit CV 0,8. Conception du siège de vanne entièrement fermée, diaphragme en alliage cobalt-nickel, adapté au contrôle du débit dans les gaz haute pression et haute pureté.', 'صمام الحجاب الحاجز ذو التدفق المتوسط عالي الضغط من سلسلة DV5 ، يصل ضغط التشغيل اليدوي إلى 24.1 ميجا باسكال ، ويصل ضغط التشغيل الهوائي إلى 20.7 ميجا باسكال ، ومعامل التدفق CV 0.8. تصميم مقعد مغلق بالكامل ، غشاء سبائك الكوبالت والنيكل ، مناسب للتحكم في التدفق في الضغط العالي والغاز عالي النقاء.', '<p>DV5 系列高压中流量隔膜阀采用全封闭阀座设计，具有优越的抗膨胀和防污染能力；内部无螺纹和弹簧，可完全清扫流道。</p><p>钴镍合金隔膜提高强度和抗腐蚀性，使用寿命长。手动或气动类型可选，适用于超高纯高压应用。</p>', '<p>The DV5 series high-pressure medium-flow diaphragm valves adopt a fully enclosed valve seat design, which has superior anti-expansion and anti-pollution capabilities; There are no threads or springs inside, and the flow channel can be completely cleaned.</p><p>Cobalt-nickel alloy diaphragm improves strength and corrosion resistance, and has a long service life. Manual or pneumatic types are available for ultra-high pure high pressure applications.</p>', '<p>DV5 シリーズの高圧中流量ダイヤフラム バルブは、完全に密閉されたバルブ シート設計を採用しており、膨張防止と汚染防止に優れています。内部にはネジやスプリングがなく、ランナーを完全に掃除できます。</p><p>コバルトニッケル合金セパレータは強度と耐食性を向上させ、長寿命です。手動または空気圧タイプは、超高純度の高圧アプリケーションに適しています。</p>', '<p>DV5 시리즈 고압 중유량 다이어프램 밸브는 완전히 밀폐된 밸브 시트 설계를 채택하여 우수한 팽창 방지 및 오염 방지 능력을 가지고 내부에는 나사산과 스프링이 없어 러너를 완전히 청소합니다.</p><p>코발트-니켈 합금 분리막은 강도와 내식성을 향상시키고 수명이 길다. 수동 또는 공압 유형은 초고순도 고압 응용 프로그램을 위해 선택적입니다.</p>', '<p>Les vannes à membrane à débit moyen haute pression de la série DV5 adoptent une conception de siège entièrement fermée et ont des capacités anti-dilatation et anti-pollution supérieures; Sans filetage ni ressort à l''intérieur, le canal d''écoulement peut être complètement nettoyé.</p><p>Le séparateur en alliage cobalt-nickel améliore la résistance et la résistance à la corrosion et offre une longue durée de vie. Les types manuels ou pneumatiques sont en option pour des applications haute pression de pureté ultra-élevée.</p>', '<p>يعتمد صمام الحجاب الحاجز ذو التدفق المتوسط عالي الضغط من سلسلة DV5 على تصميم مقعد صمام مغلق بالكامل ، والذي يتمتع بقدرات فائقة مضادة للتمدد ومضادة للتلوث ؛ لا توجد خيوط أو نوابض داخلية لتنظيف قناة المتدفق بالكامل.</p><p>يحسن فاصل سبائك الكوبالت والنيكل القوة ومقاومة التآكل وله عمر خدمة طويل. نوع يدوي أو هوائي اختياري ، مناسب لتطبيقات الضغط العالي فائقة النقاء.</p>', '["手动 24.1MPa / 气动 20.7MPa", "中流量 CV 0.8", "全封闭阀座设计", "内部无螺纹和弹簧", "钴镍合金隔膜"]', '["Manual 24.1MPa / Pneumatic 20.7MPa", "Medium flow CV 0.8", "Fully enclosed valve seat design", "No internal threads and springs", "Cobalt-nickel alloy diaphragm"]', '["手動 24.1MPa / 空気圧 20.7MPa", "中流量 CV 0.8", "全密閉シート設計", "内部ねじなし、バネなし", "コバルトニッケル合金ダイヤフラム"]', '["수동 24.1MPa / 공압 20.7MPa", "중간 유량 CV 0.8", "완전 밀폐 시트 설계", "내부 나사 및 스프링 없음", "코발트 니켈 합금 다이어프램"]', '["Manuel 24,1MPa/pneumatique 20,7MPa", "Débit moyen CV 0,8", "Conception de siège entièrement fermée", "Sans filetage et ressort à l''intérieur", "Séparateur en alliage cobalt-nickel"]', '["يدوي 24.1 ميجا باسكال / هوائي 20.7 ميجا باسكال", "معدل التدفق المتوسط CV 0.8", "تصميم مقعد مغلق بالكامل", "لا يوجد خيوط ونوابض داخلية", "حجاب حاجز من سبائك الكوبالت والنيكل"]', NULL, NULL, NULL, false, '/uploads/oem/dv12a-mr4.jpg', NULL, NULL, NULL, NULL, NULL, NULL, 1, NULL, NULL, NULL, NULL, NULL, NULL, '[{"name": "手动工作压力", "value": "MAX. 24.1MPa", "nameAr": "ضغط العمل اليدوي", "nameEn": "manual working pressure", "nameFr": "Pression de travail manuelle", "nameJa": "手動作業圧力", "nameKo": "수동 작업 압력", "valueAr": "ماكس. 24.1 ميجا باسكال", "valueEn": "MAX. 24.1MPa", "valueFr": "MAX. 24,1 MPa", "valueJa": "マックス24.1MPa", "valueKo": "최대. 24.1MPa"}, {"name": "气动工作压力", "value": "MAX. 20.7MPa", "nameAr": "ضغط العمل الهوائي", "nameEn": "pneumatic working pressure", "nameFr": "Pression de fonctionnement pneumatique", "nameJa": "空気圧作動圧力", "nameKo": "공압 작동 압력", "valueAr": "ماكس. 20.7 ميجا باسكال", "valueEn": "MAX. 20.7MPa", "valueFr": "MAX. 20,7 MPa", "valueJa": "マックス20.7MPa", "valueKo": "최대. 20.7MPa"}, {"name": "流量系数 CV", "value": "0.8", "nameAr": "معامل التدفق السيرة الذاتية", "nameEn": "Flow coefficient CV", "nameFr": "Coefficient de débit CV", "nameJa": "流量係数 CV", "nameKo": "유량 계수 CV", "valueAr": "0.8", "valueEn": "0.8", "valueFr": "0.8", "valueJa": "0.8", "valueKo": "0.8"}, {"name": "阀座材料", "value": "PCTFE / PFA", "nameAr": "مواد مقعد الصمام", "nameEn": "valve seat material", "nameFr": "Matériau du siège", "nameJa": "バルブシート材料", "nameKo": "밸브 시트 재료", "valueAr": "PCTFE / PFA", "valueEn": "PCTFE/PFA", "valueFr": "PCTFE/PFA", "valueJa": "PCTFE / PFA", "valueKo": "PCTFE / PFA"}, {"name": "泄漏率", "value": "≤ 5x10⁻¹⁰ stdcm³/s", "nameAr": "معدل التسرب", "nameEn": "leakage rate", "nameFr": "Taux de fuite", "nameJa": "漏れ率", "nameKo": "누출율", "valueAr": "≤ 5x10⁻¹⁰ stdcm³/s", "valueEn": "≤ 5x10⁻¹⁰ stdcm³/s", "valueFr": "≤5x10⁻¹⁰ stdcm³/s", "valueJa": "≤ 5x10⁻¹⁰ stdcm³/s", "valueKo": "≤ 5x10⁻¹⁰ stdcm³/s"}]', 31, 'published', '2026-09-08 18:51:45.306', '2026-09-08 18:51:45.306', '2026-09-08 18:51:45.306', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO public.products ("siteId", id, "tabId", "categoryId", slug, model, name, "nameEn", "nameJa", "nameKo", "nameFr", "nameAr", subtitle, "subtitleEn", "subtitleJa", "subtitleKo", "subtitleFr", "subtitleAr", summary, "summaryEn", "summaryJa", "summaryKo", "summaryFr", "summaryAr", description, "descriptionEn", "descriptionJa", "descriptionKo", "descriptionFr", "descriptionAr", features, "featuresEn", "featuresJa", "featuresKo", "featuresFr", "featuresAr", images, price, "priceTiers", "isParts", "coverImage", video, frames360, "manualUrl", "priceMin", "priceMax", "priceUnit", moq, "priceNote", "priceNoteEn", "priceNoteJa", "priceNoteKo", "priceNoteFr", "priceNoteAr", specs, "sortOrder", status, "publishedAt", "createdAt", "updatedAt", "seoTitle", "seoTitleJa", "seoTitleKo", "seoTitleFr", "seoTitleAr", "seoTitleEn", "seoDescription", "seoDescriptionJa", "seoDescriptionKo", "seoDescriptionFr", "seoDescriptionAr", "seoDescriptionEn", "seoKeywords", "seoKeywordsJa", "seoKeywordsKo", "seoKeywordsFr", "seoKeywordsAr", "seoKeywordsEn", "geoRegion", "geoCity") VALUES (NULL, 9, 35, 7, 'vcr-gn-fmr4', '316L-GN-FMR4', 'VCR 阴螺纹螺母接头', 'VCR Female Nut Fitting', 'VCR メスネジナット継手', 'VCR 암 나사 너트 피팅', 'Joint d''écrou fileté femelle VCR', 'تركيب صامولة خيط أنثى VCR', '1/4" VCR 内螺纹，金属面密封', '1/4" VCR female thread, metal face seal', '1/4 インチ VCR メス、メタルフェースシール', '1/4" VCR 암, 금속 면 씰', 'Filetage femelle VCR 1/4 ", joint de face métallique', 'خيط أنثى VCR مقاس 1/4 بوصة ، ختم وجه معدني', '316L 不锈钢 VCR 阴螺纹螺母接头，金属对金属面密封，适用于超高纯气体与流体系统。', '316L SS VCR female nut fitting with metal-to-metal face seal for UHP gas and fluid systems.', '316L ステンレス鋼 VCR メスネジナットフィッティング、金属対金属面シール、超高純度ガスおよび流体システム用。', '316L 스테인레스 스틸 VCR 암 너트 피팅, 금속 대 금속 면 씰, 초고순도 가스 및 유체 시스템용.', 'Joint d''écrou fileté femelle VCR en acier inoxydable 316L, étanchéité de surface métal à métal, adapté aux systèmes de gaz et de fluide ultra haute pureté.', 'وصلة صامولة ملولبة أنثوية من الفولاذ المقاوم للصدأ 316L VCR مع ختم وجه معدني إلى معدني لأنظمة الغاز والسوائل فائقة النقاء.', '<p>VCR 面密封接头采用 316L 不锈钢，金属对金属密封结构，无弹性体，适用于超高纯工艺气体管路。</p><p>1/4" 阴螺纹（FMR），可搭配 GN 系列螺母与垫片使用，洁净度可达 EP 级。</p>', '<p>VCR face seal fitting in 316L SS with metal-to-metal sealing, elastomer-free for UHP process gas lines.</p><p>1/4" female thread (FMR), works with GN nuts and gaskets, EP cleanliness available.</p>', '<p>VCR フェース シール ジョイントは 316L ステンレス鋼で作られており、メタル ツー メタル シール構造、エラストマーなし、超高純度プロセス ガス ラインに適しています。</p><p>1/4 インチ雌ねじ (FMR)、GN シリーズのナットとスペーサーで使用でき、EP クラスまでの清潔さを実現します。</p>', '<p>VCR 페이스 씰 조인트는 316L 스테인레스 스틸, 금속 대 금속 씰 구조, 엘라스토머가 없으며 초고순도 공정 가스 라인에 적합합니다.</p><p>1/4" 암 나사(FMR), GN 시리즈 너트 및 개스킷과 함께 사용할 수 있으며 EP 클래스까지 청결합니다.</p>', '<p>Le joint d''étanchéité de surface VCR est en acier inoxydable 316L, structure d''étanchéité métal-à-métal, sans élastomère, adapté aux pipelines de gaz de processus ultra-haute pureté.</p><p>Le filetage femelle (FMR) de 1/4 "peut être utilisé avec des écrous et des joints de la série GN, et la propreté peut atteindre le niveau EP.</p>', '<p>وصلة ختم وجه VCR مصنوعة من الفولاذ المقاوم للصدأ 316L ، وهيكل مانع للتسرب من المعدن إلى المعدن ، وخالية من المطاط الصناعي ، ومناسبة لخطوط غاز المعالجة فائقة النقاء.</p><p>خيط أنثوي مقاس 1/4 بوصة (FMR)، يمكن استخدامه مع صواميل وفواصل من سلسلة GN ، ويمكن أن تصل النظافة إلى مستوى EP.</p>', '["316L 不锈钢", "金属面密封无弹性体", "适配超高纯工艺"]', '["316L stainless steel", "Metal face seal, elastomer-free", "For UHP processes"]', '["316L ステンレス", "金属面シール エラストマーなし", "超高純度プロセスに対応"]', '["316L 스테인리스", "금속면 밀봉 엘라스토머 없음", "초고순도 공정 적응"]', '["Acier inoxydable 316L", "Joint de surface métallique sans élastomère", "Adapté au processus de pureté ultra-élevée"]', NULL, NULL, NULL, NULL, false, '/uploads/oem/GN_2.png', NULL, NULL, NULL, NULL, NULL, NULL, 1, NULL, NULL, NULL, NULL, NULL, NULL, '[{"name": "口径", "value": "1/4\" (6.35mm)", "nameAr": "عيار", "nameEn": "Size", "nameFr": "Calibre", "nameJa": "口径", "nameKo": "구경", "valueAr": "1/4\" (6.35mm)", "valueEn": "1/4\" (6.35mm)", "valueFr": "1/4\" (6.35mm)", "valueJa": "1/4\" (6.35mm)", "valueKo": "1/4\" (6.35mm)"}, {"name": "连接", "value": "VCR 阴螺纹 FMR", "nameAr": "الاتصال", "nameEn": "Connection", "nameFr": "Connexion", "nameJa": "接続", "nameKo": "연결", "valueAr": "مسجل فيديو أنثى الخيط FMR", "valueEn": "VCR Female Thread FMR", "valueFr": "Filetage femelle VCR FMR", "valueJa": "VCR メスネジ FMR", "valueKo": "VCR 암 스레드 FMR"}, {"name": "材质", "value": "316L", "nameAr": "المواد", "nameEn": "Material", "nameFr": "Matériel", "nameJa": "材質", "nameKo": "재료", "valueAr": "316L", "valueEn": "316L", "valueFr": "316L", "valueJa": "316L", "valueKo": "316L"}, {"name": "表面处理", "value": "标准 / EP", "nameAr": "المعالجة السطحية", "nameEn": "Finish", "nameFr": "Traitement de surface", "nameJa": "表面処理", "nameKo": "표면 처리", "valueAr": "القياسية / EP", "valueEn": "Standard / EP", "valueFr": "Norme/EP", "valueJa": "スタンダード / EP", "valueKo": "표준 / EP"}]', 9, 'published', NULL, '2026-09-07 10:59:24.498', '2026-09-07 10:59:24.498', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO public.products ("siteId", id, "tabId", "categoryId", slug, model, name, "nameEn", "nameJa", "nameKo", "nameFr", "nameAr", subtitle, "subtitleEn", "subtitleJa", "subtitleKo", "subtitleFr", "subtitleAr", summary, "summaryEn", "summaryJa", "summaryKo", "summaryFr", "summaryAr", description, "descriptionEn", "descriptionJa", "descriptionKo", "descriptionFr", "descriptionAr", features, "featuresEn", "featuresJa", "featuresKo", "featuresFr", "featuresAr", images, price, "priceTiers", "isParts", "coverImage", video, frames360, "manualUrl", "priceMin", "priceMax", "priceUnit", moq, "priceNote", "priceNoteEn", "priceNoteJa", "priceNoteKo", "priceNoteFr", "priceNoteAr", specs, "sortOrder", status, "publishedAt", "createdAt", "updatedAt", "seoTitle", "seoTitleJa", "seoTitleKo", "seoTitleFr", "seoTitleAr", "seoTitleEn", "seoDescription", "seoDescriptionJa", "seoDescriptionKo", "seoDescriptionFr", "seoDescriptionAr", "seoDescriptionEn", "seoKeywords", "seoKeywordsJa", "seoKeywordsKo", "seoKeywordsFr", "seoKeywordsAr", "seoKeywordsEn", "geoRegion", "geoCity") VALUES (NULL, 32, 37, 9, 'dv6-medium-pressure-medium-flow', '316L-DV6 Series', '中压中流量隔膜阀', 'medium pressure medium flow diaphragm valve', '中圧中流量ダイヤフラムバルブ', '중압 중유량 다이어프램 밸브', 'Vanne à membrane à moyenne pression et débit moyen', 'صمام الحجاب الحاجز ذو الضغط المتوسط والتدفق', '中压 2.07MPa，CV 0.65', 'Medium pressure 2.07 MPa, CV 0.65', '中圧 2.07MPa、CV 0.65', '중간 전압 2.07MPa, CV 0.65', 'Moyenne pression 2,07MPa, CV 0,65', 'الجهد المتوسط 2.07 ميجا باسكال ، السيرة الذاتية 0.65', 'DV6 系列中压中流量隔膜阀，工作压力最高 2.07MPa，流量系数 CV 0.65。全封闭阀座设计，内部无螺纹和弹簧，钴镍合金隔膜，适用于中等压力高纯气体流量控制。', 'DV6 series medium-pressure medium-flow diaphragm valve, with a maximum working pressure of 2.07MPa and a flow coefficient CV of 0.65. Fully enclosed valve seat design, without internal threads and springs, cobalt-nickel alloy diaphragm, suitable for medium-pressure high-purity gas flow control.', 'DV6 シリーズ中圧中流量ダイヤフラムバルブ、最大作動圧力 2.07MPa、流量係数 CV 0.65。完全に密閉されたシート設計、内部ねじやばねなし、コバルトニッケル合金ダイヤフラム、中圧高純度ガス流量制御に適しています。', 'DV6 시리즈 중압 중간 유량 다이어프램 밸브, 최대 작동 압력 2.07MPa, 유량 계수 CV 0.65. 완전히 밀폐된 밸브 시트 디자인, 내부 나사산 및 스프링 없음, 중간 압력 고순도 가스 흐름 제어를 위한 코발트 니켈 합금 다이어프램.', 'Vanne à membrane à moyenne pression et débit moyen série DV6, pression de fonctionnement maximale de 2,07 MPa, coefficient de débit CV 0,65. Conception de siège entièrement fermée, sans filetage ni ressort à l''intérieur, diaphragme en alliage cobalt-nickel, adapté au contrôle du débit de gaz à pression moyenne et haute pureté.', 'صمام الحجاب الحاجز ذو الضغط المتوسط والتدفق المتوسط من سلسلة DV6 مع ضغط عمل يصل إلى 2.07 ميجا باسكال ومعامل تدفق CV 0.65. تصميم مقعد مغلق بالكامل ، بدون خيوط ونوابض داخلية ، غشاء من سبائك الكوبالت والنيكل ، مناسب للتحكم في تدفق الغاز عالي النقاء بالضغط المتوسط.', '<p>DV6 系列中压中流量隔膜阀内部容积小、极少颗粒生成，全封闭阀座设计具有优越的抗膨胀和防污染能力。</p><p>钴镍合金隔膜提高强度和抗腐蚀性，手动或气动类型可选，适用于超高纯应用。</p>', '<p>The DV6 series medium-pressure and medium-flow diaphragm valves have a small internal volume and minimal particle formation. The fully enclosed valve seat design has superior anti-expansion and anti-contamination capabilities.</p><p>Cobalt-nickel alloy diaphragms improve strength and corrosion resistance, and are available in manual or pneumatic types, making them suitable for ultra-high purity applications.</p>', '<p>DV6 シリーズの中圧中流量ダイヤフラム バルブは、内部容積が小さく、粒子の発生がほとんどなく、完全に密閉されたシート設計により、膨張と汚染に対する優れた耐性を備えています。</p><p>コバルトニッケル合金ダイヤフラムは、強度と耐食性を向上させ、超高純度アプリケーションに適した手動または空気圧タイプから選択できます。</p>', '<p>DV6 시리즈 중압 중유량 다이어프램 밸브는 내부 부피가 작고 입자 생성이 거의 없으며 완전히 밀폐된 시트 설계로 우수한 팽창 및 오염 방지 기능을 제공합니다.</p><p>코발트-니켈 합금 분리막은 강도와 내식성을 향상시키고, 수동 또는 공압 유형을 선택할 수 있으며, 초고순도 응용 분야에 적합합니다</p>', '<p>Les vannes à membrane à moyenne pression et à débit moyen de la série DV6 ont un petit volume interne, très peu de particules sont générées et la conception du siège entièrement fermée présente des capacités anti-expansion et anti-pollution supérieures.</p><p>Les diaphragmes en alliage cobalt-nickel améliorent la résistance et la résistance à la corrosion, disponibles en type manuel ou pneumatique pour des applications ultra haute pureté.</p>', '<p>تتميز صمامات الحجاب الحاجز ذات الضغط المتوسط والتدفق المتوسط من سلسلة DV6 بحجم داخلي صغير وتوليد عدد قليل جدًا من الجسيمات ، كما أن تصميم المقعد المغلق بالكامل يتميز بقدرات فائقة على مقاومة التمدد والتلوث.</p><p>حاجز سبائك الكوبالت والنيكل يحسن القوة ومقاومة التآكل ، وهو متوفر في النوع اليدوي أو الهوائي ، وهو مناسب لتطبيقات النقاء العالي للغاية.</p>', '["中压 2.07MPa", "中流量 CV 0.65", "全封闭阀座设计", "内部无螺纹和弹簧", "钴镍合金隔膜"]', '["Medium pressure 2.07MPa", "Medium flow CV 0.65", "Fully enclosed valve seat design", "No internal threads and springs", "Cobalt-nickel alloy diaphragm"]', '["中圧 2.07MPa", "中流量 CV 0.65", "全密閉シート設計", "内部ねじやばねなし", "コバルトニッケル合金ダイヤフラム"]', '["중압 2.07MPa", "중유량 CV 0.65", "완전 밀폐형 시트 설계", "내부 나사 및 스프링 없음", "코발트 니켈 합금 다이어프램"]', '["Moyenne pression 2,07 MPa", "Débit moyen CV 0,65", "Conception de siège entièrement fermée", "Sans filetage et ressort à l''intérieur", "Séparateur en alliage cobalt-nickel"]', '["ضغط متوسط 2.07 ميجا باسكال", "تدفق متوسط CV 0.65", "تصميم مقعد مغلق بالكامل", "لا توجد خيوط أو نوابض داخلية", "غشاء من سبائك الكوبالت والنيكل"]', NULL, NULL, NULL, false, '/uploads/oem/dv22a-mr8.jpg', NULL, NULL, NULL, NULL, NULL, NULL, 1, NULL, NULL, NULL, NULL, NULL, NULL, '[{"name": "工作压力", "value": "MAX. 2.07MPa", "nameAr": "ضغط العمل", "nameEn": "working pressure", "nameFr": "Pression de travail", "nameJa": "仕事のストレス", "nameKo": "업무 스트레스", "valueAr": "ماكس. 2.07 ميجا باسكال", "valueEn": "MAX. 2.07MPa", "valueFr": "MAX. 2,07 MPa", "valueJa": "マックス2.07MPa", "valueKo": "최대. 2.07MPa"}, {"name": "流量系数 CV", "value": "0.65", "nameAr": "معامل التدفق السيرة الذاتية", "nameEn": "Flow coefficient CV", "nameFr": "Coefficient de débit CV", "nameJa": "流量係数 CV", "nameKo": "유량 계수 CV", "valueAr": "0.65", "valueEn": "0.65", "valueFr": "0.65", "valueJa": "0.65", "valueKo": "0.65"}, {"name": "阀座材料", "value": "PCTFE / PFA", "nameAr": "مواد مقعد الصمام", "nameEn": "valve seat material", "nameFr": "Matériau du siège", "nameJa": "バルブシート材料", "nameKo": "밸브 시트 재료", "valueAr": "PCTFE / PFA", "valueEn": "PCTFE/PFA", "valueFr": "PCTFE/PFA", "valueJa": "PCTFE / PFA", "valueKo": "PCTFE / PFA"}, {"name": "泄漏率", "value": "≤ 5x10⁻¹⁰ stdcm³/s", "nameAr": "معدل التسرب", "nameEn": "leakage rate", "nameFr": "Taux de fuite", "nameJa": "漏れ率", "nameKo": "누출율", "valueAr": "≤ 5x10⁻¹⁰ stdcm³/s", "valueEn": "≤ 5x10⁻¹⁰ stdcm³/s", "valueFr": "≤5x10⁻¹⁰ stdcm³/s", "valueJa": "≤ 5x10⁻¹⁰ stdcm³/s", "valueKo": "≤ 5x10⁻¹⁰ stdcm³/s"}]', 32, 'published', '2026-09-08 18:51:45.307', '2026-09-08 18:51:45.307', '2026-09-08 18:51:45.307', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO public.products ("siteId", id, "tabId", "categoryId", slug, model, name, "nameEn", "nameJa", "nameKo", "nameFr", "nameAr", subtitle, "subtitleEn", "subtitleJa", "subtitleKo", "subtitleFr", "subtitleAr", summary, "summaryEn", "summaryJa", "summaryKo", "summaryFr", "summaryAr", description, "descriptionEn", "descriptionJa", "descriptionKo", "descriptionFr", "descriptionAr", features, "featuresEn", "featuresJa", "featuresKo", "featuresFr", "featuresAr", images, price, "priceTiers", "isParts", "coverImage", video, frames360, "manualUrl", "priceMin", "priceMax", "priceUnit", moq, "priceNote", "priceNoteEn", "priceNoteJa", "priceNoteKo", "priceNoteFr", "priceNoteAr", specs, "sortOrder", status, "publishedAt", "createdAt", "updatedAt", "seoTitle", "seoTitleJa", "seoTitleKo", "seoTitleFr", "seoTitleAr", "seoTitleEn", "seoDescription", "seoDescriptionJa", "seoDescriptionKo", "seoDescriptionFr", "seoDescriptionAr", "seoDescriptionEn", "seoKeywords", "seoKeywordsJa", "seoKeywordsKo", "seoKeywordsFr", "seoKeywordsAr", "seoKeywordsEn", "geoRegion", "geoCity") VALUES (NULL, 10, 35, 7, 'vcr-gmn-mr4', '316L-GMN-MR4', 'VCR 阳螺纹螺母接头', 'VCR Male Nut Fitting', 'VCR オスネジナット継手', 'VCR 수 나사 너트 피팅', 'Joint d''écrou fileté mâle VCR', 'تركيب صامولة ذكر لمسجل الفيديو', '1/4" VCR 外螺纹，金属面密封', '1/4" VCR male thread, metal face seal', '1/4 インチ VCR オス、金属表面シール', '1/4" VCR 수, 금속 면 씰', 'Filetage mâle VCR 1/4 ", joint de face métallique', 'خيط ذكر لمسجل فيديو مقاس 1/4 بوصة ، ختم وجه معدني', '316L VCR 阳螺纹螺母接头，外螺纹活接结构，密封可靠，适配高纯气体系统。', '316L VCR male nut fitting with external thread union, reliable sealing for high-purity gas systems.', '316L VCR 雄ねじナットジョイント、雄ねじフラップ構造、信頼性の高いシール、高純度ガスシステムに適合。', '316L VCR 수 나사 너트 커넥터, 수 나사 플록 구조, 안정적인 밀봉, 고순도 가스 시스템에 적합합니다.', 'Joint d''écrou fileté mâle VCR 316L, structure de joint à filetage externe, étanchéité fiable, adapté aux systèmes de gaz de haute pureté.', 'موصل صامولة ذكر ملولب 316L VCR ، هيكل وصلة خارجي ملولب ، ختم موثوق ، مناسب لأنظمة الغاز عالية النقاء.', '<p>VCR 阳螺纹螺母接头（MR）与阴螺纹接头配合使用，构成 VCR 金属面密封连接。</p><p>316L 材质，可选 EP 表面处理，满足半导体级洁净要求。</p>', '<p>VCR male nut fitting (MR) pairs with female fitting for metal face seal connection.</p><p>316L with optional EP finish for semiconductor-grade cleanliness.</p>', '<p>VCR オス ネジ ナット フィッティング (MR) は、メス ネジ フィッティングと組み合わせて使用され、VCR 金属面密閉接続を形成します。</p><p>316L 素材、半導体グレードのクリーン要件を満たすオプションの EP 表面処理。</p>', '<p>VCR 수 나사 너트 피팅(MR)은 암 나사 피팅과 함께 사용하여 VCR 금속 면 밀봉 연결을 형성합니다.</p><p>316L 소재, EP 표면 처리 옵션, 반도체급 청정 요구 사항 충족.</p>', '<p>Le joint d''écrou fileté mâle (MR) du magnétoscope est utilisé avec le joint fileté femelle pour former une connexion étanche de surface métallique du magnétoscope.</p><p>Matériau 316L, traitement de surface EP facultatif pour répondre aux exigences de propreté de niveau semi-conducteur.</p>', '<p>يتم استخدام وصلة الجوز الملولبة ذكر VCR (MR) جنبًا إلى جنب مع وصلة الملولبة الأنثوية لتشكيل وصلة محكمة الغلق ذات الوجه المعدني لجهاز VCR.</p><p>مادة 316L ، معالجة سطح EP اختيارية لتلبية متطلبات النظافة بدرجة أشباه الموصلات.</p>', '["外螺纹活接结构", "316L 材质", "EP 表面可选"]', '["Male thread union", "316L material", "EP finish option"]', '["雄ねじ接続構造", "316L 素材", "EP サーフェス オプション"]', '["수 스레드 플립 구조", "316L 재질", "EP 표면 선택"]', '["Structure de joint à filetage externe", "Matériau 316L", "Surface EP en option"]', NULL, NULL, NULL, NULL, false, '/uploads/oem/GMN_1.png', NULL, NULL, NULL, NULL, NULL, NULL, 1, NULL, NULL, NULL, NULL, NULL, NULL, '[{"name": "口径", "value": "1/4\" (6.35mm)", "nameAr": "عيار", "nameEn": "Size", "nameFr": "Calibre", "nameJa": "口径", "nameKo": "구경", "valueAr": "1/4\" (6.35mm)", "valueEn": "1/4\" (6.35mm)", "valueFr": "1/4\" (6.35mm)", "valueJa": "1/4\" (6.35mm)", "valueKo": "1/4\" (6.35mm)"}, {"name": "连接", "value": "VCR 阳螺纹 MR", "nameAr": "الاتصال", "nameEn": "Connection", "nameFr": "Connexion", "nameJa": "接続", "nameKo": "연결", "valueAr": "مسجل فيديو ذكر الخيط السيد", "valueEn": "VCR Male Thread MR", "valueFr": "Filetage mâle VCR MR", "valueJa": "VCR オスネジ MR", "valueKo": "VCR 수 스레드 MR"}, {"name": "材质", "value": "316L", "nameAr": "المواد", "nameEn": "Material", "nameFr": "Matériel", "nameJa": "材質", "nameKo": "재료", "valueAr": "316L", "valueEn": "316L", "valueFr": "316L", "valueJa": "316L", "valueKo": "316L"}]', 10, 'published', NULL, '2026-09-07 10:59:24.502', '2026-09-07 10:59:24.502', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO public.products ("siteId", id, "tabId", "categoryId", slug, model, name, "nameEn", "nameJa", "nameKo", "nameFr", "nameAr", subtitle, "subtitleEn", "subtitleJa", "subtitleKo", "subtitleFr", "subtitleAr", summary, "summaryEn", "summaryJa", "summaryKo", "summaryFr", "summaryAr", description, "descriptionEn", "descriptionJa", "descriptionKo", "descriptionFr", "descriptionAr", features, "featuresEn", "featuresJa", "featuresKo", "featuresFr", "featuresAr", images, price, "priceTiers", "isParts", "coverImage", video, frames360, "manualUrl", "priceMin", "priceMax", "priceUnit", moq, "priceNote", "priceNoteEn", "priceNoteJa", "priceNoteKo", "priceNoteFr", "priceNoteAr", specs, "sortOrder", status, "publishedAt", "createdAt", "updatedAt", "seoTitle", "seoTitleJa", "seoTitleKo", "seoTitleFr", "seoTitleAr", "seoTitleEn", "seoDescription", "seoDescriptionJa", "seoDescriptionKo", "seoDescriptionFr", "seoDescriptionAr", "seoDescriptionEn", "seoKeywords", "seoKeywordsJa", "seoKeywordsKo", "seoKeywordsFr", "seoKeywordsAr", "seoKeywordsEn", "geoRegion", "geoCity") VALUES (NULL, 33, 37, 9, 'dv7-high-pressure-spring', '316L-DV7 Series', '高压弹簧隔膜阀', 'high pressure spring diaphragm valve', '高圧ばねダイヤフラム弁', '고압 스프링 다이어프램 밸브', 'Vanne à membrane à ressort haute pression', 'صمام الحجاب الحاجز الربيعي عالي الضغط', '弹簧加载，高压 24.1MPa', 'Spring loaded, high pressure 24.1MPa', 'ばね荷重、高圧 24.1MPa', '스프링 로딩, 고압 24.1MPa', 'Chargé par ressort, haute pression 24,1 MPa', 'تحميل الزنبرك ، الضغط العالي 24.1 ميجا باسكال', 'DV7 系列高压弹簧隔膜阀，手动与气动工作压力均最高 24.1MPa，流量系数 CV 0.14/0.3（手动）、0.2（气动）。弹簧加载阀座设计，适用于高压高纯气体的可靠截止与调节。', 'The DV7 series high-pressure spring diaphragm valves have a maximum operating pressure of 24.1MPa for both manual and pneumatic operations, and a flow coefficient CV of 0.14/0.3 (manual) and 0.2 (pneumatic). The spring-loaded valve seat design is suitable for reliable shut-off and regulation of high-pressure, high-purity gases.', 'DV7シリーズ高圧スプリングダイヤフラムバルブは、手動と空気圧の両方の作動圧力が最大24.1MPa、流量係数CV 0.14/0.3（手動）、0.2（空気圧）です。スプリング負荷弁座設計は、高圧高純度ガスの信頼性の高い遮断と調整に適しています。', 'DV7 시리즈 고압 스프링 다이어프램 밸브, 수동 및 공압 작동 압력 모두 최대 24.1MPa, 유량 계수 CV 0.14/0.3(수동), 0.2(공압). 스프링 로딩 밸브 시트 설계는 고압 고순도 가스의 신뢰할 수 있는 차단 및 조정에 적합합니다.', 'Vanne à membrane à ressort haute pression série DV7, pression de travail manuelle et pneumatique jusqu''à 24,1 MPa, coefficient de débit CV 0,14/0,3 (manuel), 0,2 (pneumatique). La conception du siège de vanne chargé à ressort convient à la coupure et au réglage fiables des gaz haute pression et haute pureté.', 'صمام الحجاب الحاجز الزنبركي عالي الضغط من سلسلة DV7 لديه ضغط عمل يدوي وهوائي يصل إلى 24.1 ميجا باسكال ، ومعاملات تدفق CV 0.14/0.3 (يدوي)، 0.2 (هوائي). تصميم مقعد الصمام المحمل بالزنبرك مناسب للقطع الموثوق والتعديل للغاز عالي الضغط وعالي النقاء.', '<p>DV7 系列高压弹簧隔膜阀采用弹簧加载阀座设计，在高压工况下提供可靠的密封与截止性能。</p><p>钴镍合金隔膜提高强度和抗腐蚀性，手动或气动类型可选，适用于超高纯高压应用。</p>', '<p>The DV7 series high-pressure spring-loaded diaphragm valves feature a spring-loaded valve seat design, providing reliable sealing and cutoff performance under high-pressure conditions.</p><p>Cobalt-nickel alloy diaphragms improve strength and corrosion resistance. Manual or pneumatic types are available, making them suitable for ultra-high pure high-pressure applications.</p>', '<p>DV7シリーズ高圧スプリングダイヤフラムバルブは、高圧条件下で信頼性の高いシールおよびカットオフ性能を提供するスプリングロードシート設計を採用しています。</p><p>コバルトニッケル合金ダイヤフラムは、強度と耐食性を向上させ、超高純度高圧アプリケーションに適した手動または空気圧タイプから選択できます。</p>', '<p>DV7 시리즈 고압 스프링 다이어프램 밸브는 스프링 로딩 시트 설계를 사용하여 고압 조건에서 안정적인 밀봉 및 차단 성능을 제공합니다.</p><p>코발트-니켈 합금 다이어프램은 강도와 내식성을 향상시키고, 수동 또는 공압 유형을 선택할 수 있으며, 초고순도 고압 응용 분야에 적합합니다.</p>', '<p>Les vannes à membrane à ressort haute pression de la série DV7 adoptent une conception de siège à ressort pour offrir des performances d''étanchéité et de coupure fiables dans des conditions de haute pression.</p><p>Le diaphragme en alliage cobalt-nickel améliore la résistance et la résistance à la corrosion, disponible en type manuel ou pneumatique pour des applications haute pression de pureté ultra haute.</p>', '<p>تتميز صمامات الحجاب الحاجز الزنبركية ذات الضغط العالي من سلسلة DV7 بتصميم مقعد محمل بالزنبرك لتوفير أداء ختم وقطع موثوق به في ظل ظروف الضغط العالي.</p><p>حاجز سبائك الكوبالت والنيكل يحسن القوة ومقاومة التآكل ، وهو متوفر في النوع اليدوي أو الهوائي ، وهو مناسب لتطبيقات الضغط العالي فائقة النقاء.</p>', '["弹簧加载阀座", "高压 24.1MPa", "CV 0.14 / 0.3（手动）", "气动 CV 0.2"]', '["Spring Loaded Valve Seat", "High Pressure 24.1MPa", "CV 0.14 / 0.3 (Manual)", "Pneumatic CV 0.2"]', '["スプリングシート", "高圧 24.1MPa", "CV 0.14 / 0.3 (手動)", "空気圧 CV 0.2"]', '["스프링 로딩 시트", "고압 24.1MPa", "CV 0.14 / 0.3 (수동)", "공압 CV 0.2"]', '["Siège à ressort", "Haute pression 24,1 MPa", "CV 0.14/0.3 (manuel)", "Pneumatique CV 0.2"]', '["مقعد محمل بالزنبرك", "الضغط العالي 24.1 ميجا باسكال", "السيرة الذاتية 0.14 / 0.3 (يدوي)", "السيرة الذاتية الهوائية 0.2"]', NULL, NULL, NULL, false, '/uploads/oem/dv12a-mr4.jpg', NULL, NULL, NULL, NULL, NULL, NULL, 1, NULL, NULL, NULL, NULL, NULL, NULL, '[{"name": "手动工作压力", "value": "MAX. 24.1MPa", "nameAr": "ضغط العمل اليدوي", "nameEn": "manual working pressure", "nameFr": "Pression de travail manuelle", "nameJa": "手動作業圧力", "nameKo": "수동 작업 압력", "valueAr": "ماكس. 24.1 ميجا باسكال", "valueEn": "MAX. 24.1MPa", "valueFr": "MAX. 24,1 MPa", "valueJa": "マックス24.1MPa", "valueKo": "최대. 24.1MPa"}, {"name": "气动工作压力", "value": "MAX. 24.1MPa", "nameAr": "ضغط العمل الهوائي", "nameEn": "pneumatic working pressure", "nameFr": "Pression de fonctionnement pneumatique", "nameJa": "空気圧作動圧力", "nameKo": "공압 작동 압력", "valueAr": "ماكس. 24.1 ميجا باسكال", "valueEn": "MAX. 24.1MPa", "valueFr": "MAX. 24,1 MPa", "valueJa": "マックス24.1MPa", "valueKo": "최대. 24.1MPa"}, {"name": "流量系数 CV", "value": "0.14 / 0.3（手动）、0.2（气动）", "nameAr": "معامل التدفق السيرة الذاتية", "nameEn": "Flow coefficient CV", "nameFr": "Coefficient de débit CV", "nameJa": "流量係数 CV", "nameKo": "유량 계수 CV", "valueAr": "0.14 / 0.3 (يدوي)، 0.2 (هوائي)", "valueEn": "0.14 / 0.3 (manual), 0.2 (pneumatic)", "valueFr": "0,14/0,3 (manuel), 0,2 (pneumatique)", "valueJa": "0.14 / 0.3（手動）、0.2（空気圧）", "valueKo": "0.14 / 0.3 (수동), 0.2 (공압)"}, {"name": "阀座材料", "value": "PCTFE / PFA", "nameAr": "مواد مقعد الصمام", "nameEn": "valve seat material", "nameFr": "Matériau du siège", "nameJa": "バルブシート材料", "nameKo": "밸브 시트 재료", "valueAr": "PCTFE / PFA", "valueEn": "PCTFE/PFA", "valueFr": "PCTFE/PFA", "valueJa": "PCTFE / PFA", "valueKo": "PCTFE / PFA"}]', 33, 'published', '2026-09-08 18:51:45.308', '2026-09-08 18:51:45.308', '2026-09-08 18:51:45.308', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO public.products ("siteId", id, "tabId", "categoryId", slug, model, name, "nameEn", "nameJa", "nameKo", "nameFr", "nameAr", subtitle, "subtitleEn", "subtitleJa", "subtitleKo", "subtitleFr", "subtitleAr", summary, "summaryEn", "summaryJa", "summaryKo", "summaryFr", "summaryAr", description, "descriptionEn", "descriptionJa", "descriptionKo", "descriptionFr", "descriptionAr", features, "featuresEn", "featuresJa", "featuresKo", "featuresFr", "featuresAr", images, price, "priceTiers", "isParts", "coverImage", video, frames360, "manualUrl", "priceMin", "priceMax", "priceUnit", moq, "priceNote", "priceNoteEn", "priceNoteJa", "priceNoteKo", "priceNoteFr", "priceNoteAr", specs, "sortOrder", status, "publishedAt", "createdAt", "updatedAt", "seoTitle", "seoTitleJa", "seoTitleKo", "seoTitleFr", "seoTitleAr", "seoTitleEn", "seoDescription", "seoDescriptionJa", "seoDescriptionKo", "seoDescriptionFr", "seoDescriptionAr", "seoDescriptionEn", "seoKeywords", "seoKeywordsJa", "seoKeywordsKo", "seoKeywordsFr", "seoKeywordsAr", "seoKeywordsEn", "geoRegion", "geoCity") VALUES (NULL, 11, 35, 7, 'vcr-gj-long-tube', '316L-GJ-MR4-TB4-12', 'VCR 长焊接接管', 'VCR Long Weld Tube Adapter', 'VCR ロング溶接ノズル', 'VCR 긴 용접 노즐', 'Tuyau long soudé VCR', 'فوهة لحام طويلة لجهاز VCR', '1/4" VCR 转 1/4" 对焊，L=43.2mm', '1/4" VCR to 1/4" butt weld, L=43.2mm', '1/4" VCR から 1/4" バット溶接、L=43.2mm', '1/4" VCR - 1/4" 버트 용접, L=43.2mm', 'Magnétoscope 1/4 "vers soudage à butte 1/4", L =43,2 mm', '1/4 بوصة VCR إلى 1/4 بوصة لحام بعقب ، L = 43.2 مم', 'VCR 转对焊长接管，一端 VCR 阳螺纹，一端 1/4" 对焊口，长度 43.2mm。', 'VCR to butt-weld long adapter, VCR male end to 1/4" weld end, L=43.2mm.', 'VCR から突き合わせ溶接された長いノズル、一端に VCR 雄ねじ、一端に 1/4 インチの突き合わせ溶接ジョイント、長さ 43.2mm。', '한쪽 끝에 VCR 수 나사산, 한쪽 끝에 1/4" 버트 용접 조인트가 있는 VCR - 버트 용접 긴 파이프, 길이 43.2mm.', 'Tuyau long de soudage à butte VCR, filetage mâle VCR à une extrémité, joint de soudage à butte de 1/4 "à l''autre extrémité, longueur 43,2 mm.', 'أنبوب طويل من جهاز VCR إلى لحام بعقب ، مع خيط ذكر لجهاز VCR في أحد الطرفين ووصلة لحام بعقب مقاس 1/4 بوصة في أحد الطرفين ، بطول 43.2 مم.', '<p>长焊接接管将 VCR 面密封连接转换为对焊连接，便于管道布局与焊接安装。</p><p>316L 材质，标准/EP 表面可选，用于超高纯管路系统。</p>', '<p>Long weld tube adapter converts VCR face seal to butt weld connection for flexible piping layout.</p><p>316L, standard or EP finish, for UHP tubing systems.</p>', '<p>長い溶接ノズルは、VCR 面シール接続を突き合わせ溶接接続に変換し、配管レイアウトと溶接設置を容易にします。</p><p>316L 素材、標準/EP 仕上げがオプション、超高純度ライン システム用。</p>', '<p>긴 용접 노즐은 VCR 면 밀봉 연결을 버트 용접 연결으로 변환하여 파이프 배치 및 용접 설치를 용이하게 합니다.</p><p>316L 재질, 초고순도 라인 시스템용 표준/EP 표면 옵션.</p>', '<p>Le long raccord de soudage convertit la connexion d''étanchéité de la surface du magnétoscope en une connexion de soudage à butte, ce qui facilite la disposition des tuyaux et l''installation du soudage.</p><p>Matériau 316L, surface standard/EP en option pour les systèmes de canalisation ultra haute pureté.</p>', '<p>تقوم الفوهات الملحومة الطويلة بتحويل اتصالات ختم سطح VCR إلى اتصالات لحام بعقب لتسهيل تخطيط الأنابيب وتركيب اللحام.</p><p>مادة 316L ، سطح قياسي/EP اختياري ، لأنظمة خطوط الأنابيب فائقة النقاء.</p>', '["VCR 转对焊", "L=43.2mm", "316L 材质"]', '["VCR to weld", "L=43.2mm", "316L material"]', '["VCR回転バット溶接", "L=43.2mm", "316L 材質"]', '["VCR 회전 버트 용접", "L=43.2mm", "316L 재질"]', '["Magnétoscope au soudage à butte", "L =43,2 mm", "Matériau 316L"]', NULL, NULL, NULL, NULL, false, '/uploads/oem/GJ_1.jpg', NULL, NULL, NULL, NULL, NULL, NULL, 1, NULL, NULL, NULL, NULL, NULL, NULL, '[{"name": "口径", "value": "1/4\"", "nameAr": "عيار", "nameEn": "Size", "nameFr": "Calibre", "nameJa": "口径", "nameKo": "구경", "valueAr": "1/4\"", "valueEn": "1/4\"", "valueFr": "1/4\"", "valueJa": "1/4\"", "valueKo": "1/4\""}, {"name": "长度", "value": "43.2mm", "nameAr": "الطول", "nameEn": "Length", "nameFr": "longueur", "nameJa": "長さ", "nameKo": "길이", "valueAr": "43.2mm", "valueEn": "43.2mm", "valueFr": "43.2mm", "valueJa": "43.2mm", "valueKo": "43.2mm"}, {"name": "材质", "value": "316L", "nameAr": "المواد", "nameEn": "Material", "nameFr": "Matériel", "nameJa": "材質", "nameKo": "재료", "valueAr": "316L", "valueEn": "316L", "valueFr": "316L", "valueJa": "316L", "valueKo": "316L"}]', 11, 'published', NULL, '2026-09-07 10:59:24.504', '2026-09-07 10:59:24.504', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO public.products ("siteId", id, "tabId", "categoryId", slug, model, name, "nameEn", "nameJa", "nameKo", "nameFr", "nameAr", subtitle, "subtitleEn", "subtitleJa", "subtitleKo", "subtitleFr", "subtitleAr", summary, "summaryEn", "summaryJa", "summaryKo", "summaryFr", "summaryAr", description, "descriptionEn", "descriptionJa", "descriptionKo", "descriptionFr", "descriptionAr", features, "featuresEn", "featuresJa", "featuresKo", "featuresFr", "featuresAr", images, price, "priceTiers", "isParts", "coverImage", video, frames360, "manualUrl", "priceMin", "priceMax", "priceUnit", moq, "priceNote", "priceNoteEn", "priceNoteJa", "priceNoteKo", "priceNoteFr", "priceNoteAr", specs, "sortOrder", status, "publishedAt", "createdAt", "updatedAt", "seoTitle", "seoTitleJa", "seoTitleKo", "seoTitleFr", "seoTitleAr", "seoTitleEn", "seoDescription", "seoDescriptionJa", "seoDescriptionKo", "seoDescriptionFr", "seoDescriptionAr", "seoDescriptionEn", "seoKeywords", "seoKeywordsJa", "seoKeywordsKo", "seoKeywordsFr", "seoKeywordsAr", "seoKeywordsEn", "geoRegion", "geoCity") VALUES (NULL, 34, 37, 9, 'ald-atomic-layer-deposition', '316L-ALD Series', '原子层沉积隔膜阀', 'atomic layer deposition diaphragm valve', '原子層堆積ダイヤフラム弁', '원자층 증착 다이어프램 밸브', 'Vanne à membrane de dépôt de couche atomique', 'صمام الحجاب الحاجز ترسيب الطبقة الذرية', 'ALD 专用，CV 0.27 / 0.62', 'ALD specific, CV 0.27 / 0.62', 'ALD 専用、CV 0.27 / 0.62', 'ALD 전용, CV 0.27 / 0.62', 'Spécifique ALD, CV 0,27/0,62', 'خاص بـ ALD ، CV 0.27 / 0.62', '专为原子层沉积（ALD）工艺设计的隔膜阀，工作压力最高 1MPa，流量系数 CV 0.27 / 0.62。极小的内腔容积与快速响应特性，适用于 ALD / CVD 前驱体精确输送与脉冲控制。', 'Diaphragm valve designed specifically for atomic layer deposition (ALD) processes, with a maximum operating pressure of 1MPa and a flow coefficient CV of 0.27 / 0.62. Extremely small lumen volume and fast response characteristics for precise delivery and pulse control of ALD/CVD precursors.', '原子層堆積 (ALD) プロセス用に設計されたダイヤフラム バルブは、最大 1MPa の動作圧力と流量係数 CV 0.27 / 0.62 です。極めて小さな内腔容積と高速応答特性により、ALD/CVD前駆体の正確な送達とパルス制御に適しています。', '원자층 증착(ALD) 공정을 위해 특별히 설계된 다이어프램 밸브, 최대 1MPa의 작동 압력, 유량 계수 CV 0.27/0.62. ALD/CVD 전구체의 정확한 전달 및 펄스 제어를 위한 매우 작은 내부 공동 부피와 빠른 응답 특성.', 'Vanne à membrane spécialement conçue pour le procédé de dépôt de couche atomique (ALD) avec une pression de fonctionnement allant jusqu''à 1 MPa et un coefficient de débit CV 0,27/0,62. Le volume de cavité interne extrêmement petit et les caractéristiques de réponse rapide conviennent à la livraison précise et au contrôle des impulsions des précurseurs ALD/CVD.', 'صمام الحجاب الحاجز مصمم خصيصًا لعملية ترسيب الطبقة الذرية (ALD) مع ضغط تشغيل يصل إلى 1 ميجا باسكال ومعامل تدفق CV 0.27 / 0.62. حجم التجويف الصغير للغاية وخصائص الاستجابة السريعة مناسبة للتوصيل الدقيق والتحكم في النبض لسلائف ALD / CVD.', '<p>原子层沉积隔膜阀专为 ALD 工艺优化，极小的内部容积确保前驱体剂量精确，阀座与隔膜材料经特殊选型，适应腐蚀性前驱体介质。</p><p>工作压力最高 1MPa，CV 0.27 / 0.62 两种规格可选，适用于半导体薄膜沉积工艺气体控制。</p>', '<p>Atomic layer deposition diaphragm valves are optimized for ALD processes. Their extremely small internal volume ensures precise precursor dosing. The valve seat and diaphragm materials are specially selected to adapt to corrosive precursor media.</p><p>Maximum working pressure 1MPa, CV 0.27 / 0.62 specifications available, suitable for gas control in semiconductor thin film deposition processes.</p>', '<p>ALD プロセス用に最適化された原子層蒸着ダイヤフラム バルブは、極めて小さな内部容積により正確な前駆体投与が保証され、シートとダイヤフラムの材料は腐食性の前駆体媒体に適応するように特別に選択されています。</p><p>動作圧力は最大1MPa、CV 0.27 / 0.62の2つの仕様から選択でき、半導体薄膜成膜プロセスのガス制御に適しています。</p>', '<p>ALD 공정에 최적화된 원자층 증착 다이어프램 밸브는 매우 작은 내부 부피로 정확한 전구체 투여량을 보장하며, 밸브 시트와 다이어프램 재료는 부식성 전구체 매체에 적응하도록 특별히 선택되었습니다.</p><p>작동압력 최대 1MPa, CV 0.27 / 0.62 두 가지 사양 선택 가능하며 반도체 박막 증착 공정 가스 제어에 적합합니다.</p>', '<p>Les vannes à membrane à dépôt de couche atomique sont spécialement optimisées pour le processus ALD. Le volume interne extrêmement petit garantit une dose précise de précurseur. Les matériaux du siège et du diaphragme sont spécialement sélectionnés pour s''adapter aux milieux précurseurs corrosifs.</p><p>Pression de travail jusqu''à 1MPa, CV 0,27/0,62 Deux spécifications sont disponibles, adaptées au contrôle du gaz dans le processus de dépôt de film mince à semi-conducteurs.</p>', '<p>تم تحسين صمام الحجاب الحاجز لترسيب الطبقة الذرية خصيصًا لعملية ALD ، ويضمن الحجم الداخلي الصغير جدًا جرعة دقيقة من السلائف ، ويتم اختيار مواد المقعد والحجاب الحاجز خصيصًا للتكيف مع وسائط السلائف المسببة للتآكل.</p><p>يصل ضغط العمل إلى 1MPa ، CV 0.27 / 0.62 مواصفات اختيارية ، مناسبة للتحكم في الغاز في عملية ترسيب فيلم أشباه الموصلات.</p>', '["ALD 工艺专用", "极小内腔容积", "快速响应", "CV 0.27 / 0.62"]', '["ALD process specific", "Minimal lumen volume", "Fast response", "CV 0.27 / 0.62"]', '["ALD プロセス専用", "極小内腔容積", "迅速応答", "CV 0.27 / 0.62"]', '["ALD 공정 전용", "최소 내공 부피", "빠른 응답", "CV 0.27 / 0.62"]', '["Spécifique pour le processus ALD", "Volume luminal extrêmement petit", "Réponse rapide", "CV 0,27/0,62"]', '["مخصص لعملية ALD", "حجم تجويف صغير للغاية", "استجابة سريعة", "السيرة الذاتية 0.27 / 0.62"]', NULL, NULL, NULL, false, '/uploads/oem/dv12a-mr4.jpg', NULL, NULL, NULL, NULL, NULL, NULL, 1, NULL, NULL, NULL, NULL, NULL, NULL, '[{"name": "工作压力", "value": "MAX. 1MPa", "nameAr": "ضغط العمل", "nameEn": "working pressure", "nameFr": "Pression de travail", "nameJa": "仕事のストレス", "nameKo": "업무 스트레스", "valueAr": "ماكس. 1 ميجا باسكال", "valueEn": "MAX. 1MPa", "valueFr": "MAX. 1MPa", "valueJa": "マックス1MPa", "valueKo": "최대. 1MPa"}, {"name": "流量系数 CV", "value": "0.27 / 0.62", "nameAr": "معامل التدفق السيرة الذاتية", "nameEn": "Flow coefficient CV", "nameFr": "Coefficient de débit CV", "nameJa": "流量係数 CV", "nameKo": "유량 계수 CV", "valueAr": "0.27/0.62", "valueEn": "0.27/0.62", "valueFr": "0.27/0.62", "valueJa": "0.27/0.62", "valueKo": "0.27/0.62"}, {"name": "适用工艺", "value": "ALD / CVD", "nameAr": "عملية قابلة للتطبيق", "nameEn": "applicable process", "nameFr": "Processus applicable", "nameJa": "適用プロセス", "nameKo": "적용 가능한 공정", "valueAr": "ALD / الأمراض القلبية الوعائية", "valueEn": "ALD / CVD", "valueFr": "ALD/CVD", "valueJa": "ALD / CVD", "valueKo": "ALD / CVD"}, {"name": "阀座材料", "value": "PCTFE / PFA", "nameAr": "مواد مقعد الصمام", "nameEn": "valve seat material", "nameFr": "Matériau du siège", "nameJa": "バルブシート材料", "nameKo": "밸브 시트 재료", "valueAr": "PCTFE / PFA", "valueEn": "PCTFE/PFA", "valueFr": "PCTFE/PFA", "valueJa": "PCTFE / PFA", "valueKo": "PCTFE / PFA"}]', 34, 'published', '2026-09-08 18:51:45.308', '2026-09-08 18:51:45.308', '2026-09-08 18:51:45.308', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO public.products ("siteId", id, "tabId", "categoryId", slug, model, name, "nameEn", "nameJa", "nameKo", "nameFr", "nameAr", subtitle, "subtitleEn", "subtitleJa", "subtitleKo", "subtitleFr", "subtitleAr", summary, "summaryEn", "summaryJa", "summaryKo", "summaryFr", "summaryAr", description, "descriptionEn", "descriptionJa", "descriptionKo", "descriptionFr", "descriptionAr", features, "featuresEn", "featuresJa", "featuresKo", "featuresFr", "featuresAr", images, price, "priceTiers", "isParts", "coverImage", video, frames360, "manualUrl", "priceMin", "priceMax", "priceUnit", moq, "priceNote", "priceNoteEn", "priceNoteJa", "priceNoteKo", "priceNoteFr", "priceNoteAr", specs, "sortOrder", status, "publishedAt", "createdAt", "updatedAt", "seoTitle", "seoTitleJa", "seoTitleKo", "seoTitleFr", "seoTitleAr", "seoTitleEn", "seoDescription", "seoDescriptionJa", "seoDescriptionKo", "seoDescriptionFr", "seoDescriptionAr", "seoDescriptionEn", "seoKeywords", "seoKeywordsJa", "seoKeywordsKo", "seoKeywordsFr", "seoKeywordsAr", "seoKeywordsEn", "geoRegion", "geoCity") VALUES (NULL, 35, 38, 10, 'prt2-small-flow-sensitive', '316L-PRT2C-SMR4', '小流量灵敏减压阀', 'small flow sensitive pressure reducing valve', '小流量感応減圧弁', '작은 흐름 민감한 압력 감소 밸브', 'Réducteur de pression sensible au petit débit', 'صمام تخفيض الضغط الحساس للتدفق الصغير', '联接式膜片，入口 24.1MPa，CV 0.13 / 0.16', 'Coupling diaphragm, inlet 24.1MPa, CV 0.13 / 0.16', 'カップリングダイヤフラム、入口24.1MPa、CV 0.13 / 0.16', '연결형 다이어프램, 입구 24.1MPa, CV 0.13 / 0.16', 'Diaphragme raccordé, entrée 24,1 MPa, CV 0,13/0,16', 'الحجاب الحاجز المتصل ، مدخل 24.1 ميجا باسكال ، السيرة الذاتية 0.13/0.16', 'PRT2 系列小流量灵敏减压阀，联接式膜片设计，最大入口压力 24.1MPa（3500psig），流量系数 CV 0.13 / 0.16。阀体 316L/316LVAR，膜片与阀芯采用 Hastelloy，适用于高纯气体精密压力调节。', 'PRT2 Series Small Flow Sensitive Pressure Reducing Valve, Coupling Diaphragm Design, Maximum Inlet Pressure 24.1MPa (3500psig), Flow Coefficient CV 0.13 / 0.16. Valve body 316L/316LVAR, diaphragm and valve core made of Hastelloy, suitable for precision pressure regulation of high-purity gases.', 'PRT2 シリーズ小流量感応減圧弁、結合ダイヤフラム設計、最大入口圧力 24.1MPa (3500psig)、流量係数 CV 0.13 / 0.16。バルブボディ 316L/316LVAR、ダイヤフラムとスプールは Hastelloy で作られており、高純度ガスの精密な圧力調整に適しています。', 'PRT2 시리즈 작은 흐름에 민감한 감압 밸브, 결합 다이어프램 설계, 최대 입구 압력 24.1MPa(3500psig), 유량 계수 CV 0.13/0.16. 밸브 본체 316L/316LVAR, 다이어프램 및 스풀은 고순도 가스의 정밀 압력 조절을 위해 Hastelloy로 제작되었습니다.', 'Vanne réductrice de pression sensible à faible débit série PRT2, conception à diaphragme connecté, pression d''entrée maximale de 24,1 MPa (3500 psig), coefficient de débit CV 0,13/0,16. Le corps de vanne 316L/316LVAR, le diaphragme et le noyau de vanne sont en Hastelloy, qui convient à un réglage de pression de précision des gaz de haute pureté.', 'صمام تخفيض الضغط الحساس للتدفق الصغير من سلسلة PRT2 ، تصميم الحجاب الحاجز المقترن ، الحد الأقصى لضغط المدخل 24.1 ميجا باسكال (3500psig)، معامل التدفق CV 0.13 / 0.16. جسم الصمام 316L/316LVAR ، الحجاب الحاجز والقلب مصنوع من Hastelloy ، وهو مناسب لتنظيم الضغط الدقيق للغاز عالي النقاء.', '<p>PRT2 系列小流量灵敏减压阀适用于高纯气体的压力调节，入口压力可达 3500psig。膜片和阀芯为联结一体式，提升调节稳定性。</p><p>阀体材质 316L/316LVAR，膜片和阀芯采用 Hastelloy，出口压力 10-300psig 多档可选。</p>', '<p>The PRT2 series low-flow sensitive pressure reducing valves are suitable for pressure regulation of high-purity gases, with inlet pressures up to 3500psig. The diaphragm and valve core are integrally connected, improving adjustment stability.</p><p>The valve body material is 316L/316LVAR, the diaphragm and valve core are made of Hastelloy, and the outlet pressure is 10-300psig with multiple settings available.</p>', '<p>PRT2 シリーズの小流量感応減圧バルブは、入口圧力が最大 3500psig の高純度ガスの圧力調整に適しています。ダイヤフラムとバルブコアを一体に接続し、調整安定性を向上させます。</p><p>バルブ本体材質は316L/316LVAR、ダイヤフラムとバルブスプリングはHastelloyで作られており、出口圧力は10~300psigの複数のレベルから選択できます。</p>', '<p>PRT2 시리즈 소유량 민감한 압력 감소 밸브는 최대 3500psig의 입구 압력을 가진 고순도 가스의 압력 조절에 적합합니다. 다이어프램과 밸브 코어는 일체로 연결되어 조정 안정성을 향상시킵니다.</p><p>밸브 본체 재질 316L/316LVAR, 다이어프램 및 스풀은 Hastelloy, 출구 압력 10-300psig 다중 단계 선택.</p>', '<p>Les vannes réductrices de pression sensibles au petit débit de la série PRT2 conviennent à la régulation de la pression des gaz de haute pureté, et la pression d''entrée peut atteindre 3500 psig. Le diaphragme et le noyau de la vanne sont reliés d''une seule pièce pour améliorer la stabilité du réglage.</p><p>Le matériau du corps de la vanne est 316L/316LVAR, le diaphragme et le noyau de la vanne sont en Hastelloy et la pression de sortie est de 10 à 300psig et plusieurs niveaux sont disponibles.</p>', '<p>صمامات تخفيض الضغط الحساسة للتدفق الصغير من سلسلة PRT2 مناسبة لتنظيم ضغط الغازات عالية النقاء ، مع ضغط مدخل يصل إلى 3500 رطل لكل بوصة مربعة. يتم توصيل الحجاب الحاجز وقلب الصمام بشكل متكامل لتحسين استقرار التعديل.</p><p>مادة جسم الصمام 316L/316LVAR ، الحجاب الحاجز وقلب الصمام مصنوع من Hastelloy ، وضغط المخرج 10-300psig متعدد المستويات اختياري.</p>', '["联接式膜片设计", "入口压力 24.1MPa", "Hastelloy 膜片与阀芯", "316L / 316LVAR 阀体", "GP / HP / UHP 工艺"]', '["Coupling Diaphragm Design", "Inlet Pressure 24.1MPa", "Hastelloy Diaphragm & Core", "316L / 316LVAR Body", "GP / HP / UHP Process"]', '["結合ダイヤフラム設計", "入口圧力 24.1MPa", "Hastelloy ダイヤフラムとスプリング", "316L / 316LVAR バルブボディ", "GP / HP / UHPプロセス"]', '["결합형 다이어프램 설계", "입구 압력 24.1MPa", "Hastelloy 다이어프램 및 스풀", "316L / 316LVAR 밸브 본체", "GP / HP / UHP 공정"]', '["Conception de diaphragme connecté", "Pression d''entrée 24,1 MPa", "Diaphragme et cartouche Hastelloy", "Corps de vanne 316L/316LVAR", "Processus GP/HP/UHP"]', '["تصميم الحجاب الحاجز المتصل", "ضغط المدخل 24.1 ميجا باسكال", "الحجاب الحاجز وقلب الصمام Hastelloy", "جسم الصمام 316L / 316LVAR", "عملية GP / HP / UHP"]', NULL, NULL, NULL, false, '/uploads/oem/prt1-mr4.jpg', NULL, NULL, NULL, NULL, NULL, NULL, 1, NULL, NULL, NULL, NULL, NULL, NULL, '[{"name": "最大入口压力", "value": "24.1MPa（3500psig）", "nameAr": "الحد الأقصى لضغط المدخل", "nameEn": "Maximum inlet pressure", "nameFr": "Pression d''entrée maximale", "nameJa": "最大入口圧力", "nameKo": "최대 입구 압력", "valueAr": "24.1 ميجا باسكال (3500psg)", "valueEn": "24.1MPa (3500psig)", "valueFr": "24,1 MPa (3500 psig)", "valueJa": "24.1MPa（3500psig）", "valueKo": "24.1MPa (3500psig)"}, {"name": "流量系数 CV", "value": "0.13 / 0.16", "nameAr": "معامل التدفق السيرة الذاتية", "nameEn": "Flow coefficient CV", "nameFr": "Coefficient de débit CV", "nameJa": "流量係数 CV", "nameKo": "유량 계수 CV", "valueAr": "0.13/0.16", "valueEn": "0.13/0.16", "valueFr": "0.13/0.16", "valueJa": "0.13/0.16", "valueKo": "0.13/0.16"}, {"name": "出口压力", "value": "10、30、60、100、150、300psig", "nameAr": "ضغط المخرج", "nameEn": "outlet pressure", "nameFr": "Pression de sortie", "nameJa": "出口圧力", "nameKo": "출구 압력", "valueAr": "10 ، 30 ، 60 ، 100 ، 150 ، 300psig", "valueEn": "10, 30, 60, 100, 150, 300psig", "valueFr": "10, 30, 60, 100, 150, 300 psig", "valueJa": "10、30、60、100、150、300psig", "valueKo": "10, 30, 60, 100, 150, 300psig"}, {"name": "阀体", "value": "316L / 316LVAR", "nameAr": "جسم الصمام", "nameEn": "valve body", "nameFr": "corps de soupape", "nameJa": "弁体", "nameKo": "밸브 본체", "valueAr": "316L / 316LVAR", "valueEn": "316L/316LVAR", "valueFr": "316L/316LVAR", "valueJa": "316L/316LVAR", "valueKo": "316L / 316LVAR"}, {"name": "膜片 / 阀芯", "value": "Hastelloy", "nameAr": "الحجاب الحاجز / خرطوشة", "nameEn": "Diaphragm / Core", "nameFr": "Diaphragme/noyau", "nameJa": "ダイヤフラム / スプール", "nameKo": "다이어프램 / 스풀", "valueAr": "هاستيلوي", "valueEn": "Hastelloy", "valueFr": "Hastelloy", "valueJa": "ハステロイ", "valueKo": "하스 텔로이"}]', 35, 'published', '2026-09-08 18:51:45.309', '2026-09-08 18:51:45.309', '2026-09-08 18:51:45.309', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO public.products ("siteId", id, "tabId", "categoryId", slug, model, name, "nameEn", "nameJa", "nameKo", "nameFr", "nameAr", subtitle, "subtitleEn", "subtitleJa", "subtitleKo", "subtitleFr", "subtitleAr", summary, "summaryEn", "summaryJa", "summaryKo", "summaryFr", "summaryAr", description, "descriptionEn", "descriptionJa", "descriptionKo", "descriptionFr", "descriptionAr", features, "featuresEn", "featuresJa", "featuresKo", "featuresFr", "featuresAr", images, price, "priceTiers", "isParts", "coverImage", video, frames360, "manualUrl", "priceMin", "priceMax", "priceUnit", moq, "priceNote", "priceNoteEn", "priceNoteJa", "priceNoteKo", "priceNoteFr", "priceNoteAr", specs, "sortOrder", status, "publishedAt", "createdAt", "updatedAt", "seoTitle", "seoTitleJa", "seoTitleKo", "seoTitleFr", "seoTitleAr", "seoTitleEn", "seoDescription", "seoDescriptionJa", "seoDescriptionKo", "seoDescriptionFr", "seoDescriptionAr", "seoDescriptionEn", "seoKeywords", "seoKeywordsJa", "seoKeywordsKo", "seoKeywordsFr", "seoKeywordsAr", "seoKeywordsEn", "geoRegion", "geoCity") VALUES (NULL, 36, 38, 10, 'prt3-large-flow-sensitive', '316L-PRT3C-SMR4', '大流量灵敏减压阀', 'high-flow sensitive pressure reducing valve', '大流量感応減圧弁', '대형 유량 민감한 압력 감소 밸브', 'Réducteur de pression sensible à grand débit', 'صمام تخفيض الضغط الحساس للتدفق الكبير', '联接式膜片，入口 11.7MPa，CV 0.9 / 1.1', 'Coupling diaphragm, inlet 11.7MPa, CV 0.9 / 1.1', 'カップリングダイヤフラム、入口11.7MPa、CV 0.9 / 1.1', '연결형 다이어프램, 입구 11.7MPa, 이력서 0.9/1.1', 'Diaphragme raccordé, entrée 11,7 MPa, CV 0,9/1,1', 'الحجاب الحاجز المتصل ، مدخل 11.7 ميجا باسكال ، السيرة الذاتية 0.9/1.1', 'PRT3 系列大流量灵敏减压阀，联接式膜片设计，最大入口压力 11.7MPa，流量系数 CV 0.9 / 1.1。Hastelloy 膜片与阀芯，适用于高纯气体大流量精密减压。', 'PRT3 Series High Flow Sensitive Pressure Reducing Valve, Coupling Diaphragm Design, Maximum Inlet Pressure 11.7MPa, Flow Coefficient CV 0.9 / 1.1. Hastelloy diaphragms and spools for high-purity gas high-flow precision decompression.', 'PRT3 シリーズ大流量感応減圧弁、結合ダイヤフラム設計、最大入口圧力 11.7MPa、流量係数 CV 0.9 / 1.1。Hastelloy ダイヤフラムとバルブカートリッジは、高純度ガスの大流量の精密減圧に適しています。', 'PRT3 시리즈 대형 유량 민감한 감압 밸브, 결합 다이어프램 설계, 최대 입구 압력 11.7MPa, 유량 계수 CV 0.9/1.1. 고순도 가스의 고유량 정밀 감압을 위한 Hastelloy 다이어프램 및 밸브 카트리지.', 'Vanne réductrice de pression sensible à grand débit série PRT3, conception à diaphragme connecté, pression d''entrée maximale 11,7 MPa, coefficient de débit CV 0,9/1,1. Le diaphragme et le noyau de vanne Hastelloy conviennent à la décompression précise de gaz de haute pureté à grand débit.', 'صمام تخفيض الضغط الحساس للتدفق الكبير من سلسلة PRT3 ، تصميم الحجاب الحاجز المقترن ، الحد الأقصى لضغط المدخل 11.7MPa ، معامل التدفق CV 0.9 / 1.1. الحجاب الحاجز والخرطوشة Hastelloy مناسبة لتخفيف الضغط الدقيق للتدفق الكبير للغاز عالي النقاء.', '<p>PRT3 系列大流量灵敏减压阀适用于高纯气体的大流量压力调节，入口压力最高 11.7MPa。</p><p>膜片和阀芯为联结一体式，采用 Hastelloy 材料，阀体 316L/316LVAR，适用于高纯与超高纯工艺气体系统。</p>', '<p>The PRT3 series high-flow sensitive pressure reducing valve is suitable for high-flow pressure regulation of high-purity gases, with a maximum inlet pressure of 11.7MPa.</p><p>The diaphragm and valve core are integrally connected, made of Hastelloy material, and the valve body is 316L/316LVAR, suitable for high-purity and ultra-high-purity process gas systems.</p>', '<p>PRT3 シリーズの大流量感応減圧弁は、入口圧力が最大 11.7MPa の高純度ガスの大流量圧力調整に適しています。</p><p>ダイヤフラムとバルブコアは一体型で、Hastelloy材料で作られており、バルブボディは316L/316LVARで、高純度と超高純度のプロセスガスシステムに適しています。</p>', '<p>PRT3 시리즈 대형 유량 민감한 압력 감소 밸브는 최대 11.7MPa의 입구 압력으로 고순도 가스의 대형 유량 압력 조절에 적합합니다.</p><p>다이어프램과 밸브 코어는 Hastelloy 소재를 사용하여 일체형으로 연결되어 있으며 밸브 본체는 316L/316LVAR로 고순도 및 초고순도 공정 가스 시스템에 적합합니다.</p>', '<p>Les vannes réductrices de pression sensibles à grand débit de la série PRT3 conviennent à la régulation de la pression de grand débit des gaz de haute pureté, avec une pression d''entrée allant jusqu''à 11,7 MPa.</p><p>Le diaphragme et le noyau de la vanne sont reliés et intégrés, en matériau Hastelloy, et le corps de la vanne est de 316L/316LVAR, qui convient aux systèmes de gaz de processus de haute pureté et d''ultra-haute pureté.</p>', '<p>صمامات تقليل الضغط الحساسة للتدفق الكبير من سلسلة PRT3 مناسبة لتنظيم ضغط التدفق الكبير للغاز عالي النقاء ، مع ضغط مدخل يصل إلى 11.7 ميجا باسكال.</p><p>الحجاب الحاجز وقلب الصمام متصلان ومتكاملان ، ويستخدمان مادة Hastelloy ، ويبلغ حجم جسم الصمام 316L/316LVAR ، وهو مناسب لأنظمة غاز المعالجة عالية النقاء وفائقة النقاء.</p>', '["联接式膜片设计", "入口压力 11.7MPa", "大流量 CV 0.9 / 1.1", "Hastelloy 膜片与阀芯"]', '["Coupling Diaphragm Design", "Inlet Pressure 11.7MPa", "High Flow CV 0.9 / 1.1", "Hastelloy Diaphragm & Core"]', '["連結ダイヤフラム設計", "入口圧力 11.7MPa", "大流量 CV 0.9 / 1.1", "Hastelloy ダイヤフラムとスプール"]', '["결합형 다이어프램 설계", "입구 압력 11.7MPa", "큰 유량 CV 0.9 / 1.1", "밸브 스풀과 Hastelloy 다이어프램"]', '["Conception de diaphragme connecté", "Pression d''entrée 11,7 MPa", "CV de débit élevé 0,9/1,1", "Diaphragme et cartouche Hastelloy"]', '["تصميم الحجاب الحاجز المتصل", "ضغط المدخل 11.7 ميجا باسكال", "معدل التدفق الكبير CV 0.9 / 1.1", "الحجاب الحاجز وقلب الصمام Hastelloy"]', NULL, NULL, NULL, false, '/uploads/oem/prt1-mr4.jpg', NULL, NULL, NULL, NULL, NULL, NULL, 1, NULL, NULL, NULL, NULL, NULL, NULL, '[{"name": "最大入口压力", "value": "11.7MPa", "nameAr": "الحد الأقصى لضغط المدخل", "nameEn": "Maximum inlet pressure", "nameFr": "Pression d''entrée maximale", "nameJa": "最大入口圧力", "nameKo": "최대 입구 압력", "valueAr": "11.7 ميجا باسكال", "valueEn": "11.7MPa", "valueFr": "11,7 MPa", "valueJa": "11.7MPa", "valueKo": "11.7MPa"}, {"name": "流量系数 CV", "value": "0.9 / 1.1", "nameAr": "معامل التدفق السيرة الذاتية", "nameEn": "Flow coefficient CV", "nameFr": "Coefficient de débit CV", "nameJa": "流量係数 CV", "nameKo": "유량 계수 CV", "valueAr": "0.9/1.1", "valueEn": "0.9/1.1", "valueFr": "0.9/1.1", "valueJa": "0.9/1.1", "valueKo": "0.9/1.1"}, {"name": "阀体", "value": "316L / 316LVAR", "nameAr": "جسم الصمام", "nameEn": "valve body", "nameFr": "corps de soupape", "nameJa": "弁体", "nameKo": "밸브 본체", "valueAr": "316L / 316LVAR", "valueEn": "316L/316LVAR", "valueFr": "316L/316LVAR", "valueJa": "316L/316LVAR", "valueKo": "316L / 316LVAR"}, {"name": "膜片 / 阀芯", "value": "Hastelloy", "nameAr": "الحجاب الحاجز / خرطوشة", "nameEn": "Diaphragm / Core", "nameFr": "Diaphragme/noyau", "nameJa": "ダイヤフラム / スプール", "nameKo": "다이어프램 / 스풀", "valueAr": "هاستيلوي", "valueEn": "Hastelloy", "valueFr": "Hastelloy", "valueJa": "ハステロイ", "valueKo": "하스 텔로이"}]', 36, 'published', '2026-09-08 18:51:45.309', '2026-09-08 18:51:45.309', '2026-09-08 18:51:45.309', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO public.products ("siteId", id, "tabId", "categoryId", slug, model, name, "nameEn", "nameJa", "nameKo", "nameFr", "nameAr", subtitle, "subtitleEn", "subtitleJa", "subtitleKo", "subtitleFr", "subtitleAr", summary, "summaryEn", "summaryJa", "summaryKo", "summaryFr", "summaryAr", description, "descriptionEn", "descriptionJa", "descriptionKo", "descriptionFr", "descriptionAr", features, "featuresEn", "featuresJa", "featuresKo", "featuresFr", "featuresAr", images, price, "priceTiers", "isParts", "coverImage", video, frames360, "manualUrl", "priceMin", "priceMax", "priceUnit", moq, "priceNote", "priceNoteEn", "priceNoteJa", "priceNoteKo", "priceNoteFr", "priceNoteAr", specs, "sortOrder", status, "publishedAt", "createdAt", "updatedAt", "seoTitle", "seoTitleJa", "seoTitleKo", "seoTitleFr", "seoTitleAr", "seoTitleEn", "seoDescription", "seoDescriptionJa", "seoDescriptionKo", "seoDescriptionFr", "seoDescriptionAr", "seoDescriptionEn", "seoKeywords", "seoKeywordsJa", "seoKeywordsKo", "seoKeywordsFr", "seoKeywordsAr", "seoKeywordsEn", "geoRegion", "geoCity") VALUES (NULL, 37, 38, 10, 'pre2-small-flow-sensitive', '316L-PRE2C-SMR4', '小流量灵敏减压阀', 'small flow sensitive pressure reducing valve', '小流量感応減圧弁', '작은 흐름 민감한 압력 감소 밸브', 'Réducteur de pression sensible au petit débit', 'صمام تخفيض الضغط الحساس للتدفق الصغير', '自由膜片，入口 24.1MPa，CV 0.13', 'Free diaphragm, inlet 24.1MPa, CV 0.13', 'フリーダイヤフラム、入口 24.1MPa、CV 0.13', '자유 다이어프램, 입구 24.1MPa, CV 0.13', 'Diaphragme libre, entrée 24,1 MPa, CV 0,13', 'الحجاب الحاجز الحر ، المدخل 24.1 ميجا باسكال ، السيرة الذاتية 0.13', 'PRE2 系列小流量灵敏减压阀，自由膜片设计，最大入口压力 24.1MPa（3500psig），流量系数 CV 0.13。阀体 316L/316LVAR，膜片与阀芯采用 Hastelloy，适用于高纯气体精密压力调节。', 'PRE2 Series Small Flow Sensitive Pressure Reducing Valve, Free Diaphragm Design, Maximum Inlet Pressure 24.1MPa (3500psig), Flow Coefficient CV 0.13. Valve body 316L/316LVAR, diaphragm and valve core made of Hastelloy, suitable for precision pressure regulation of high-purity gases.', 'PRE2 シリーズの小流量感応減圧弁、フリーダイヤフラム設計、最大入口圧力 24.1MPa (3500psig)、流量係数 CV 0.13。バルブボディ 316L/316LVAR、ダイヤフラムとスプールは Hastelloy で作られており、高純度ガスの精密な圧力調整に適しています。', '프리 다이어프램 설계, 최대 입구 압력 24.1MPa(3500psig), 유량 계수 CV 0.13을 갖춘 PRE2 시리즈 소형 유량 민감 감압 밸브. 밸브 본체 316L/316LVAR, 다이어프램 및 스풀은 고순도 가스의 정밀 압력 조절을 위해 Hastelloy로 제작되었습니다.', 'Vanne réductrice de pression sensible à petit débit série PRE2, conception à diaphragme libre, pression d''entrée maximale de 24,1 MPa (3500 psig), coefficient de débit CV 0,13. Le corps de vanne 316L/316LVAR, le diaphragme et le noyau de vanne sont en Hastelloy, qui convient à un réglage de pression de précision des gaz de haute pureté.', 'صمام تخفيض الضغط الحساس للتدفق الصغير من سلسلة PRE2 ، تصميم حجاب حاجز مجاني ، الحد الأقصى لضغط المدخل 24.1 ميجا باسكال (3500 رطل لكل بوصة مربعة)، معامل التدفق CV 0.13. جسم الصمام 316L/316LVAR ، الحجاب الحاجز والقلب مصنوع من Hastelloy ، وهو مناسب لتنظيم الضغط الدقيق للغاز عالي النقاء.', '<p>PRE2 系列小流量灵敏减压阀适用于高纯气体的压力调节，入口压力可达 3500psig。自由膜片设计提供稳定的输出压力。</p><p>阀体材质 316L/316LVAR，膜片和阀芯采用 Hastelloy，出口压力 10-300psig 多档可选。</p>', '<p>The PRE2 series low-flow sensitive pressure reducing valves are suitable for pressure regulation of high-purity gases, with inlet pressures up to 3500psig. Free diaphragm design provides stable output pressure.</p><p>The valve body material is 316L/316LVAR, the diaphragm and valve core are made of Hastelloy, and the outlet pressure is 10-300psig with multiple settings available.</p>', '<p>PRE2 シリーズの小流量感応減圧バルブは、入口圧力が最大 3500psig の高純度ガスの圧力調整に適しています。フリーダイヤフラム設計により、安定した出力圧力を提供します。</p><p>バルブ本体材質は316L/316LVAR、ダイヤフラムとバルブスプリングはHastelloyで作られており、出口圧力は10~300psigの複数のレベルから選択できます。</p>', '<p>PRE2 시리즈 소유량 민감한 압력 감소 밸브는 최대 3500psig의 입구 압력을 가진 고순도 가스의 압력 조절에 적합합니다. 자유로운 다이어프램 설계는 안정적인 출력 압력을 제공합니다.</p><p>밸브 본체 재질 316L/316LVAR, 다이어프램 및 스풀은 Hastelloy, 출구 압력 10-300psig 다중 단계 선택.</p>', '<p>Les vannes réductrices de pression sensibles au petit débit de la série PRE2 conviennent à la régulation de la pression des gaz de haute pureté, et la pression d''entrée peut atteindre 3500 psig. La conception du diaphragme libre fournit une pression de sortie stable.</p><p>Le matériau du corps de la vanne est 316L/316LVAR, le diaphragme et le noyau de la vanne sont en Hastelloy et la pression de sortie est de 10 à 300psig et plusieurs niveaux sont disponibles.</p>', '<p>صمامات تخفيض الضغط الحساسة للتدفق الصغير من سلسلة PRE2 مناسبة لتنظيم ضغط الغازات عالية النقاء ، مع ضغط مدخل يصل إلى 3500 رطل لكل بوصة مربعة. يوفر تصميم الحجاب الحاجز الحر ضغط إخراج مستقر.</p><p>مادة جسم الصمام 316L/316LVAR ، الحجاب الحاجز وقلب الصمام مصنوع من Hastelloy ، وضغط المخرج 10-300psig متعدد المستويات اختياري.</p>', '["自由膜片设计", "入口压力 24.1MPa", "Hastelloy 膜片与阀芯", "316L / 316LVAR 阀体"]', '["Free Diaphragm Design", "Inlet Pressure 24.1MPa", "Hastelloy Diaphragm & Spool", "316L / 316LVAR Body"]', '["フリーダイヤフラム設計", "入口圧力 24.1MPa", "ハステロイダイヤフラムとスプール", "316L / 316LVAR ボディ"]', '["자유 다이어프램 설계", "입구 압력 24.1MPa", "스풀과 Hastelloy 다이어프램", "316L / 316LVAR 바디"]', '["Conception de diaphragme libre", "Pression d''entrée 24,1 MPa", "Diaphragme et cartouche Hastelloy", "Corps de vanne 316L/316LVAR"]', '["تصميم الحجاب الحاجز المجاني", "ضغط المدخل 24.1 ميجا باسكال", "الحجاب الحاجز وقلب الصمام Hastelloy", "جسم الصمام 316L / 316LVAR"]', NULL, NULL, NULL, false, '/uploads/oem/pre1-mr4.jpg', NULL, NULL, NULL, NULL, NULL, NULL, 1, NULL, NULL, NULL, NULL, NULL, NULL, '[{"name": "最大入口压力", "value": "24.1MPa（3500psig）", "nameAr": "الحد الأقصى لضغط المدخل", "nameEn": "Maximum inlet pressure", "nameFr": "Pression d''entrée maximale", "nameJa": "最大入口圧力", "nameKo": "최대 입구 압력", "valueAr": "24.1 ميجا باسكال (3500psg)", "valueEn": "24.1MPa (3500psig)", "valueFr": "24,1 MPa (3500 psig)", "valueJa": "24.1MPa（3500psig）", "valueKo": "24.1MPa (3500psig)"}, {"name": "流量系数 CV", "value": "0.13", "nameAr": "معامل التدفق السيرة الذاتية", "nameEn": "Flow coefficient CV", "nameFr": "Coefficient de débit CV", "nameJa": "流量係数 CV", "nameKo": "유량 계수 CV", "valueAr": "0.13", "valueEn": "0.13", "valueFr": "0.13", "valueJa": "0.13", "valueKo": "0.13"}, {"name": "出口压力", "value": "10、30、60、100、150、300psig", "nameAr": "ضغط المخرج", "nameEn": "outlet pressure", "nameFr": "Pression de sortie", "nameJa": "出口圧力", "nameKo": "출구 압력", "valueAr": "10 ، 30 ، 60 ، 100 ، 150 ، 300psig", "valueEn": "10, 30, 60, 100, 150, 300psig", "valueFr": "10, 30, 60, 100, 150, 300 psig", "valueJa": "10、30、60、100、150、300psig", "valueKo": "10, 30, 60, 100, 150, 300psig"}, {"name": "膜片 / 阀芯", "value": "Hastelloy", "nameAr": "الحجاب الحاجز / خرطوشة", "nameEn": "Diaphragm / Core", "nameFr": "Diaphragme/noyau", "nameJa": "ダイヤフラム / スプール", "nameKo": "다이어프램 / 스풀", "valueAr": "هاستيلوي", "valueEn": "Hastelloy", "valueFr": "Hastelloy", "valueJa": "ハステロイ", "valueKo": "하스 텔로이"}]', 37, 'published', '2026-09-08 18:51:45.31', '2026-09-08 18:51:45.31', '2026-09-08 18:51:45.31', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO public.products ("siteId", id, "tabId", "categoryId", slug, model, name, "nameEn", "nameJa", "nameKo", "nameFr", "nameAr", subtitle, "subtitleEn", "subtitleJa", "subtitleKo", "subtitleFr", "subtitleAr", summary, "summaryEn", "summaryJa", "summaryKo", "summaryFr", "summaryAr", description, "descriptionEn", "descriptionJa", "descriptionKo", "descriptionFr", "descriptionAr", features, "featuresEn", "featuresJa", "featuresKo", "featuresFr", "featuresAr", images, price, "priceTiers", "isParts", "coverImage", video, frames360, "manualUrl", "priceMin", "priceMax", "priceUnit", moq, "priceNote", "priceNoteEn", "priceNoteJa", "priceNoteKo", "priceNoteFr", "priceNoteAr", specs, "sortOrder", status, "publishedAt", "createdAt", "updatedAt", "seoTitle", "seoTitleJa", "seoTitleKo", "seoTitleFr", "seoTitleAr", "seoTitleEn", "seoDescription", "seoDescriptionJa", "seoDescriptionKo", "seoDescriptionFr", "seoDescriptionAr", "seoDescriptionEn", "seoKeywords", "seoKeywordsJa", "seoKeywordsKo", "seoKeywordsFr", "seoKeywordsAr", "seoKeywordsEn", "geoRegion", "geoCity") VALUES (NULL, 38, 38, 10, 'pre3-large-flow-sensitive', '316L-PRE3C-SMR4', '大流量灵敏减压阀', 'high-flow sensitive pressure reducing valve', '大流量感応減圧弁', '대형 유량 민감한 압력 감소 밸브', 'Réducteur de pression sensible à grand débit', 'صمام تخفيض الضغط الحساس للتدفق الكبير', '自由膜片，入口 4.14MPa，CV 1.1', 'Free diaphragm, inlet 4.14MPa, CV 1.1', 'フリーダイヤフラム、入口 4.14MPa、CV 1.1', '자유 다이어프램, 입구 4.14MPa, CV 1.1', 'Diaphragme libre, entrée 4.14MPa, CV 1.1', 'الحجاب الحاجز الحر ، مدخل 4.14 ميجا باسكال ، CV 1.1', 'PRE3 系列大流量灵敏减压阀，自由膜片设计，最大入口压力 4.14MPa，流量系数 CV 1.1。Hastelloy 膜片与阀芯，适用于高纯气体大流量精密减压。', 'PRE3 series high-flow sensitive pressure reducing valve, free diaphragm design, maximum inlet pressure 4.14MPa, flow coefficient CV 1.1. Hastelloy diaphragms and spools for high-purity gas high-flow precision decompression.', 'PRE3 シリーズ大流量感応減圧弁、フリーダイヤフラム設計、最大入口圧力 4.14MPa、流量係数 CV 1.1。Hastelloy ダイヤフラムとバルブカートリッジは、高純度ガスの大流量の精密減圧に適しています。', '프리 다이어프램 설계, 최대 입구 압력 4.14MPa, 유량 계수 CV 1.1을 갖춘 PRE3 시리즈 대형 유량 민감 감압 밸브. 고순도 가스의 고유량 정밀 감압을 위한 Hastelloy 다이어프램 및 밸브 카트리지.', 'Vanne réductrice de pression sensible à grand débit série PRE3, conception à diaphragme libre, pression d''entrée maximale 4,14 MPa, coefficient de débit CV 1,1. Le diaphragme et le noyau de vanne Hastelloy conviennent à la décompression précise de gaz de haute pureté à grand débit.', 'صمام تخفيض الضغط الحساس للتدفق الكبير من سلسلة PRE3 ، تصميم الحجاب الحاجز الحر ، الحد الأقصى لضغط المدخل 4.14MPa ، معامل التدفق CV 1.1. الحجاب الحاجز والخرطوشة Hastelloy مناسبة لتخفيف الضغط الدقيق للتدفق الكبير للغاز عالي النقاء.', '<p>PRE3 系列大流量灵敏减压阀适用于高纯气体的大流量压力调节，入口压力最高 4.14MPa。</p><p>自由膜片设计，膜片和阀芯采用 Hastelloy，阀体 316L/316LVAR，适用于高纯与超高纯工艺气体系统。</p>', '<p>The PRE3 series high-flow sensitive pressure reducing valve is suitable for high-flow pressure regulation of high-purity gases, with a maximum inlet pressure of 4.14MPa.</p><p>Free diaphragm design, diaphragm and valve core made of Hastelloy, valve body 316L/316LVAR, suitable for high-purity and ultra-high-purity process gas systems.</p>', '<p>PRE3 シリーズの大流量感応減圧弁は、入口圧力が最大 4.14MPa の高純度ガスの大流量圧力調整に適しています。</p><p>高純度および超高純度プロセスガスシステムに適した、Hastelloy を使用したダイヤフラムとバルブスプリングの自由なダイヤフラム設計、バルブボディ 316L/316LVAR。</p>', '<p>PRE3 시리즈 대형 유량 민감한 압력 감소 밸브는 최대 4.14MPa의 입구 압력으로 고순도 가스의 대형 유량 압력 조절에 적합합니다.</p><p>자유로운 다이어프램 설계, 다이어프램 및 밸브 스풀은 Hastelloy, 밸브 본체 316L/316LVAR를 사용하여 고순도 및 초고순도 공정 가스 시스템에 적합합니다.</p>', '<p>Les vannes réductrices de pression sensibles à grand débit de la série PRE3 conviennent à la régulation de la pression de grand débit des gaz de haute pureté, avec une pression d''entrée allant jusqu''à 4,14 MPa.</p><p>Conception de diaphragme libre, diaphragme et noyau de vanne en Hastelloy, corps de vanne 316L/316LVAR, adapté aux systèmes de gaz de processus de haute pureté et ultra-haute pureté.</p>', '<p>صمامات تخفيض الضغط الحساسة للتدفق الكبير من سلسلة PRE3 مناسبة لتنظيم ضغط التدفق الكبير للغاز عالي النقاء ، مع ضغط مدخل يصل إلى 4.14 ميجا باسكال.</p><p>تصميم الحجاب الحاجز المجاني ، الحجاب الحاجز وقلب الصمام مصنوع من Hastelloy ، وجسم الصمام 316L/316LVAR ، مناسب لأنظمة غاز المعالجة عالية النقاء وعالية النقاء للغاية.</p>', '["自由膜片设计", "入口压力 4.14MPa", "大流量 CV 1.1", "Hastelloy 膜片与阀芯"]', '["Free Diaphragm Design", "Inlet Pressure 4.14MPa", "High Flow CV 1.1", "Hastelloy Diaphragm & Core"]', '["フリーダイヤフラム設計", "入口圧力 4.14MPa", "大流量 CV 1.1", "ハステロイダイヤフラムとスプール"]', '["자유 다이어프램 설계", "입구 압력 4.14MPa", "대형 유량 CV 1.1", "밸브 스풀과 Hastelloy 다이어프램"]', '["Conception de diaphragme libre", "Pression d''entrée 4.14MPa", "CV de débit élevé 1.1", "Diaphragme et cartouche Hastelloy"]', '["تصميم الحجاب الحاجز المجاني", "ضغط المدخل 4.14 ميجا باسكال", "معدل التدفق الكبير CV 1.1", "الحجاب الحاجز وقلب الصمام Hastelloy"]', NULL, NULL, NULL, false, '/uploads/oem/pre1-mr4.jpg', NULL, NULL, NULL, NULL, NULL, NULL, 1, NULL, NULL, NULL, NULL, NULL, NULL, '[{"name": "最大入口压力", "value": "4.14MPa", "nameAr": "الحد الأقصى لضغط المدخل", "nameEn": "Maximum inlet pressure", "nameFr": "Pression d''entrée maximale", "nameJa": "最大入口圧力", "nameKo": "최대 입구 압력", "valueAr": "4.14 ميجا باسكال", "valueEn": "4.14MPa", "valueFr": "4,14 MPa", "valueJa": "4.14MPa", "valueKo": "4.14MPa"}, {"name": "流量系数 CV", "value": "1.1", "nameAr": "معامل التدفق السيرة الذاتية", "nameEn": "Flow coefficient CV", "nameFr": "Coefficient de débit CV", "nameJa": "流量係数 CV", "nameKo": "유량 계수 CV", "valueAr": "1.1", "valueEn": "1.1", "valueFr": "1.1", "valueJa": "1.1", "valueKo": "1.1"}, {"name": "阀体", "value": "316L / 316LVAR", "nameAr": "جسم الصمام", "nameEn": "valve body", "nameFr": "corps de soupape", "nameJa": "弁体", "nameKo": "밸브 본체", "valueAr": "316L / 316LVAR", "valueEn": "316L/316LVAR", "valueFr": "316L/316LVAR", "valueJa": "316L/316LVAR", "valueKo": "316L / 316LVAR"}, {"name": "膜片 / 阀芯", "value": "Hastelloy", "nameAr": "الحجاب الحاجز / خرطوشة", "nameEn": "Diaphragm / Core", "nameFr": "Diaphragme/noyau", "nameJa": "ダイヤフラム / スプール", "nameKo": "다이어프램 / 스풀", "valueAr": "هاستيلوي", "valueEn": "Hastelloy", "valueFr": "Hastelloy", "valueJa": "ハステロイ", "valueKo": "하스 텔로이"}]', 38, 'published', '2026-09-08 18:51:45.31', '2026-09-08 18:51:45.31', '2026-09-08 18:51:45.31', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO public.products ("siteId", id, "tabId", "categoryId", slug, model, name, "nameEn", "nameJa", "nameKo", "nameFr", "nameAr", subtitle, "subtitleEn", "subtitleJa", "subtitleKo", "subtitleFr", "subtitleAr", summary, "summaryEn", "summaryJa", "summaryKo", "summaryFr", "summaryAr", description, "descriptionEn", "descriptionJa", "descriptionKo", "descriptionFr", "descriptionAr", features, "featuresEn", "featuresJa", "featuresKo", "featuresFr", "featuresAr", images, price, "priceTiers", "isParts", "coverImage", video, frames360, "manualUrl", "priceMin", "priceMax", "priceUnit", moq, "priceNote", "priceNoteEn", "priceNoteJa", "priceNoteKo", "priceNoteFr", "priceNoteAr", specs, "sortOrder", status, "publishedAt", "createdAt", "updatedAt", "seoTitle", "seoTitleJa", "seoTitleKo", "seoTitleFr", "seoTitleAr", "seoTitleEn", "seoDescription", "seoDescriptionJa", "seoDescriptionKo", "seoDescriptionFr", "seoDescriptionAr", "seoDescriptionEn", "seoKeywords", "seoKeywordsJa", "seoKeywordsKo", "seoKeywordsFr", "seoKeywordsAr", "seoKeywordsEn", "geoRegion", "geoCity") VALUES (NULL, 12, 35, 7, 'vcr-gjs-short-tube', '316L-GJS-MR4-TB4-12', 'VCR 短焊接接管', 'VCR Short Weld Tube Adapter', 'VCR ショート溶接ノズル', 'VCR 짧은 용접 노즐', 'Tuyau de soudage court VCR', 'فوهة لحام قصيرة لجهاز VCR', '1/4" VCR 转 1/4" 对焊，L=27.9mm', '1/4" VCR to 1/4" butt weld, L=27.9mm', '1/4" VCR から 1/4" バット溶接、L=27.9mm', '1/4" VCR - 1/4" 버트 용접, L=27.9mm', 'Magnétoscope 1/4 "vers soudage à butte 1/4", L =27,9 mm', '1/4 بوصة VCR إلى 1/4 بوصة لحام بعقب ، L=27.9 مم', 'VCR 转对焊短接管，长度 27.9mm，适用于紧凑布局的高纯管路。', 'VCR to butt-weld short adapter, L=27.9mm for compact UHP layouts.', 'コンパクトなレイアウトの高純度ラインに適した、長さ 27.9mm の VCR から突合せ溶接短いノズル。', '컴팩트한 레이아웃의 고순도 라인에 적합한 길이 27.9mm의 VCR - 버트 용접 짧은 파이프.', 'Tuyau court soudé par VCR à butt, longueur 27,9 mm, adapté aux pipelines de haute pureté avec une disposition compacte.', 'أنبوب قصير من مسجل الفيديو إلى ملحوم بعقب ، بطول 27.9 مم ، مناسب للخطوط عالية النقاء ذات التخطيط المدمج.', '<p>短焊接接管适用于空间受限的高纯管路，一端 VCR 阳螺纹、一端对焊口。</p><p>316L 材质，金属面密封，洁净室包装。</p>', '<p>Short weld adapter for space-constrained UHP lines, VCR male to weld end.</p><p>316L, metal face seal, cleanroom packaged.</p>', '<p>短い溶接ノズルは、スペースが限られた高純度パイプラインに適しており、一端に VCR 雄ねじ、もう一端に突き合わせ溶接接合部が付いています。</p><p>316L素材、金属表面シール、クリーンルームパッケージ。</p>', '<p>짧은 용접 노즐은 공간이 제한된 고순도 파이프라인에 적합하며 한쪽 끝에 VCR 수 나사산과 한쪽 끝에 버트 용접 조인트가 있습니다.</p><p>316L 재질, 금속 표면 밀봉, 클린룸 포장.</p>', '<p>Les tuyaux soudés courts conviennent aux pipelines de haute pureté avec un espace limité, avec un filetage mâle VCR à une extrémité et un joint de soudage à l''autre extrémité.</p><p>Matériau 316L, scellement de surface métallique, emballage en salle blanche.</p>', '<p>الفوهات الملحومة القصيرة مناسبة لخطوط الأنابيب عالية النقاء ذات المساحة المحدودة ، مع خيط ذكر VCR في أحد الطرفين ووصلة لحام بعقب في الطرف الآخر.</p><p>مادة 316L ، مختومة السطح المعدني ، تعبئة الغرفة النظيفة.</p>', '["紧凑设计 L=27.9mm", "VCR 转对焊", "洁净室包装"]', '["Compact L=27.9mm", "VCR to weld", "Cleanroom packaged"]', '["コンパクト設計 L=27.9mm", "VCR回転バット溶接", "クリーンルーム用パッケージ"]', '["컴팩트 디자인 L=27.9mm", "VCR 투 버트 용접", "클린룸 포장"]', '["Conception compacte L =27,9 mm", "Magnétoscope au soudage à butte", "Emballage salle blanche"]', NULL, NULL, NULL, NULL, false, '/uploads/oem/GJ_8.png', NULL, NULL, NULL, NULL, NULL, NULL, 1, NULL, NULL, NULL, NULL, NULL, NULL, '[{"name": "口径", "value": "1/4\"", "nameAr": "عيار", "nameEn": "Size", "nameFr": "Calibre", "nameJa": "口径", "nameKo": "구경", "valueAr": "1/4\"", "valueEn": "1/4\"", "valueFr": "1/4\"", "valueJa": "1/4\"", "valueKo": "1/4\""}, {"name": "长度", "value": "27.9mm", "nameAr": "الطول", "nameEn": "Length", "nameFr": "longueur", "nameJa": "長さ", "nameKo": "길이", "valueAr": "27.9mm", "valueEn": "27.9mm", "valueFr": "27.9mm", "valueJa": "27.9mm", "valueKo": "27.9mm"}, {"name": "材质", "value": "316L", "nameAr": "المواد", "nameEn": "Material", "nameFr": "Matériel", "nameJa": "材質", "nameKo": "재료", "valueAr": "316L", "valueEn": "316L", "valueFr": "316L", "valueJa": "316L", "valueKo": "316L"}]', 12, 'published', NULL, '2026-09-07 10:59:24.507', '2026-09-07 10:59:24.507', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO public.products ("siteId", id, "tabId", "categoryId", slug, model, name, "nameEn", "nameJa", "nameKo", "nameFr", "nameAr", subtitle, "subtitleEn", "subtitleJa", "subtitleKo", "subtitleFr", "subtitleAr", summary, "summaryEn", "summaryJa", "summaryKo", "summaryFr", "summaryAr", description, "descriptionEn", "descriptionJa", "descriptionKo", "descriptionFr", "descriptionAr", features, "featuresEn", "featuresJa", "featuresKo", "featuresFr", "featuresAr", images, price, "priceTiers", "isParts", "coverImage", video, frames360, "manualUrl", "priceMin", "priceMax", "priceUnit", moq, "priceNote", "priceNoteEn", "priceNoteJa", "priceNoteKo", "priceNoteFr", "priceNoteAr", specs, "sortOrder", status, "publishedAt", "createdAt", "updatedAt", "seoTitle", "seoTitleJa", "seoTitleKo", "seoTitleFr", "seoTitleAr", "seoTitleEn", "seoDescription", "seoDescriptionJa", "seoDescriptionKo", "seoDescriptionFr", "seoDescriptionAr", "seoDescriptionEn", "seoKeywords", "seoKeywordsJa", "seoKeywordsKo", "seoKeywordsFr", "seoKeywordsAr", "seoKeywordsEn", "geoRegion", "geoCity") VALUES (NULL, 39, 40, 12, 'ft6-sintered-stainless-filter', '316L-FT6 Series', '不锈钢滤芯过滤器', 'Stainless steel filter element filter', 'ステンレス製フィルターカートリッジフィルター', '스테인레스 스틸 카트리지 필터', 'Filtre à cartouche en acier inoxydable', 'الفولاذ المقاوم للصدأ مرشح عنصر', '烧结金属滤芯 2.5nm，21.0MPa', 'Sintered metal filter element 2.5nm, 21.0MPa', '焼結金属フィルターエレメント 2.5nm、21.0MPa', '소결 금속 필터 요소 2.5nm, 21.0MPa', 'Élément filtrant en métal fritté 2,5 nm, 21,0 MPa', 'عنصر مرشح معدني متكلس 2.5 نانومتر ، 21.0 ميجا باسكال', 'FT6 系列不锈钢滤芯气体过滤器，工作压力最高 21.0MPa，烧结金属滤芯过滤精度 2.5 纳米。316L 全焊接结构，适用于超高纯气体深度过滤。', 'The FT6 series stainless steel filter element gas filter has a maximum working pressure of 21.0 MPa and a sintered metal filter element with a filtration accuracy of 2.5 nanometers. 316L fully welded structure, suitable for ultra-high purity gas depth filtration.', 'FT6 シリーズ ステンレス鋼カートリッジ ガス フィルター、最大動作圧力 21.0MPa、焼結金属カートリッジ濾過精度 2.5nm。316L 完全溶接構造で、超高純度ガスの深さろ過に適しています。', '최대 작동 압력 21.0MPa, 소결 금속 필터 필터 정확도 2.5nm를 갖춘 FT6 시리즈 스테인레스 스틸 필터 가스 필터. 초고순도 가스 깊이 여과를 위한 316L 완전 용접 구조.', 'Filtre à gaz à élément en acier inoxydable série FT6, pression de travail jusqu''à 21,0 MPa, élément en métal fritté avec une précision de filtration de 2,5 nm. Structure entièrement soudée 316L, adaptée à la filtration en profondeur de gaz ultra-haute pureté.', 'مرشح غاز عنصر الفولاذ المقاوم للصدأ من سلسلة FT6 مع ضغط عمل يصل إلى 21.0 ميجا باسكال ودقة ترشيح عنصر معدني متكلس تبلغ 2.5 نانومتر. هيكل ملحوم بالكامل 316L مناسب للترشيح العميق للغاز فائق النقاء.', '<p>FT6 系列不锈钢滤芯气体过滤器采用烧结金属滤芯，过滤精度 2.5 纳米，为超高纯气体系统提供可靠的颗粒过滤。</p><p>工作压力最高 21.0MPa，316L 全焊接结构，电抛光（EP）可选，适用于半导体工艺气体过滤。</p>', '<p>The FT6 series stainless steel cartridge gas filters use sintered metal cartridges with a filtration accuracy of 2.5 nanometers, providing reliable particulate filtration for ultra-high purity gas systems.</p><p>Maximum working pressure 21.0MPa, 316L fully welded structure, electropolishing (EP) optional, suitable for semiconductor process gas filtration.</p>', '<p>FT6 シリーズ ステンレス鋼カートリッジ ガス フィルターは、濾過精度 2.5 nm の焼結金属カートリッジを備えており、超高純度ガス システムに信頼性の高い粒子濾過を提供します。</p><p>動作圧力最大 21.0MPa、316L 完全溶接構造、電気研磨 (EP) オプション、半導体プロセスガス濾過に適しています。</p>', '<p>FT6 시리즈 스테인레스 스틸 카트리지 가스 필터는 2.5nm의 여과 정확도를 갖춘 소결 금속 카트리지를 특징으로 하여 초고순도 가스 시스템에 대한 안정적인 입자 여과를 제공합니다.</p><p>작동압력 최대 21.0MPa, 316L 완전 용접 구조, 전기 연마(EP) 선택 사항, 반도체 공정 가스 여과에 적합</p>', '<p>Le filtre à gaz à élément en acier inoxydable de la série FT6 utilise un élément de filtre en métal fritté avec une précision de filtration de 2,5 nm, fournissant une filtration fiable des particules pour les systèmes de gaz ultra-haute pureté.</p><p>Pression de travail jusqu''à 21,0MPa, structure entièrement soudée de 316L, électropolissage (EP) en option, adapté à la filtration des gaz de procédé semi-conducteur.</p>', '<p>تتميز مرشحات الغاز المصنوعة من الفولاذ المقاوم للصدأ من سلسلة FT6 بعنصر معدني متكلس بدقة ترشيح تبلغ 2.5 نانومتر ، مما يوفر ترشيحًا موثوقًا للجسيمات لأنظمة الغاز فائقة النقاء.</p><p>يصل ضغط العمل إلى 21.0MPa ، هيكل ملحوم بالكامل 316L ، تلميع كهربائي (EP) اختياري ، مناسب لترشيح غاز عملية أشباه الموصلات.</p>', '["烧结金属滤芯 2.5nm", "工作压力 21.0MPa", "316L 全焊接结构", "EP 电抛光可选"]', '["Sintered metal filter element 2.5nm", "Working pressure 21.0MPa", "316L fully welded structure", "EP electropolishing optional"]', '["焼結金属フィルターエレメント 2.5nm", "作動圧力 21.0MPa", "316L 全溶接構造", "EP 電気研磨オプション"]', '["소결 금속 필터 요소 2.5nm", "작동 압력 21.0MPa", "316L 완전 용접 구조", "EP 전기 연마 옵션"]', '["Élément filtrant en métal fritté 2,5 nm", "Pression de travail 21,0MPa", "Structure entièrement soudée 316L", "EP électropolissage en option"]', '["عنصر مرشح معدني متكلس 2.5 نانومتر", "ضغط العمل 21.0 ميجا باسكال", "هيكل ملحوم بالكامل 316 لتر", "تلميع EP اختياري"]', NULL, NULL, NULL, false, '/uploads/oem/ft4-mr4.png', NULL, NULL, NULL, NULL, NULL, NULL, 1, NULL, NULL, NULL, NULL, NULL, NULL, '[{"name": "工作压力", "value": "MAX. 21.0MPa", "nameAr": "ضغط العمل", "nameEn": "working pressure", "nameFr": "Pression de travail", "nameJa": "仕事のストレス", "nameKo": "업무 스트레스", "valueAr": "ماكس. 21.0 ميجا باسكال", "valueEn": "MAX. 21.0MPa", "valueFr": "MAX. 21,0 MPa", "valueJa": "マックス21.0MPa", "valueKo": "최대. 21.0MPa"}, {"name": "过滤精度", "value": "2.5nm（烧结金属滤芯）", "nameAr": "دقة الترشيح", "nameEn": "filtration accuracy", "nameFr": "Précision de filtration", "nameJa": "ろ過精度", "nameKo": "필터링 정밀도", "valueAr": "2.5 نانومتر (عنصر مرشح معدني متكلس)", "valueEn": "2.5nm (sintered metal filter element)", "valueFr": "2,5 nm (élément filtrant en métal fritté)", "valueJa": "2.5nm（焼結金属フィルターエレメント）", "valueKo": "2.5nm (소결 금속 필터 요소)"}, {"name": "材料", "value": "316L 全焊接", "nameAr": "المواد", "nameEn": "Material", "nameFr": "Matériel", "nameJa": "素材", "nameKo": "재료", "valueAr": "316L ملحومة بالكامل", "valueEn": "316L fully welded", "valueFr": "316L entièrement soudé", "valueJa": "316L 全溶接", "valueKo": "316L 완전 용접"}, {"name": "表面处理", "value": "EP 电抛光可选", "nameAr": "المعالجة السطحية", "nameEn": "surface treatment", "nameFr": "Traitement de surface", "nameJa": "表面処理", "nameKo": "표면 처리", "valueAr": "EP تلميع كهربائي اختياري", "valueEn": "EP electropolishing optional", "valueFr": "EP électropolissage en option", "valueJa": "EPエレクトロポリッシュ オプション", "valueKo": "EP 전기 연마 옵션"}]', 39, 'published', '2026-09-08 18:51:45.311', '2026-09-08 18:51:45.311', '2026-09-08 18:51:45.311', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO public.products ("siteId", id, "tabId", "categoryId", slug, model, name, "nameEn", "nameJa", "nameKo", "nameFr", "nameAr", subtitle, "subtitleEn", "subtitleJa", "subtitleKo", "subtitleFr", "subtitleAr", summary, "summaryEn", "summaryJa", "summaryKo", "summaryFr", "summaryAr", description, "descriptionEn", "descriptionJa", "descriptionKo", "descriptionFr", "descriptionAr", features, "featuresEn", "featuresJa", "featuresKo", "featuresFr", "featuresAr", images, price, "priceTiers", "isParts", "coverImage", video, frames360, "manualUrl", "priceMin", "priceMax", "priceUnit", moq, "priceNote", "priceNoteEn", "priceNoteJa", "priceNoteKo", "priceNoteFr", "priceNoteAr", specs, "sortOrder", status, "publishedAt", "createdAt", "updatedAt", "seoTitle", "seoTitleJa", "seoTitleKo", "seoTitleFr", "seoTitleAr", "seoTitleEn", "seoDescription", "seoDescriptionJa", "seoDescriptionKo", "seoDescriptionFr", "seoDescriptionAr", "seoDescriptionEn", "seoKeywords", "seoKeywordsJa", "seoKeywordsKo", "seoKeywordsFr", "seoKeywordsAr", "seoKeywordsEn", "geoRegion", "geoCity") VALUES (NULL, 20, 38, 10, 'pre1-mr4', '316L-PRE1-MR4', '小流量减压阀', 'Low-Flow Pressure Reducer', '小流量減圧弁', '작은 유량 감압 밸브', 'Réducteur de pression à petit débit', 'صمام تخفيض ضغط التدفق الصغير', '入口 24.1MPa，CV 0.09/0.15', 'Inlet 24.1MPa, CV 0.09/0.15', '入口 24.1MPa、CV 0.09/0.15', '입구 24.1MPa, CV 0.09/0.15', 'Entrée 24,1MPa, CV 0,09/0,15', 'مدخل 24.1MPa ، CV 0.09 / 0.15', '小流量减压阀，入口压力最高 24.1MPa，适用于高纯气体精密减压。', 'Low-flow pressure reducer, max inlet 24.1MPa for precise UHP gas regulation.', '入口圧力最大24.1MPaの小流量減圧弁は、高純度ガスの精密減圧に適しています。', '최대 24.1MPa의 입구 압력을 갖춘 소유량 감압 밸브는 고순도 가스의 정밀 감압에 적합합니다.', 'Vanne réductrice de pression à petit débit, pression d''entrée jusqu''à 24,1 MPa, adaptée à la décompression de précision des gaz de haute pureté.', 'صمام تخفيض ضغط التدفق الصغير ، ضغط مدخل يصل إلى 24.1 ميجا باسكال ، مناسب لتخفيف الضغط الدقيق للغاز عالي النقاء.', '<p>PRE1 小流量减压阀提供稳定的输出压力控制，适用于半导体工艺气体柜。</p><p>316L 阀体，金属膜片密封，入口最高 24.1MPa。</p>', '<p>PRE1 low-flow reducer delivers stable outlet regulation for semiconductor gas cabinets.</p><p>316L body, metal diaphragm, max inlet 24.1MPa.</p>', '<p>PRE1 小流量減圧バルブは、半導体プロセスガスキャビネットに適した安定した出力圧力制御を提供します。</p><p>316L バルブボディ、金属ダイヤフラムシール、最大 24.1MPa の入口。</p>', '<p>PRE1 소유량 감압 밸브는 반도체 공정 가스 캐비닛에 적합한 안정적인 출력 압력 제어를 제공합니다.</p><p>316L 밸브 본체, 금속 다이어프램 밀봉, 입구 최대 24.1MPa.</p>', '<p>Le réducteur de pression à petit débit PRE1 offre un contrôle stable de la pression de sortie et convient aux armoires de gaz de processus à semi-conducteurs.</p><p>Corps de vanne 316L, étanchéité par diaphragme métallique, entrée jusqu''à 24,1 MPa.</p>', '<p>يوفر صمام تخفيض الضغط ذو التدفق الصغير PRE1 تحكمًا مستقرًا في ضغط الخرج ومناسبًا لخزائن غاز معالجة أشباه الموصلات.</p><p>جسم صمام 316L ، محكم الغلق بالحجاب الحاجز المعدني ، مدخل يصل إلى 24.1MPa.</p>', '["入口 24.1MPa", "金属膜片密封", "半导体气柜适用"]', '["24.1MPa inlet", "Metal diaphragm", "For gas cabinets"]', '["入口 24.1MPa", "メタルダイヤフラムシール", "半導体ガスキャビネット適用"]', '["입구 24.1MPa", "금속 다이어프램 밀봉", "반도체 가스 캐비닛 적용"]', '["Entrée 24,1 MPa", "Joint à diaphragme métallique", "Applicable aux armoires à gaz à semi-conducteurs"]', NULL, NULL, NULL, NULL, false, '/uploads/oem/pre1-mr4.jpg', NULL, NULL, NULL, NULL, NULL, NULL, 1, NULL, NULL, NULL, NULL, NULL, NULL, '[{"name": "入口压力", "value": "MAX. 24.1MPa", "nameAr": "ضغط المدخل", "nameEn": "Inlet", "nameFr": "Pression d''entrée", "nameJa": "入口圧力", "nameKo": "입구 압력", "valueAr": "MAX. 24.1MPa", "valueEn": "MAX. 24.1MPa", "valueFr": "MAX. 24.1MPa", "valueJa": "MAX. 24.1MPa", "valueKo": "MAX. 24.1MPa"}, {"name": "CV 值", "value": "0.09 / 0.15", "nameAr": "قيمة CV", "nameEn": "CV", "nameFr": "Valeur CV", "nameJa": "CV値", "nameKo": "CV 값", "valueAr": "0.09 / 0.15", "valueEn": "0.09 / 0.15", "valueFr": "0.09 / 0.15", "valueJa": "0.09 / 0.15", "valueKo": "0.09 / 0.15"}, {"name": "材质", "value": "316L", "nameAr": "المواد", "nameEn": "Material", "nameFr": "Matériel", "nameJa": "材質", "nameKo": "재료", "valueAr": "316L", "valueEn": "316L", "valueFr": "316L", "valueJa": "316L", "valueKo": "316L"}]', 20, 'published', NULL, '2026-09-07 10:59:24.528', '2026-09-07 11:54:25.726', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO public.products ("siteId", id, "tabId", "categoryId", slug, model, name, "nameEn", "nameJa", "nameKo", "nameFr", "nameAr", subtitle, "subtitleEn", "subtitleJa", "subtitleKo", "subtitleFr", "subtitleAr", summary, "summaryEn", "summaryJa", "summaryKo", "summaryFr", "summaryAr", description, "descriptionEn", "descriptionJa", "descriptionKo", "descriptionFr", "descriptionAr", features, "featuresEn", "featuresJa", "featuresKo", "featuresFr", "featuresAr", images, price, "priceTiers", "isParts", "coverImage", video, frames360, "manualUrl", "priceMin", "priceMax", "priceUnit", moq, "priceNote", "priceNoteEn", "priceNoteJa", "priceNoteKo", "priceNoteFr", "priceNoteAr", specs, "sortOrder", status, "publishedAt", "createdAt", "updatedAt", "seoTitle", "seoTitleJa", "seoTitleKo", "seoTitleFr", "seoTitleAr", "seoTitleEn", "seoDescription", "seoDescriptionJa", "seoDescriptionKo", "seoDescriptionFr", "seoDescriptionAr", "seoDescriptionEn", "seoKeywords", "seoKeywordsJa", "seoKeywordsKo", "seoKeywordsFr", "seoKeywordsAr", "seoKeywordsEn", "geoRegion", "geoCity") VALUES (NULL, 22, 39, 11, 'cv3-fmr4-hp', '316L-CV3-FMR4-HP', '全焊接单向阀', 'All-Welded Check Valve', '全溶接チェックバルブ', '완전 용접 체크 밸브', 'Vanne de réception entièrement soudée', 'صمام اتجاه ملحومة بالكامل', '20.7MPa，开启 <2psi，EP', '20.7MPa, crack <2psi, EP', '20.7MPa、オン <2psi、EP', '20.7MPa, ON <2psi, EP', '20,7 MPa, activé <2psi, EP', '20.7 ميجا باسكال ، قيد التشغيل <2psi ، EP', '全焊接结构单向阀，开启压力小于 2psi，EP 表面，适用于超高纯气体防倒流。', 'All-welded check valve, crack <2psi, EP finish for UHP gas backflow prevention.', '完全溶接構造のチェックバルブ、開圧 2psi 未満、EP 表面、超高純度ガスの逆流防止に適しています。', '완전 용접 구조 일방향 밸브, 개방 압력 2psi 미만, EP 표면, 초고순도 가스 역류 방지에 적합.', 'Vanne unidirectionnelle à structure entièrement soudée, pression d''ouverture inférieure à 2psi, surface EP, adaptée à l''anti-reflux de gaz ultra-haute pureté.', 'صمام اتجاه واحد ذو هيكل ملحوم بالكامل ، ضغط فتح أقل من 2 رطل لكل بوصة مربعة ، سطح EP ، مناسب لمنع التدفق العكسي للغاز فائق النقاء.', '<p>CV3 全焊接单向阀无弹性体密封，全焊接结构，适用于超高纯气体系统防止倒流。</p><p>开启压力小于 2psi，工作压力最大 20.7MPa，EP 表面处理，VCR 1/4" 连接。</p>', '<p>CV3 all-welded check valve, elastomer-free with welded body for UHP gas backflow prevention.</p><p>Crack <2psi, max 20.7MPa, EP finish, 1/4" VCR connection.</p>', '<p>CV3 完全溶接チェックバルブ エラストマーシールなし、完全溶接構造、逆流を防ぐ超高純度ガスシステムに適しています。</p><p>開圧 2psi 未満、動作圧力最大 20.7MPa、EP 仕上げ、VCR 1/4 インチ接続。</p>', '<p>CV3 완전 용접 일방향 밸브에는 엘라스토머 씰이 없으며 역류를 방지하기 위해 초고순도 가스 시스템에 적합한 완전 용접 구조입니다.</p><p>2psi 미만의 개방 압력, 최대 작동 압력 20.7MPa, EP 표면 처리, VCR 1/4" 연결.</p>', '<p>La vanne de réception entièrement soudée CV3 n''a pas d''étanchéité en élastomère et a une structure entièrement soudée, adaptée aux systèmes de gaz ultra-haute pureté pour empêcher le reflux.</p><p>Pression d''ouverture inférieure à 2 psi, pression de fonctionnement maximale de 20,7 MPa, finition EP, connexion VCR 1/4 ".</p>', '<p>لا يحتوي صمام الاتجاه الملحوم بالكامل CV3 على ختم مطاطي ، هيكل ملحوم بالكامل ، مناسب لأنظمة الغاز فائقة النقاء لمنع التدفق العكسي.</p><p>ضغط التشغيل أقل من 2 رطل لكل بوصة مربعة ، ضغط العمل 20.7 ميجا باسكال كحد أقصى ، معالجة سطح EP ، اتصال VCR 1/4 بوصة.</p>', '["全焊接无弹性体", "开启 <2psi", "20.7MPa / EP"]', '["All-welded, elastomer-free", "Crack <2psi", "20.7MPa / EP"]', '["全溶接無エラストマー", "オン <2psi", "20.7MPa / EP"]', '["완전 용접 비탄성체", "열기 <2psi", "20.7MPa / EP"]', '["Entièrement soudé sans élastomère", "Activation <2psi", "20,7 MPa/EP"]', NULL, NULL, NULL, NULL, false, '/uploads/oem/cv3-fmr4.jpg', NULL, NULL, NULL, NULL, NULL, NULL, 1, NULL, NULL, NULL, NULL, NULL, NULL, '[{"name": "工作压力", "value": "MAX. 20.7MPa", "nameAr": "ضغط التشغيل", "nameEn": "Pressure", "nameFr": "Pression de service", "nameJa": "動作圧力", "nameKo": "작동 압력", "valueAr": "MAX. 20.7MPa", "valueEn": "MAX. 20.7MPa", "valueFr": "MAX. 20.7MPa", "valueJa": "MAX. 20.7MPa", "valueKo": "MAX. 20.7MPa"}, {"name": "开启压力", "value": "< 2psi", "nameAr": "ضغط الفتح", "nameEn": "Crack", "nameFr": "Pression de craquage", "nameJa": "クラッキング圧力", "nameKo": "크래킹 압력", "valueAr": "< 2psi", "valueEn": "< 2psi", "valueFr": "< 2psi", "valueJa": "< 2psi", "valueKo": "< 2psi"}, {"name": "连接", "value": "1/4\" VCR 阴螺纹", "nameAr": "الاتصال", "nameEn": "Connection", "nameFr": "Connexion", "nameJa": "接続", "nameKo": "연결", "valueAr": "جهاز فيديو 1/4 بوصة خيط أنثى", "valueEn": "1/4\" VCR female thread", "valueFr": "Magnétoscope 1/4 \" filetage femelle", "valueJa": "1/4インチビデオカメラ雌ねじ", "valueKo": "1/4\" VCR 암컷 스레드"}, {"name": "表面", "value": "EP", "nameAr": "السطح", "nameEn": "Finish", "nameFr": "Surface", "nameJa": "表面", "nameKo": "표면", "valueAr": "EP", "valueEn": "EP", "valueFr": "EP", "valueJa": "EP", "valueKo": "EP"}]', 22, 'published', NULL, '2026-09-07 10:59:24.533', '2026-09-07 10:59:24.533', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO public.products ("siteId", id, "tabId", "categoryId", slug, model, name, "nameEn", "nameJa", "nameKo", "nameFr", "nameAr", subtitle, "subtitleEn", "subtitleJa", "subtitleKo", "subtitleFr", "subtitleAr", summary, "summaryEn", "summaryJa", "summaryKo", "summaryFr", "summaryAr", description, "descriptionEn", "descriptionJa", "descriptionKo", "descriptionFr", "descriptionAr", features, "featuresEn", "featuresJa", "featuresKo", "featuresFr", "featuresAr", images, price, "priceTiers", "isParts", "coverImage", video, frames360, "manualUrl", "priceMin", "priceMax", "priceUnit", moq, "priceNote", "priceNoteEn", "priceNoteJa", "priceNoteKo", "priceNoteFr", "priceNoteAr", specs, "sortOrder", status, "publishedAt", "createdAt", "updatedAt", "seoTitle", "seoTitleJa", "seoTitleKo", "seoTitleFr", "seoTitleAr", "seoTitleEn", "seoDescription", "seoDescriptionJa", "seoDescriptionKo", "seoDescriptionFr", "seoDescriptionAr", "seoDescriptionEn", "seoKeywords", "seoKeywordsJa", "seoKeywordsKo", "seoKeywordsFr", "seoKeywordsAr", "seoKeywordsEn", "geoRegion", "geoCity") VALUES (NULL, 23, 39, 11, 'bsm-mr4', '316L-BSM-MR4', '波纹管计量阀', 'Bellows Metering Valve', 'ベローズ計量弁', '벨로우 계량 밸브', 'Soufflet doseur', 'صمام قياس منفاخ', '4.8MPa，CV 0.19（计量）', '4.8MPa, CV 0.19 (metering)', '4.8MPa、CV0.19（計量）', '4.8MPa, 이력서 0.19(측정)', '4,8 MPa, CV 0,19 (mesure)', '4.8 ميجا باسكال ، السيرة الذاتية 0.19 (قياس)', '波纹管计量阀，精确流量调节，适用于分析仪器与高纯气体微调。', 'Bellows metering valve for precise flow adjustment in analyzers and UHP gas.', 'ベローズ計量弁、正確な流量調整、分析機器と高純度ガスの微調整に適しています。', '벨로우 계량 밸브, 정확한 유량 조절, 분석 기기 및 고순도 가스 미세 조정에 적합합니다.', 'Soufflet de dosage, réglage précis du débit, adapté aux instruments analytiques et au réglage fin des gaz de haute pureté.', 'صمام قياس منفاخ ، تعديل التدفق الدقيق ، مناسب للأدوات التحليلية والضبط الدقيق للغاز عالي النقاء.', '<p>BSM 波纹管计量阀提供精细流量控制，波纹管密封无泄漏，适用于气体分析仪器与取样系统。</p><p>工作压力最大 4.8MPa，计量型 CV 0.19 / 调节型 CV 0.3。</p>', '<p>BSM bellows metering valve for fine flow control, bellows seal leak-free for analyzers and sampling.</p><p>Max 4.8MPa, metering CV 0.19 / regulating CV 0.3.</p>', '<p>BSM ベローズ計量バルブは、ガス分析機器やサンプリング システムに適した、細かい流量制御と漏れのないベローズ シールを提供します。</p><p>作動圧力は最大4.8MPa、計量型CV 0.19 / 調整型CV 0.3。</p>', '<p>BSM 벨로우 계량 밸브는 가스 분석 장비 및 샘플링 시스템에 적합한 정밀한 유량 제어 및 벨로우 밀봉 누출 방지를 제공합니다.</p><p>작동압력 최대 4.8MPa, 계량형 CV 0.19 / 조절형 CV 0.3.</p>', '<p>La vanne de dosage à soufflet BSM fournit un contrôle de débit précis et l''étanchéité du soufflet est sans fuite. Elle convient aux instruments d''analyse de gaz et aux systèmes d''échantillonnage.</p><p>La pression de travail maximale est de 4,8 MPa, le type doseur CV 0,19/le type réglable CV 0,3.</p>', '<p>يوفر صمام قياس المنفاخ BSM تحكمًا دقيقًا في التدفق ، وختم المنفاخ خالٍ من التسرب ، وهو مناسب لأدوات تحليل الغاز وأنظمة أخذ العينات.</p><p>الحد الأقصى لضغط العمل هو 4.8 ميجا باسكال ، نوع القياس CV 0.19 / نوع التعديل CV 0.3.</p>', '["波纹管密封无泄漏", "精细流量调节", "4.8MPa"]', '["Bellows seal leak-free", "Fine metering", "4.8MPa"]', '["ベローズシールの漏れなし", "微細流量調整", "4.8MPa"]', '["벨로우 밀봉 누출 없음", "미세 유량 조절", "4.8MPa"]', '["Joint de soufflet sans fuite", "Régulation fine du débit", "4,8 MPa"]', NULL, NULL, NULL, NULL, false, '/uploads/oem/bsm-mr4.jpg', NULL, NULL, NULL, NULL, NULL, NULL, 1, NULL, NULL, NULL, NULL, NULL, NULL, '[{"name": "工作压力", "value": "MAX. 4.8MPa", "nameAr": "ضغط التشغيل", "nameEn": "Pressure", "nameFr": "Pression de service", "nameJa": "動作圧力", "nameKo": "작동 압력", "valueAr": "MAX. 4.8MPa", "valueEn": "MAX. 4.8MPa", "valueFr": "MAX. 4.8MPa", "valueJa": "MAX. 4.8MPa", "valueKo": "MAX. 4.8MPa"}, {"name": "CV 值", "value": "0.19（计量）/ 0.3（调节）", "nameAr": "قيمة CV", "nameEn": "CV", "nameFr": "Valeur CV", "nameJa": "CV値", "nameKo": "CV 값", "valueAr": "0.19 (قياس) / 0.3 (تعديل)", "valueEn": "0.19 (metered) / 0.3 (adjusted)", "valueFr": "0,19 (mesure) /0,3 (réglage)", "valueJa": "0.19（計量）/0.3（調整）", "valueKo": "0.19(측정) / 0.3(조정)"}, {"name": "材质", "value": "316L", "nameAr": "المواد", "nameEn": "Material", "nameFr": "Matériel", "nameJa": "材質", "nameKo": "재료", "valueAr": "316L", "valueEn": "316L", "valueFr": "316L", "valueJa": "316L", "valueKo": "316L"}]', 23, 'published', NULL, '2026-09-07 10:59:24.535', '2026-09-07 11:54:25.731', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO public.products ("siteId", id, "tabId", "categoryId", slug, model, name, "nameEn", "nameJa", "nameKo", "nameFr", "nameAr", subtitle, "subtitleEn", "subtitleJa", "subtitleKo", "subtitleFr", "subtitleAr", summary, "summaryEn", "summaryJa", "summaryKo", "summaryFr", "summaryAr", description, "descriptionEn", "descriptionJa", "descriptionKo", "descriptionFr", "descriptionAr", features, "featuresEn", "featuresJa", "featuresKo", "featuresFr", "featuresAr", images, price, "priceTiers", "isParts", "coverImage", video, frames360, "manualUrl", "priceMin", "priceMax", "priceUnit", moq, "priceNote", "priceNoteEn", "priceNoteJa", "priceNoteKo", "priceNoteFr", "priceNoteAr", specs, "sortOrder", status, "publishedAt", "createdAt", "updatedAt", "seoTitle", "seoTitleJa", "seoTitleKo", "seoTitleFr", "seoTitleAr", "seoTitleEn", "seoDescription", "seoDescriptionJa", "seoDescriptionKo", "seoDescriptionFr", "seoDescriptionAr", "seoDescriptionEn", "seoKeywords", "seoKeywordsJa", "seoKeywordsKo", "seoKeywordsFr", "seoKeywordsAr", "seoKeywordsEn", "geoRegion", "geoCity") VALUES (NULL, 13, 35, 7, 'vcr-gg-gasket', '316L-GG-MR4', 'VCR 金属垫片', 'VCR Metal Gasket', 'VCRメタルスペーサー', 'VCR 금속 개스킷', 'Joint métallique VCR', 'حشية معدنية لجهاز VCR', '1/4" VCR 密封垫片，金属密封', '1/4" VCR sealing gasket, metal seal', '1/4 インチ VCR ガスケット、金属シール', '1/4" VCR 개스킷, 금속 씰', 'Joint d''étanchéité VCR 1/4 ", joint métallique', 'حشية VCR مقاس 1/4 بوصة ، ختم معدني', 'VCR 金属面密封垫片，316L 材质，用于 VCR 接头连接密封。', 'VCR metal face seal gasket, 316L, for VCR fitting connections.', 'VCR 金属フェース シール ガスケット、316L 素材、VCR ジョイント接続シール用。', 'VCR 조인트 연결 씰을 위한 316L 소재의 VCR 금속 페이스 씰 개스킷.', 'Joint d''étanchéité de surface métallique pour magnétoscope, matériau 316L, utilisé pour l''étanchéité de connexion du connecteur magnétoscope.', 'حشية ختم الوجه المعدني لجهاز VCR ، مادة 316L ، لختم توصيل وصلة جهاز VCR.', '<p>VCR 垫片用于两个 VCR 连接面之间，形成金属对金属密封，可重复使用。</p><p>适配 1/4" VCR 接头，高纯工艺推荐。</p>', '<p>VCR gasket sits between VCR faces creating metal-to-metal seal, reusable.</p><p>For 1/4" VCR fittings, recommended for high-purity processes.</p>', '<p>VCR ガスケットは 2 つの VCR 接続面の間に使用され、再利用可能な金属対金属シールを形成します。</p><p>1/4 インチ VCR コネクタに適合し、高純度プロセスが推奨されます。</p>', '<p>VCR 개스킷은 두 개의 VCR 연결 면 사이에 사용되어 재사용 가능한 금속 대 금속 씰을 형성합니다.</p><p>1/4" VCR 커넥터에 적합하며 고순도 공정을 권장합니다.</p>', '<p>Le joint VCR est utilisé entre deux surfaces de connexion VCR pour former un joint métal-à-métal qui peut être réutilisé.</p><p>Adapté au connecteur magnétoscope 1/4 ", recommandé pour un processus de haute pureté.</p>', '<p>يتم استخدام حشية VCR بين وجهي توصيل VCR لتشكيل ختم معدني إلى معدني قابل لإعادة الاستخدام.</p><p>يتكيف مع موصل VCR مقاس 1/4 بوصة ، ويوصى بالعملية عالية النقاء.</p>', '["金属对金属密封", "可重复使用", "316L 材质"]', '["Metal-to-metal seal", "Reusable", "316L material"]', '["金属から金属へのシール", "再利用可能", "316L 材質"]', '["금속 대 금속 씰", "재사용 가능", "316L 재질"]', '["Etanchéité métal à métal", "réutilisable", "Matériau 316L"]', NULL, NULL, NULL, NULL, false, '/uploads/oem/GG_1.jpg', NULL, NULL, NULL, NULL, NULL, NULL, 1, NULL, NULL, NULL, NULL, NULL, NULL, '[{"name": "口径", "value": "1/4\"", "nameAr": "عيار", "nameEn": "Size", "nameFr": "Calibre", "nameJa": "口径", "nameKo": "구경", "valueAr": "1/4\"", "valueEn": "1/4\"", "valueFr": "1/4\"", "valueJa": "1/4\"", "valueKo": "1/4\""}, {"name": "材质", "value": "316L", "nameAr": "المواد", "nameEn": "Material", "nameFr": "Matériel", "nameJa": "材質", "nameKo": "재료", "valueAr": "316L", "valueEn": "316L", "valueFr": "316L", "valueJa": "316L", "valueKo": "316L"}]', 13, 'published', NULL, '2026-09-07 10:59:24.509', '2026-09-07 10:59:24.509', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO public.products ("siteId", id, "tabId", "categoryId", slug, model, name, "nameEn", "nameJa", "nameKo", "nameFr", "nameAr", subtitle, "subtitleEn", "subtitleJa", "subtitleKo", "subtitleFr", "subtitleAr", summary, "summaryEn", "summaryJa", "summaryKo", "summaryFr", "summaryAr", description, "descriptionEn", "descriptionJa", "descriptionKo", "descriptionFr", "descriptionAr", features, "featuresEn", "featuresJa", "featuresKo", "featuresFr", "featuresAr", images, price, "priceTiers", "isParts", "coverImage", video, frames360, "manualUrl", "priceMin", "priceMax", "priceUnit", moq, "priceNote", "priceNoteEn", "priceNoteJa", "priceNoteKo", "priceNoteFr", "priceNoteAr", specs, "sortOrder", status, "publishedAt", "createdAt", "updatedAt", "seoTitle", "seoTitleJa", "seoTitleKo", "seoTitleFr", "seoTitleAr", "seoTitleEn", "seoDescription", "seoDescriptionJa", "seoDescriptionKo", "seoDescriptionFr", "seoDescriptionAr", "seoDescriptionEn", "seoKeywords", "seoKeywordsJa", "seoKeywordsKo", "seoKeywordsFr", "seoKeywordsAr", "seoKeywordsEn", "geoRegion", "geoCity") VALUES (NULL, 14, 36, 8, 'weld-elbow-ie-tb4', '316L-IE-TB4', '微焊接弯头', 'Micro Weld Elbow', 'マイクロ溶接エルボ', '마이크로 용접 엘보', 'Coudes micro-soudés', 'كوع ملحومة دقيقة', '1/4" 对焊弯头，90°', '1/4" butt weld elbow, 90°', '1/4 インチ突合せ溶接エルボ、90°', '1/4" 버트 용접 엘보, 90°', 'Coudé de soudage à butte 1/4 ", 90°', 'كوع لحام بعقب 1/4 بوصة ، 90 درجة', '316L 微焊接弯头，两端 1/4" 对焊口，适用于高纯管路紧凑转弯。', '316L micro weld elbow, 1/4" weld ends for compact UHP turns.', '316L マイクロ溶接エルボ、両端に 1/4 インチのバットジョイントが付いており、高純度ラインのコンパクトなターンに適しています。', '양쪽 끝에 1/4" 버트 용접 조인트가 있는 316L 마이크로 용접된 엘보우는 고순도 라인의 컴팩트한 회전에 적합합니다.', 'Coude micro-soudé 316L, soudure à butte de 1/4 "aux deux extrémités, adapté aux virages compacts de tuyauteries de haute pureté.', 'كوع ملحوم دقيقًا 316L مع وصلات لحام بعقب مقاس 1/4 بوصة على كلا الطرفين للمنعطفات المدمجة في الأنابيب عالية النقاء.', '<p>微焊接弯头 I 系列采用 316L 材质，小尺寸设计，焊接后内壁光滑无死角。</p><p>适配 1/4" EP 管，用于半导体工艺气体管路。</p>', '<p>Micro weld elbow I series in 316L, compact size, smooth bore after welding.</p><p>For 1/4" EP tubing in semiconductor process lines.</p>', '<p>マイクロ溶接エルボIシリーズは316L素材を使用し、小型設計で、溶接後の内壁は滑らかで死角がありません。</p><p>半導体プロセスガスライン用の 1/4 インチ EP チューブに適合。</p>', '<p>마이크로 용접 엘보우 I 시리즈는 316L 소재로 제작되었으며 작은 크기로 설계되었으며 용접 후 사각지대 없이 매끄러운 내벽을 제공합니다.</p><p>반도체 공정 가스 라인용 1/4" EP 튜브에 적합합니다.</p>', '<p>Le coude de micro-soudage série I est fabriqué en matériau 316L et a une conception de petite taille. Après le soudage, la paroi intérieure est lisse et sans angles morts.</p><p>Adapté à des tubes EP de 1/4 "pour les conduites de gaz de processus semi-conducteurs.</p>', '<p>سلسلة الكوع الملحومة الدقيقة I مصنوعة من مادة 316L ، وهي مصممة بحجم صغير ، والجدار الداخلي أملس بدون زوايا ميتة بعد اللحام.</p><p>تناسب أنابيب EP مقاس 1/4 بوصة لخطوط غاز عملية أشباه الموصلات.</p>', '["316L 材质", "内壁光滑无死角", "1/4\" 对焊"]', '["316L", "Smooth bore", "1/4\" weld"]', '["316L 材質", "内壁が滑らかで死角なし", "1/4\" 突合せ溶接"]', '["316L 재질", "사각지대 없이 매끄러운 내벽", "1/4\" 버트용접"]', '["Matériau 316L", "La paroi intérieure est lisse et sans angles morts", "Soudage à butte 1/4 \""]', NULL, NULL, NULL, NULL, false, '/uploads/oem/IE-TB8.jpg', NULL, NULL, NULL, NULL, NULL, NULL, 1, NULL, NULL, NULL, NULL, NULL, NULL, '[{"name": "口径", "value": "1/4\"", "nameAr": "عيار", "nameEn": "Size", "nameFr": "Calibre", "nameJa": "口径", "nameKo": "구경", "valueAr": "1/4\"", "valueEn": "1/4\"", "valueFr": "1/4\"", "valueJa": "1/4\"", "valueKo": "1/4\""}, {"name": "角度", "value": "90°", "nameAr": "زاوية", "nameEn": "Angle", "nameFr": "Angle", "nameJa": "アングル", "nameKo": "각도", "valueAr": "90°", "valueEn": "90°", "valueFr": "90°", "valueJa": "90°", "valueKo": "90°"}, {"name": "材质", "value": "316L", "nameAr": "المواد", "nameEn": "Material", "nameFr": "Matériel", "nameJa": "材質", "nameKo": "재료", "valueAr": "316L", "valueEn": "316L", "valueFr": "316L", "valueJa": "316L", "valueKo": "316L"}]', 14, 'published', NULL, '2026-09-07 10:59:24.512', '2026-09-07 10:59:24.512', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO public.products ("siteId", id, "tabId", "categoryId", slug, model, name, "nameEn", "nameJa", "nameKo", "nameFr", "nameAr", subtitle, "subtitleEn", "subtitleJa", "subtitleKo", "subtitleFr", "subtitleAr", summary, "summaryEn", "summaryJa", "summaryKo", "summaryFr", "summaryAr", description, "descriptionEn", "descriptionJa", "descriptionKo", "descriptionFr", "descriptionAr", features, "featuresEn", "featuresJa", "featuresKo", "featuresFr", "featuresAr", images, price, "priceTiers", "isParts", "coverImage", video, frames360, "manualUrl", "priceMin", "priceMax", "priceUnit", moq, "priceNote", "priceNoteEn", "priceNoteJa", "priceNoteKo", "priceNoteFr", "priceNoteAr", specs, "sortOrder", status, "publishedAt", "createdAt", "updatedAt", "seoTitle", "seoTitleJa", "seoTitleKo", "seoTitleFr", "seoTitleAr", "seoTitleEn", "seoDescription", "seoDescriptionJa", "seoDescriptionKo", "seoDescriptionFr", "seoDescriptionAr", "seoDescriptionEn", "seoKeywords", "seoKeywordsJa", "seoKeywordsKo", "seoKeywordsFr", "seoKeywordsAr", "seoKeywordsEn", "geoRegion", "geoCity") VALUES (NULL, 15, 36, 8, 'weld-tee-it-tb4', '316L-IT-TB4', '微焊接三通', 'Micro Weld Tee', 'マイクロ溶接ティー', '마이크로 용접 티', 'Tee micro-soudé', 'تي لحام دقيقة', '1/4" 对焊三通', '1/4" butt weld tee', '1/4" 突合せ溶接ティー', '1/4" 버트 용접 티', 'Tee de soudage à butte 1/4 "', '1/4 بوصة لحام بعقب تي', '316L 微焊接三通，三端 1/4" 对焊口，均布分流设计。', '316L micro weld tee with three 1/4" weld ends.', '316L マイクロ溶接ティー、3 端 1/4 インチ突合せジョイント、均一に分散されたシャント設計。', '316L 마이크로 용접 티, 3단 1/4" 버트 용접 조인트, 균일하게 분포된 분류 디자인.', 'Tee de micro-soudage 316L, joints de soudage à butte de 1/4 "à trois extrémités, conception de dérivation uniforme.', 'تي شيرت ملحومة دقيقة 316L ، وصلة لحام بعقب 1/4 بوصة في ثلاثة أطراف ، تصميم تحويل موزع بشكل موحد.', '<p>微焊接三通用于管路三分支，316L 材质，焊接后内壁光滑，适配超高纯系统。</p>', '<p>Micro weld tee for three-way branch, 316L, smooth bore after welding for UHP systems.</p>', '<p>マイクロ溶接ティーはパイプラインの3分岐に使用され、316L素材で作られており、溶接後の内壁は滑らかで、超高純度システムに適合しています。</p>', '<p>마이크로 용접 티는 파이프라인의 3가지 분기에 사용되며 316L 재질로 용접 후 내벽이 매끄럽고 초고순도 시스템에 적합합니다.</p>', '<p>Le tee micro-soudé est utilisé pour les trois branches du pipeline. Il est fabriqué en matériau 316L. La paroi intérieure est lisse après le soudage et convient aux systèmes de pureté ultra haute.</p>', '<p>يستخدم القميص الملحوم دقيقًا في ثلاثة فروع من خطوط الأنابيب ، وهو مصنوع من مادة 316L ، والجدار الداخلي ناعم بعد اللحام ، وهو مناسب لأنظمة فائقة النقاء.</p>', '["三端 1/4\" 对焊", "均布分流", "316L 材质"]', '["Three 1/4\" weld ends", "Balanced flow", "316L"]', '["3 端 1/4\" 突合せ溶接", "均等分布分流", "316L 材質"]', '["3단 1/4\" 버트용접", "균일하게 분포 분류", "316L 재질"]', '["Soudage à butte à trois extrémités 1/4 \"", "dérivation uniforme", "Matériau 316L"]', NULL, NULL, NULL, NULL, false, '/uploads/oem/IT-TB8-TB8-TB4_1.png', NULL, NULL, NULL, NULL, NULL, NULL, 1, NULL, NULL, NULL, NULL, NULL, NULL, '[{"name": "口径", "value": "1/4\"", "nameAr": "عيار", "nameEn": "Size", "nameFr": "Calibre", "nameJa": "口径", "nameKo": "구경", "valueAr": "1/4\"", "valueEn": "1/4\"", "valueFr": "1/4\"", "valueJa": "1/4\"", "valueKo": "1/4\""}, {"name": "类型", "value": "等径三通", "nameAr": "أنواع", "nameEn": "Type", "nameFr": "Type", "nameJa": "タイプ", "nameKo": "유형", "valueAr": "تي قطر متساوي", "valueEn": "equal diameter tee", "valueFr": "T à diamètre égal", "valueJa": "等径ティー", "valueKo": "등경 티"}, {"name": "材质", "value": "316L", "nameAr": "المواد", "nameEn": "Material", "nameFr": "Matériel", "nameJa": "材質", "nameKo": "재료", "valueAr": "316L", "valueEn": "316L", "valueFr": "316L", "valueJa": "316L", "valueKo": "316L"}]', 15, 'published', NULL, '2026-09-07 10:59:24.514', '2026-09-07 10:59:24.514', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO public.products ("siteId", id, "tabId", "categoryId", slug, model, name, "nameEn", "nameJa", "nameKo", "nameFr", "nameAr", subtitle, "subtitleEn", "subtitleJa", "subtitleKo", "subtitleFr", "subtitleAr", summary, "summaryEn", "summaryJa", "summaryKo", "summaryFr", "summaryAr", description, "descriptionEn", "descriptionJa", "descriptionKo", "descriptionFr", "descriptionAr", features, "featuresEn", "featuresJa", "featuresKo", "featuresFr", "featuresAr", images, price, "priceTiers", "isParts", "coverImage", video, frames360, "manualUrl", "priceMin", "priceMax", "priceUnit", moq, "priceNote", "priceNoteEn", "priceNoteJa", "priceNoteKo", "priceNoteFr", "priceNoteAr", specs, "sortOrder", status, "publishedAt", "createdAt", "updatedAt", "seoTitle", "seoTitleJa", "seoTitleKo", "seoTitleFr", "seoTitleAr", "seoTitleEn", "seoDescription", "seoDescriptionJa", "seoDescriptionKo", "seoDescriptionFr", "seoDescriptionAr", "seoDescriptionEn", "seoKeywords", "seoKeywordsJa", "seoKeywordsKo", "seoKeywordsFr", "seoKeywordsAr", "seoKeywordsEn", "geoRegion", "geoCity") VALUES (NULL, 16, 36, 8, 'weld-cross-ic-tb4', '316L-IC-TB4', '微焊接四通', 'Micro Weld Cross', 'マイクロ溶接四通', '마이크로 용접 4방향', 'Micro-soudage de quatre voies', 'رباعي الاتجاه الملحومة الصغيرة', '1/4" 对焊四通', '1/4" butt weld cross', '1/4インチ突合せ溶接四方向', '1/4" 버트 용접 4방향', 'Quadruple soudé sur butte 1/4 "', '1/4 بوصة لحام بعقب رباعي الاتجاه', '316L 微焊接四通，四端 1/4" 对焊口，多路分配应用。', '316L micro weld cross, four 1/4" weld ends.', '316L マイクロ溶接 4 ウェイ、4 端 1/4 インチ バット ジョイント、マルチディストリビューション アプリケーション。', '316L 마이크로 용접 4방향, 4단 1/4" 버트 조인트, 다중 분배 애플리케이션.', 'Quad micro-soudé 316L, joints de soudage à quatre extrémités de 1/4 ", applications de distribution multicanaux.', '316L رباعي الاتجاه ملحومة دقيقة ، وصلة بعقب أربعة أطراف 1/4 بوصة ، تطبيق التوزيع متعدد الاتجاهات.', '<p>微焊接四通用于多点分配管路，316L 材质，内壁光滑无死角，适配高纯气体分配系统。</p>', '<p>Micro weld cross for multi-point distribution, 316L, smooth bore for UHP gas distribution.</p>', '<p>マイクロ溶接四方は多点分配パイプラインに使用され、316L材料、内壁は滑らかで死角がなく、高純度ガス分配システムに適合している。</p>', '<p>마이크로 용접 4통은 다점 분배 파이프라인, 316L 재질, 매끄러운 내벽 사각지대 없이 고순도 가스 분배 시스템에 적합합니다.</p>', '<p>Les quatre voies micro-soudées sont utilisées dans les pipelines de distribution multipoints. Il est fabriqué en matériau 316L. La paroi intérieure est lisse et sans angles morts. Il convient aux systèmes de distribution de gaz de haute pureté.</p>', '<p>يتم استخدام الأنابيب الرباعية الملحومة دقيقًا في خطوط أنابيب التوزيع متعددة النقاط ، وهي مصنوعة من مادة 316L ، والجدار الداخلي أملس بدون زوايا ميتة ، وهي مناسبة لأنظمة توزيع الغاز</p>', '["四端 1/4\" 对焊", "多点分配", "316L 材质"]', '["Four weld ends", "Multi-point distribution", "316L"]', '["4 端 1/4 インチ突合せ溶接", "マルチポイント割り当て", "316L 素材"]', '["4단 1/4\" 버트용접", "멀티포인트 분배", "316L 재질"]', '["Soudage à butte à quatre extrémités 1/4 \"", "Distribution multipoint", "Matériau 316L"]', NULL, NULL, NULL, NULL, false, '/uploads/oem/IT-TB8-TB8-TB4_1.png', NULL, NULL, NULL, NULL, NULL, NULL, 1, NULL, NULL, NULL, NULL, NULL, NULL, '[{"name": "口径", "value": "1/4\"", "nameAr": "عيار", "nameEn": "Size", "nameFr": "Calibre", "nameJa": "口径", "nameKo": "구경", "valueAr": "1/4\"", "valueEn": "1/4\"", "valueFr": "1/4\"", "valueJa": "1/4\"", "valueKo": "1/4\""}, {"name": "材质", "value": "316L", "nameAr": "المواد", "nameEn": "Material", "nameFr": "Matériel", "nameJa": "材質", "nameKo": "재료", "valueAr": "316L", "valueEn": "316L", "valueFr": "316L", "valueJa": "316L", "valueKo": "316L"}]', 16, 'published', NULL, '2026-09-07 10:59:24.518', '2026-09-07 10:59:24.518', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO public.products ("siteId", id, "tabId", "categoryId", slug, model, name, "nameEn", "nameJa", "nameKo", "nameFr", "nameAr", subtitle, "subtitleEn", "subtitleJa", "subtitleKo", "subtitleFr", "subtitleAr", summary, "summaryEn", "summaryJa", "summaryKo", "summaryFr", "summaryAr", description, "descriptionEn", "descriptionJa", "descriptionKo", "descriptionFr", "descriptionAr", features, "featuresEn", "featuresJa", "featuresKo", "featuresFr", "featuresAr", images, price, "priceTiers", "isParts", "coverImage", video, frames360, "manualUrl", "priceMin", "priceMax", "priceUnit", moq, "priceNote", "priceNoteEn", "priceNoteJa", "priceNoteKo", "priceNoteFr", "priceNoteAr", specs, "sortOrder", status, "publishedAt", "createdAt", "updatedAt", "seoTitle", "seoTitleJa", "seoTitleKo", "seoTitleFr", "seoTitleAr", "seoTitleEn", "seoDescription", "seoDescriptionJa", "seoDescriptionKo", "seoDescriptionFr", "seoDescriptionAr", "seoDescriptionEn", "seoKeywords", "seoKeywordsJa", "seoKeywordsKo", "seoKeywordsFr", "seoKeywordsAr", "seoKeywordsEn", "geoRegion", "geoCity") VALUES (NULL, 17, 37, 9, 'dv12a-fmr4-hp', '316L-DV12A-FMR4-HP', '手动低压隔膜阀', 'Manual Low-Pressure Diaphragm Valve', '手動低圧ダイヤフラムバルブ', '수동 저압 다이어프램 밸브', 'Vanne à membrane basse pression manuelle', 'صمام الحجاب الحاجز اليدوي منخفض الضغط', '250psi，-23℃~66℃，VCR 阴螺纹', '250psi, -23~66°C, VCR female', '250psi、-23℃~66℃、VCR メスネジ', '250psi, -23℃~66℃, VCR 암 스레드', '250psi, -23℃ ~66℃, filetage femelle VCR', '250 رطل لكل بوصة مربعة ، -23 درجة مئوية ~ 66 درجة مئوية ، خيط أنثى VCR', '手动隔膜阀，工作压力 250psi，VCR 阴螺纹连接，适用于高纯气体开关控制。', 'Manual diaphragm valve, 250psi, VCR female connection for UHP gas on/off control.', '手動ダイヤフラムバルブ、動作圧力 250psi、VCR メスねじ接続、高純度ガススイッチ制御に適しています。', '수동 다이어프램 밸브, 작동 압력 250psi, 고순도 가스 스위치 제어를 위한 VCR 암 나사 연결.', 'Vanne à membrane manuelle, pression de fonctionnement 250psi, connexion filetée femelle VCR, adaptée au contrôle de commutation de gaz de haute pureté.', 'صمام الحجاب الحاجز اليدوي ، ضغط التشغيل 250 رطل لكل بوصة مربعة ، وصلة ملولبة أنثوية لجهاز VCR للتحكم في مفتاح الغاز عالي النقاء.', '<p>DV12A 手动隔膜阀采用 316L 阀体与聚酰亚胺/PTFE 隔膜，无死角结构，适用于超高纯工艺气体。</p><p>工作压力最大 250psi（1.72MPa），温度 -23℃～66℃，VCR 1/4" 阴螺纹连接。</p>', '<p>DV12A manual diaphragm valve with 316L body and PI/PTFE diaphragm, dead-space-free for UHP process gas.</p><p>Max 250psi (1.72MPa), -23~66°C, 1/4" VCR female connection.</p>', '<p>DV12A 手動ダイヤフラム バルブは、316L バルブ本体とポリイミド/PTFE ダイヤフラムを採用しており、デッドコーナーのない構造で、超高純度プロセスガスに適しています。</p><p>動作圧力最大 250psi (1.72MPa)、温度 -23℃~66℃、VCR 1/4 インチ雌ネジ接続。</p>', '<p>DV12A 수동 다이어프램 밸브는 316L 밸브 본체와 폴리이미드/PTFE 다이어프램을 갖추고 있으며 초고순도 공정 가스에 적합한 사각지대 구조가 없습니다.</p><p>작동 압력 최대 250psi (1.72MPa), 온도 -23℃~66℃, VCR 1/4" 암나사 연결.</p>', '<p>La vanne à membrane manuelle DV12A adopte un corps de vanne 316L et un diaphragme en polyimide/PTFE, sans structure d''angle mort, adaptée aux gaz de processus ultra-haute pureté.</p><p>Pression de travail maximale 250 psi (1,72 MPa), température-23 ℃ ~66 ℃, connexion filetée femelle VCR 1/4 ".</p>', '<p>يتميز صمام الحجاب الحاجز اليدوي DV12A بجسم صمام سعة 316L وحجاب حاجز من البوليميد/PTFE ، ولا يوجد هيكل زاوية ميتة ، وهو مناسب لغازات المعالجة فائقة النقاء.</p><p>الحد الأقصى لضغط العمل هو 250 رطل لكل بوصة مربعة (1.72 ميجا باسكال)، درجة الحرارة -23 درجة مئوية ~ 66 درجة مئوية ، وصلة خيط أنثى VCR 1/4 بوصة.</p>', '["无死角隔膜密封", "250psi 工作压力", "VCR 1/4\" 连接"]', '["Dead-space-free diaphragm seal", "250psi working pressure", "1/4\" VCR connection"]', '["デッドコーナーなしダイヤフラムシール", "250psi 作動圧力", "VCR 1/4\" 接続"]', '["사각지대 없는 다이어프램 씰", "250psi 작동 압력", "VCR 1/4\" 연결"]', '["Joint de diaphragme sans angle mort", "Pression de fonctionnement de 250psi", "magnétoscope Connexion 1/4 \""]', NULL, NULL, NULL, NULL, false, '/uploads/oem/dv12a-mr4.jpg', NULL, NULL, NULL, NULL, NULL, NULL, 1, NULL, NULL, NULL, NULL, NULL, NULL, '[{"name": "工作压力", "value": "MAX. 250psi (1.72MPa)", "nameAr": "ضغط التشغيل", "nameEn": "Pressure", "nameFr": "Pression de service", "nameJa": "動作圧力", "nameKo": "작동 압력", "valueAr": "MAX. 250psi (1.72MPa)", "valueEn": "MAX. 250psi (1.72MPa)", "valueFr": "MAX. 250psi (1.72MPa)", "valueJa": "MAX. 250psi (1.72MPa)", "valueKo": "MAX. 250psi (1.72MPa)"}, {"name": "温度", "value": "-23℃ ~ 66℃", "nameAr": "درجة الحرارة", "nameEn": "Temperature", "nameFr": "Température", "nameJa": "温度", "nameKo": "온도", "valueAr": "-23℃ ~ 66℃", "valueEn": "-23℃ ~ 66℃", "valueFr": "-23℃ ~ 66℃", "valueJa": "-23℃ ~ 66℃", "valueKo": "-23℃ ~ 66℃"}, {"name": "连接", "value": "1/4\" VCR 阴螺纹", "nameAr": "الاتصال", "nameEn": "Connection", "nameFr": "Connexion", "nameJa": "接続", "nameKo": "연결", "valueAr": "جهاز فيديو 1/4 بوصة خيط أنثى", "valueEn": "1/4\" VCR female thread", "valueFr": "Magnétoscope 1/4 \" filetage femelle", "valueJa": "1/4インチビデオカメラ雌ねじ", "valueKo": "1/4\" VCR 암컷 스레드"}, {"name": "驱动", "value": "手动", "nameAr": "التشغيل", "nameEn": "Actuation", "nameFr": "Actionnement", "nameJa": "駆動方式", "nameKo": "구동 방식", "valueAr": "يدوي", "valueEn": "manual", "valueFr": "manuel", "valueJa": "手動", "valueKo": "수동"}]', 17, 'published', NULL, '2026-09-07 10:59:24.52', '2026-09-07 10:59:24.52', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO public.products ("siteId", id, "tabId", "categoryId", slug, model, name, "nameEn", "nameJa", "nameKo", "nameFr", "nameAr", subtitle, "subtitleEn", "subtitleJa", "subtitleKo", "subtitleFr", "subtitleAr", summary, "summaryEn", "summaryJa", "summaryKo", "summaryFr", "summaryAr", description, "descriptionEn", "descriptionJa", "descriptionKo", "descriptionFr", "descriptionAr", features, "featuresEn", "featuresJa", "featuresKo", "featuresFr", "featuresAr", images, price, "priceTiers", "isParts", "coverImage", video, frames360, "manualUrl", "priceMin", "priceMax", "priceUnit", moq, "priceNote", "priceNoteEn", "priceNoteJa", "priceNoteKo", "priceNoteFr", "priceNoteAr", specs, "sortOrder", status, "publishedAt", "createdAt", "updatedAt", "seoTitle", "seoTitleJa", "seoTitleKo", "seoTitleFr", "seoTitleAr", "seoTitleEn", "seoDescription", "seoDescriptionJa", "seoDescriptionKo", "seoDescriptionFr", "seoDescriptionAr", "seoDescriptionEn", "seoKeywords", "seoKeywordsJa", "seoKeywordsKo", "seoKeywordsFr", "seoKeywordsAr", "seoKeywordsEn", "geoRegion", "geoCity") VALUES (NULL, 18, 37, 9, 'dv12a-mr4-nc-hp', '316L-DV12A-MR4-NC-HP', '气动常闭隔膜阀', 'Pneumatic Normally-Closed Diaphragm Valve', '空気圧ノーマルクローズドダイヤフラムバルブ', '공압식 일반적으로 닫힌 다이어프램', 'Vanne à membrane pneumatique normalement fermée', 'صمام الحجاب الحاجز الهوائي مغلق عادة', '常闭，250psi，VCR 阳螺纹', 'NC, 250psi, VCR male', 'ノーマルクローズド、250psi、VCR オス', '일반적으로 닫힌, 250psi, VCR 수 스레드', 'Normalement fermé, 250psi, filetage mâle VCR', 'مغلق عادةً ، 250 رطل لكل بوصة مربعة ، مسجل فيديو ذكر', '气动常闭隔膜阀，失气关闭，VCR 阳螺纹连接，适用于自动化高纯气体控制。', 'Pneumatic NC diaphragm valve, air-to-open, VCR male, for automated UHP gas control.', '空気圧ノーマルクローズドダイヤフラムバルブ、ガスオフシャットダウン、VCRオスネジ接続、自動高純度ガス制御に適しています。', '공압식 일반적으로 닫힌 다이어프램 밸브, 가스 손실 폐쇄, 자동화된 고순도 가스 제어를 위한 VCR 수 나사 연결.', 'Vanne à membrane pneumatique normalement fermée, fermeture de perte de gaz, connexion filetée mâle VCR, adaptée au contrôle automatisé de gaz de haute pureté.', 'صمام الحجاب الحاجز الهوائي المغلق عادةً ، وإغلاق فقدان الهواء ، وصلة ملولبة ذكرية لجهاز VCR ، مناسب للتحكم الآلي في الغاز عالي النقاء.', '<p>气动常闭隔膜阀（NC-HP）失气自动关闭，保障系统安全；气动驱动适合自动化控制。</p><p>工作压力最大 250psi，1/4" VCR 阳螺纹连接，316L 阀体。</p>', '<p>Pneumatic NC diaphragm valve fails closed for system safety, pneumatic actuation for automation.</p><p>Max 250psi, 1/4" VCR male connection, 316L body.</p>', '<p>空気圧ノーマルクローズドダイヤフラムバルブ（NC-HP）はガスを失うと自動的に閉じ、システムの安全を保障する。空気圧駆動は自動制御に適しています。</p><p>動作圧力最大 250psi、1/4 インチ VCR オスネジ接続、316L バルブボディ。</p>', '<p>공압식 일반적으로 닫힌 다이어프램 밸브(NC-HP)는 가스를 잃으면 자동으로 닫혀 시스템 안전을 보장합니다 공압 구동은 자동화 제어에 적합합니다.</p><p>작동 압력 최대 250psi, 1/4" VCR 수 나사 연결, 316L 밸브 본체.</p>', '<p>La vanne à membrane pneumatique normalement fermée (NC-HP) se ferme automatiquement lorsque le gaz est perdu pour garantir la sécurité du système; L''entraînement pneumatique est adapté au contrôle automatique.</p><p>Pression de fonctionnement maximale 250 psi, raccordement fileté mâle VCR 1/4 ", corps 316L.</p>', '<p>يغلق صمام الحجاب الحاجز الهوائي المغلق عادةً (NC-HP) تلقائيًا عند فقدان الغاز لضمان سلامة النظام ؛ محرك هوائي مناسب للتحكم الآلي.</p><p>ضغط التشغيل 250 رطل لكل بوصة مربعة كحد أقصى ، وصلة ملولبة ذكر 1/4 بوصة VCR ، جسم صمام 316L.</p>', '["失气关闭（常闭）", "气动驱动可自动化", "VCR 1/4\" 连接"]', '["Fail-closed (NC)", "Pneumatic actuation", "1/4\" VCR connection"]', '["ガス抜きシャットダウン（ノーマル", "空気圧駆動は自動化できます", "ビデオカメラ1/4\" 接続"]', '["오프 가스 폐쇄(일반 폐쇄)", "공압 구동 자동화 가능", "VCR 1/4\" 연결"]', '["Perte de gaz fermée (normalement fermée)", "L''entraînement pneumatique peut être automatisé", "magnétoscope Connexion 1/4 \""]', NULL, NULL, NULL, NULL, false, '/uploads/oem/dv12a-smr4.jpg', NULL, NULL, NULL, NULL, NULL, NULL, 1, NULL, NULL, NULL, NULL, NULL, NULL, '[{"name": "工作压力", "value": "MAX. 250psi (1.72MPa)", "nameAr": "ضغط التشغيل", "nameEn": "Pressure", "nameFr": "Pression de service", "nameJa": "動作圧力", "nameKo": "작동 압력", "valueAr": "MAX. 250psi (1.72MPa)", "valueEn": "MAX. 250psi (1.72MPa)", "valueFr": "MAX. 250psi (1.72MPa)", "valueJa": "MAX. 250psi (1.72MPa)", "valueKo": "MAX. 250psi (1.72MPa)"}, {"name": "温度", "value": "-23℃ ~ 66℃", "nameAr": "درجة الحرارة", "nameEn": "Temperature", "nameFr": "Température", "nameJa": "温度", "nameKo": "온도", "valueAr": "-23℃ ~ 66℃", "valueEn": "-23℃ ~ 66℃", "valueFr": "-23℃ ~ 66℃", "valueJa": "-23℃ ~ 66℃", "valueKo": "-23℃ ~ 66℃"}, {"name": "连接", "value": "1/4\" VCR 阳螺纹", "nameAr": "الاتصال", "nameEn": "Connection", "nameFr": "Connexion", "nameJa": "接続", "nameKo": "연결", "valueAr": "جهاز فيديو 1/4 بوصة خيط ذكر", "valueEn": "1/4\" VCR male thread", "valueFr": "Magnétoscope 1/4 \" filetage mâle", "valueJa": "1/4インチビデオカメラオスねじ", "valueKo": "1/4\" VCR 수컷 스레드"}, {"name": "驱动", "value": "气动常闭", "nameAr": "التشغيل", "nameEn": "Actuation", "nameFr": "Actionnement", "nameJa": "駆動方式", "nameKo": "구동 방식", "valueAr": "هوائي مغلق عادة", "valueEn": "pneumatic normally closed", "valueFr": "Pneumatique normalement fermé", "valueJa": "空気圧ノーマルクローズ", "valueKo": "공압 정상 폐쇄"}]', 18, 'published', NULL, '2026-09-07 10:59:24.523', '2026-09-07 10:59:24.523', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO public.products ("siteId", id, "tabId", "categoryId", slug, model, name, "nameEn", "nameJa", "nameKo", "nameFr", "nameAr", subtitle, "subtitleEn", "subtitleJa", "subtitleKo", "subtitleFr", "subtitleAr", summary, "summaryEn", "summaryJa", "summaryKo", "summaryFr", "summaryAr", description, "descriptionEn", "descriptionJa", "descriptionKo", "descriptionFr", "descriptionAr", features, "featuresEn", "featuresJa", "featuresKo", "featuresFr", "featuresAr", images, price, "priceTiers", "isParts", "coverImage", video, frames360, "manualUrl", "priceMin", "priceMax", "priceUnit", moq, "priceNote", "priceNoteEn", "priceNoteJa", "priceNoteKo", "priceNoteFr", "priceNoteAr", specs, "sortOrder", status, "publishedAt", "createdAt", "updatedAt", "seoTitle", "seoTitleJa", "seoTitleKo", "seoTitleFr", "seoTitleAr", "seoTitleEn", "seoDescription", "seoDescriptionJa", "seoDescriptionKo", "seoDescriptionFr", "seoDescriptionAr", "seoDescriptionEn", "seoKeywords", "seoKeywordsJa", "seoKeywordsKo", "seoKeywordsFr", "seoKeywordsAr", "seoKeywordsEn", "geoRegion", "geoCity") VALUES (NULL, 19, 37, 9, 'dv22a-mr8', '316L-DV22A-MR8', '中流量隔膜阀', 'Medium-Flow Diaphragm Valve', '中流量ダイヤフラム弁', '중간 유량 다이어프램 밸브', 'Vanne à membrane à débit moyen', 'صمام الحجاب الحاجز متوسط التدفق', '1/2" VCR，CV 0.65', '1/2" VCR, CV 0.65', '1/2 インチ VCR、CV 0.65', '1/2" VCR, CV 0.65', 'Magnétoscope 1/2 ", CV 0,65', 'جهاز فيديو 1/2 بوصة ، CV 0.65', '低压中流量隔膜阀，CV 0.65，1/2" VCR 连接，适用于较大流量高纯气体。', 'Low-pressure medium-flow diaphragm valve, CV 0.65, 1/2" VCR.', '低圧中流量ダイヤフラムバルブ、CV 0.65、1/2 インチ VCR 接続、大流量の高純度ガスに適しています。', '저압 중간 유량 다이어프램 밸브, CV 0.65, 1/2" VCR 연결, 더 큰 유량 고순도 가스에 적합.', 'Vanne à membrane à débit moyen basse pression, CV 0,65, connexion VCR 1/2 ", adaptée aux gaz de haute pureté à débit plus important.', 'صمام الحجاب الحاجز ذو الضغط المنخفض والتدفق المتوسط ، CV 0.65 ، اتصال VCR مقاس 1/2 بوصة ، مناسب للتدفق الأكبر للغاز عالي النقاء.', '<p>DV22A 中流量隔膜阀提供更大的流通能力（CV 0.65），适用于工艺气体主管路。</p><p>316L 阀体，1/2" VCR 连接，手动/气动可选。</p>', '<p>DV22A medium-flow diaphragm valve with higher capacity (CV 0.65) for main process gas lines.</p><p>316L body, 1/2" VCR, manual or pneumatic.</p>', '<p>DV22A 中流量ダイヤフラム バルブは、プロセス ガス メイン ラインに向けてより大きな流量 (CV 0.65) を提供します。</p><p>316L バルブボディ、1/2 インチ VCR 接続、手動/空気圧オプション。</p>', '<p>DV22A 중간 유량 다이어프램 밸브는 공정 가스 메인 라인에 더 큰 유동 용량(CV 0.65)을 제공합니다.</p><p>316L 밸브 바디, 1/2" VCR 연결, 수동/공압 옵션.</p>', '<p>La vanne à membrane à débit moyen DV22A offre une plus grande capacité de circulation (CV 0,65) et est adaptée aux lignes principales de gaz de processus.</p><p>Corps 316L, raccordement VCR 1/2 ", manuel/pneumatique en option.</p>', '<p>يوفر صمام الحجاب الحاجز متوسط التدفق DV22A قدرة تدفق أكبر (CV 0.65) لخطوط غاز المعالجة الرئيسية.</p><p>جسم صمام 316L ، اتصال VCR 1/2 بوصة ، يدوي/هوائي اختياري.</p>', '["CV 0.65 大流量", "1/2\" VCR 连接", "手动/气动可选"]', '["CV 0.65 high flow", "1/2\" VCR", "Manual or pneumatic"]', '["CV 0.65 大流量", "1/2インチビデオカメラつながる", "手动/空気圧任意"]', '["CV 0.65 큰 흐름", "1/2\" VCR 연결", "수동/공압 옵션"]', '["CV 0,65 débit élevé", "Magnétoscope 1/2 \" connecter", "Manuel/pneumatique en option"]', NULL, NULL, NULL, NULL, false, '/uploads/oem/dv22a-mr8.jpg', NULL, NULL, NULL, NULL, NULL, NULL, 1, NULL, NULL, NULL, NULL, NULL, NULL, '[{"name": "工作压力", "value": "MAX. 250psi (1.72MPa)", "nameAr": "ضغط التشغيل", "nameEn": "Pressure", "nameFr": "Pression de service", "nameJa": "動作圧力", "nameKo": "작동 압력", "valueAr": "MAX. 250psi (1.72MPa)", "valueEn": "MAX. 250psi (1.72MPa)", "valueFr": "MAX. 250psi (1.72MPa)", "valueJa": "MAX. 250psi (1.72MPa)", "valueKo": "MAX. 250psi (1.72MPa)"}, {"name": "CV 值", "value": "0.65", "nameAr": "قيمة CV", "nameEn": "CV", "nameFr": "Valeur CV", "nameJa": "CV値", "nameKo": "CV 값", "valueAr": "0.65", "valueEn": "0.65", "valueFr": "0.65", "valueJa": "0.65", "valueKo": "0.65"}, {"name": "连接", "value": "1/2\" VCR", "nameAr": "الاتصال", "nameEn": "Connection", "nameFr": "Connexion", "nameJa": "接続", "nameKo": "연결", "valueAr": "1/2\" VCR", "valueEn": "1/2\" VCR", "valueFr": "1/2\" VCR", "valueJa": "1/2\" VCR", "valueKo": "1/2\" VCR"}]', 19, 'published', NULL, '2026-09-07 10:59:24.525', '2026-09-07 10:59:24.525', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO public.products ("siteId", id, "tabId", "categoryId", slug, model, name, "nameEn", "nameJa", "nameKo", "nameFr", "nameAr", subtitle, "subtitleEn", "subtitleJa", "subtitleKo", "subtitleFr", "subtitleAr", summary, "summaryEn", "summaryJa", "summaryKo", "summaryFr", "summaryAr", description, "descriptionEn", "descriptionJa", "descriptionKo", "descriptionFr", "descriptionAr", features, "featuresEn", "featuresJa", "featuresKo", "featuresFr", "featuresAr", images, price, "priceTiers", "isParts", "coverImage", video, frames360, "manualUrl", "priceMin", "priceMax", "priceUnit", moq, "priceNote", "priceNoteEn", "priceNoteJa", "priceNoteKo", "priceNoteFr", "priceNoteAr", specs, "sortOrder", status, "publishedAt", "createdAt", "updatedAt", "seoTitle", "seoTitleJa", "seoTitleKo", "seoTitleFr", "seoTitleAr", "seoTitleEn", "seoDescription", "seoDescriptionJa", "seoDescriptionKo", "seoDescriptionFr", "seoDescriptionAr", "seoDescriptionEn", "seoKeywords", "seoKeywordsJa", "seoKeywordsKo", "seoKeywordsFr", "seoKeywordsAr", "seoKeywordsEn", "geoRegion", "geoCity") VALUES (NULL, 21, 38, 10, 'prt1-mr4', '316L-PRT1-MR4', '联接式膜片减压阀', 'Tied-Diaphragm Pressure Reducer', 'カップリングダイヤフラム減圧弁', '결합형 다이어프램 감압 밸브', 'Réducteur de pression à diaphragme connecté', 'صمام تخفيض ضغط الحجاب الحاجز المتصل', '入口 31.0MPa，CV 0.09/0.15', 'Inlet 31.0MPa, CV 0.09/0.15', '入口 31.0MPa、CV 0.09/0.15', '입구 31.0MPa, CV 0.09/0.15', 'Entrée 31.0MPa, CV 0.09/0.15', 'مدخل 31.0 ميجا باسكال ، CV 0.09 / 0.15', '联接式膜片减压阀，入口压力最高 31.0MPa，高精度输出控制。', 'Tied-diaphragm reducer, max inlet 31.0MPa, high-precision outlet control.', 'カップリング式ダイヤフラム減圧弁、入口圧力最大31.0MPa、高精度出力制御。', '최대 31.0MPa의 입구 압력과 고정밀 출력 제어를 갖춘 결합형 다이어프램 감압 밸브.', 'Vanne réductrice de pression à diaphragme connectée, pression d''entrée jusqu''à 31,0 MPa, contrôle de sortie de haute précision.', 'صمام تخفيض ضغط الحجاب الحاجز المتصل ، ضغط مدخل يصل إلى 31.0 ميجا باسكال ، تحكم في الإخراج عالي الدقة.', '<p>PRT1 联接式膜片减压阀采用膜片式调节机构，输出压力稳定，适用于高压气源精密减压。</p><p>316L 材质，入口最高 31.0MPa，洁净室装配。</p>', '<p>PRT1 tied-diaphragm reducer with stable outlet pressure for high-pressure source regulation.</p><p>316L, max inlet 31.0MPa, cleanroom assembled.</p>', '<p>PRT1 連結ダイヤフラム減圧弁はダイヤフラム調整機構を採用しており、出力圧力が安定しており、高圧空気源の精密減圧に適しています。</p><p>316L素材、入口最大31.0MPa、クリーンルーム組立。</p>', '<p>PRT1 연결 다이어프램 감압 밸브는 다이어프램 조정 메커니즘을 채택하고 출력 압력이 안정적이며 고압 공기원의 정밀 감압에 적합합니다.</p><p>316L 재질, 입구 최대 31.0MPa, 클린룸 조립.</p>', '<p>La vanne réductrice de pression à diaphragme connectée PRT1 adopte un mécanisme de réglage à diaphragme avec une pression de sortie stable et convient à la décompression précise des sources d''air haute pression.</p><p>Matériau 316L, entrée jusqu''à 31,0 MPa, assemblage salle blanche.</p>', '<p>يعتمد صمام تقليل ضغط الحجاب الحاجز المتصل PRT1 آلية تعديل الحجاب الحاجز مع ضغط خرج مستقر ، وهو مناسب لتقليل الضغط الدقيق لمصادر الهواء عالية الضغط.</p><p>مادة 316L ، مدخل يصل إلى 31.0MPa ، تجميع الغرفة النظيفة.</p>', '["入口 31.0MPa", "膜片式高精度", "洁净室装配"]', '["31.0MPa inlet", "Diaphragm precision", "Cleanroom assembled"]', '["入口 31.0MPa", "ダイヤフラム式高精度", "クリーンルーム組立"]', '["입구 31.0MPa", "다이어프램형 고정밀", "클린룸 조립"]', '["Entrée 31.0MPa", "Haute précision de type diaphragme", "Assemblage salle blanche"]', NULL, NULL, NULL, NULL, false, '/uploads/oem/prt1-mr4.jpg', NULL, NULL, NULL, NULL, NULL, NULL, 1, NULL, NULL, NULL, NULL, NULL, NULL, '[{"name": "入口压力", "value": "MAX. 31.0MPa", "nameAr": "ضغط المدخل", "nameEn": "Inlet", "nameFr": "Pression d''entrée", "nameJa": "入口圧力", "nameKo": "입구 압력", "valueAr": "MAX. 31.0MPa", "valueEn": "MAX. 31.0MPa", "valueFr": "MAX. 31.0MPa", "valueJa": "MAX. 31.0MPa", "valueKo": "MAX. 31.0MPa"}, {"name": "CV 值", "value": "0.09 / 0.15", "nameAr": "قيمة CV", "nameEn": "CV", "nameFr": "Valeur CV", "nameJa": "CV値", "nameKo": "CV 값", "valueAr": "0.09 / 0.15", "valueEn": "0.09 / 0.15", "valueFr": "0.09 / 0.15", "valueJa": "0.09 / 0.15", "valueKo": "0.09 / 0.15"}, {"name": "材质", "value": "316L", "nameAr": "المواد", "nameEn": "Material", "nameFr": "Matériel", "nameJa": "材質", "nameKo": "재료", "valueAr": "316L", "valueEn": "316L", "valueFr": "316L", "valueJa": "316L", "valueKo": "316L"}]', 21, 'published', NULL, '2026-09-07 10:59:24.53', '2026-09-07 11:54:25.73', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO public.products ("siteId", id, "tabId", "categoryId", slug, model, name, "nameEn", "nameJa", "nameKo", "nameFr", "nameAr", subtitle, "subtitleEn", "subtitleJa", "subtitleKo", "subtitleFr", "subtitleAr", summary, "summaryEn", "summaryJa", "summaryKo", "summaryFr", "summaryAr", description, "descriptionEn", "descriptionJa", "descriptionKo", "descriptionFr", "descriptionAr", features, "featuresEn", "featuresJa", "featuresKo", "featuresFr", "featuresAr", images, price, "priceTiers", "isParts", "coverImage", video, frames360, "manualUrl", "priceMin", "priceMax", "priceUnit", moq, "priceNote", "priceNoteEn", "priceNoteJa", "priceNoteKo", "priceNoteFr", "priceNoteAr", specs, "sortOrder", status, "publishedAt", "createdAt", "updatedAt", "seoTitle", "seoTitleJa", "seoTitleKo", "seoTitleFr", "seoTitleAr", "seoTitleEn", "seoDescription", "seoDescriptionJa", "seoDescriptionKo", "seoDescriptionFr", "seoDescriptionAr", "seoDescriptionEn", "seoKeywords", "seoKeywordsJa", "seoKeywordsKo", "seoKeywordsFr", "seoKeywordsAr", "seoKeywordsEn", "geoRegion", "geoCity") VALUES (NULL, 24, 40, 12, 'ft4-mr4-s15', '316L-FT4-MR4-S15-HP', '粉末烧结过滤器', 'Sintered Powder Filter', '粉末焼結フィルター', '분말 소결 필터', 'Filtre à frittage de poudre', 'مسحوق تلبد مرشح', '滤芯最小 0.5μm，20.7MPa', 'Element min 0.5μm, 20.7MPa', 'フィルターエレメント 最小 0.5μm、20.7MPa', '필터 요소 최소 0.5μm, 20.7MPa', 'Élément filtrant minimum 0,5 μ m, 20,7 MPa', 'عنصر الفلتر الحد الأدنى 0.5 ميكرومتر ، 20.7 ميجا باسكال', '粉末烧结滤芯气体过滤器，过滤精度最小 0.5 微米，适用于高纯气体过滤。', 'Sintered powder element gas filter, min 0.5μm for UHP gas filtration.', '粉末焼結カートリッジガスフィルター、ろ過精度最低0.5ミクロン、高純度ガスろ過に適しています。', '최소 0.5 마이크론의 여과 정확도를 갖춘 분말 소결 필터 카트리지 가스 필터는 고순도 가스 여과에 적합합니다.', 'Filtre à gaz à élément de filtre fritté en poudre avec une précision de filtration minimale de 0,5 microns, adapté à la filtration de gaz de haute pureté.', 'مرشح غاز عنصر مسحوق متلبد ، دقة ترشيح لا تقل عن 0.5 ميكرون ، مناسب لترشيح الغاز عالي النقاء.', '<p>FT4 粉末烧结过滤器采用烧结金属滤芯，过滤精度最小 0.5 微米，去除工艺气体颗粒。</p><p>工作压力最大 20.7MPa，316L 材质，VCR 1/4" 连接，EP 表面可选。</p>', '<p>FT4 sintered powder filter with metal element, min 0.5μm particle removal for process gas.</p><p>Max 20.7MPa, 316L, 1/4" VCR, EP finish option.</p>', '<p>FT4 粉末焼結フィルターは、最低 0.5 ミクロンの濾過精度を備えた焼結金属フィルターエレメントを使用し、プロセスガス粒子を除去します。</p><p>動作圧力最大 20.7MPa、316L 素材、VCR 1/4 インチ接続、EP 表面はオプションです。</p>', '<p>FT4 분말 소결 필터는 공정 가스 입자를 제거하기 위해 최소 0.5마이크론의 여과 정확도를 갖춘 소결 금속 필터 카트리지를 사용합니다.</p><p>작동 압력 최대 20.7MPa, 316L 재질, VCR 1/4" 연결, EP 표면 선택.</p>', '<p>Le filtre fritté à poudre FT4 utilise un élément filtrant en métal fritté avec une précision de filtration minimale de 0,5 microns pour éliminer les particules de gaz de processus.</p><p>Pression de travail maximale 20,7 MPa, matériau 316L, connexion VCR 1/4 ", surface EP en option.</p>', '<p>يستخدم مرشح تلبيد المسحوق FT4 عنصرًا معدنيًا متلبدًا بدقة ترشيح لا تقل عن 0.5 ميكرون لإزالة جزيئات غاز العملية.</p><p>ضغط العمل 20.7MPa كحد أقصى ، مادة 316L ، اتصال VCR 1/4 "، سطح EP اختياري.</p>', '["滤芯 0.5μm", "20.7MPa", "316L / EP 可选"]', '["0.5μm element", "20.7MPa", "316L / EP option"]', '["フィルターエレメント 0.5μm", "20.7MPa", "316L / EP オプション"]', '["필터 요소 0.5μm", "20.7MPa", "316L / EP 선택"]', '["Élément filtrant 0,5 μ m", "20,7 MPa", "316L/EP en option"]', NULL, NULL, NULL, NULL, false, '/uploads/oem/ft4-mr4.png', NULL, NULL, NULL, NULL, NULL, NULL, 1, NULL, NULL, NULL, NULL, NULL, NULL, '[{"name": "工作压力", "value": "MAX. 20.7MPa", "nameAr": "ضغط التشغيل", "nameEn": "Pressure", "nameFr": "Pression de service", "nameJa": "動作圧力", "nameKo": "작동 압력", "valueAr": "MAX. 20.7MPa", "valueEn": "MAX. 20.7MPa", "valueFr": "MAX. 20.7MPa", "valueJa": "MAX. 20.7MPa", "valueKo": "MAX. 20.7MPa"}, {"name": "滤芯", "value": "烧结金属，最小 0.5μm", "nameAr": "عنصر الفلتر", "nameEn": "Element", "nameFr": "élément filtrant", "nameJa": "フィルターエレメント", "nameKo": "필터 요소", "valueAr": "معدن متكلس ، الحد الأدنى 0.5 ميكرومتر", "valueEn": "Sintered metal, minimum 0.5μm", "valueFr": "Métal fritté, 0,5 μ m minimum", "valueJa": "焼結金属、最小 0.5μm", "valueKo": "소결 금속, 최소 0.5μm"}, {"name": "连接", "value": "1/4\" VCR", "nameAr": "الاتصال", "nameEn": "Connection", "nameFr": "Connexion", "nameJa": "接続", "nameKo": "연결", "valueAr": "1/4\" VCR", "valueEn": "1/4\" VCR", "valueFr": "1/4\" VCR", "valueJa": "1/4\" VCR", "valueKo": "1/4\" VCR"}]', 24, 'published', NULL, '2026-09-07 10:59:24.538', '2026-09-07 10:59:24.538', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO public.products ("siteId", id, "tabId", "categoryId", slug, model, name, "nameEn", "nameJa", "nameKo", "nameFr", "nameAr", subtitle, "subtitleEn", "subtitleJa", "subtitleKo", "subtitleFr", "subtitleAr", summary, "summaryEn", "summaryJa", "summaryKo", "summaryFr", "summaryAr", description, "descriptionEn", "descriptionJa", "descriptionKo", "descriptionFr", "descriptionAr", features, "featuresEn", "featuresJa", "featuresKo", "featuresFr", "featuresAr", images, price, "priceTiers", "isParts", "coverImage", video, frames360, "manualUrl", "priceMin", "priceMax", "priceUnit", moq, "priceNote", "priceNoteEn", "priceNoteJa", "priceNoteKo", "priceNoteFr", "priceNoteAr", specs, "sortOrder", status, "publishedAt", "createdAt", "updatedAt", "seoTitle", "seoTitleJa", "seoTitleKo", "seoTitleFr", "seoTitleAr", "seoTitleEn", "seoDescription", "seoDescriptionJa", "seoDescriptionKo", "seoDescriptionFr", "seoDescriptionAr", "seoDescriptionEn", "seoKeywords", "seoKeywordsJa", "seoKeywordsKo", "seoKeywordsFr", "seoKeywordsAr", "seoKeywordsEn", "geoRegion", "geoCity") VALUES (NULL, 25, 40, 12, 'ft5-mr4', '316L-FT5-MR4', '陶瓷滤芯过滤器', 'Ceramic Element Filter', 'セラミックカートリッジフィルター', '세라믹 필터 필터', 'Filtre à cartouche en céramique', 'فلتر عنصر السيراميك', '滤芯 2.5nm，20.7MPa', 'Element 2.5nm, 20.7MPa', 'フィルターエレメント 2.5nm、20.7MPa', '필터 요소 2.5nm, 20.7MPa', 'Élément filtrant 2,5 nm, 20,7 MPa', 'عنصر الفلتر 2.5 نانومتر ، 20.7 ميجا باسكال', '陶瓷滤芯气体过滤器，过滤精度 2.5 纳米，适用于超高纯气体深度过滤。', 'Ceramic element gas filter, 2.5nm for UHP gas deep filtration.', 'セラミックカートリッジガスフィルター、濾過精度 2.5 nm、超高純度ガスの深度濾過に適しています。', '초고순도 가스의 깊은 여과를 위한 2.5nm 정밀도를 갖춘 세라믹 카트리지 가스 필터.', 'Filtre à gaz à élément de filtre en céramique avec une précision de filtration de 2,5 nanomètres, adapté à la filtration en profondeur de gaz ultra haute pureté.', 'فلتر غاز من السيراميك بدقة ترشيح 2.5 نانومتر ، مناسب للترشيح العميق للغاز فائق النقاء.', '<p>FT5 陶瓷滤芯过滤器提供纳米级过滤精度（2.5nm），满足半导体工艺气体颗粒要求。</p><p>工作压力最大 20.7MPa，316L 阀体，VCR 连接。</p>', '<p>FT5 ceramic element filter with 2.5nm precision for semiconductor-grade particle removal.</p><p>Max 20.7MPa, 316L body, VCR connection.</p>', '<p>FT5 セラミック カートリッジ フィルターは、半導体プロセスガス粒子の要件を満たすナノスケールの濾過精度 (2.5nm) を提供します。</p><p>作動圧力最大20.7MPa、316Lバルブボディ、VCR接続。</p>', '<p>FT5 세라믹 카트리지 필터는 반도체 공정 가스 입자 요구 사항을 충족하는 나노 스케일 여과 정확도(2.5nm)를 제공합니다.</p><p>작동압력 최대 20.7MPa, 316L 밸브 본체, VCR 연결.</p>', '<p>Le filtre à élément de filtre en céramique FT5 offre une précision de filtration à l''échelle nanométrique (2,5 nm) et répond aux exigences relatives aux particules de gaz du processus semi-conducteur.</p><p>Pression de fonctionnement max. 20,7MPa, corps de vanne 316L, connexion VCR.</p>', '<p>يوفر مرشح عنصر السيراميك FT5 دقة ترشيح على نطاق النانو (2.5 نانومتر) لتلبية متطلبات جزيئات غاز عملية أشباه الموصلات.</p><p>ضغط العمل 20.7 ميجا باسكال كحد أقصى ، جسم صمام 316L ، اتصال VCR.</p>', '["滤芯 2.5nm", "20.7MPa", "半导体级过滤"]', '["2.5nm element", "20.7MPa", "Semiconductor-grade"]', '["フィルタエレメント 2.5nm", "20.7MPa", "半導体級ろ過"]', '["필터 요소 2.5nm", "20.7MPa", "반도체급 여과"]', '["Élément filtrant 2,5nm", "20,7 MPa", "Filtration de niveau semi-conducteur"]', NULL, NULL, NULL, NULL, false, '/uploads/oem/ft5-mr4.jpg', NULL, NULL, NULL, NULL, NULL, NULL, 1, NULL, NULL, NULL, NULL, NULL, NULL, '[{"name": "工作压力", "value": "MAX. 20.7MPa", "nameAr": "ضغط التشغيل", "nameEn": "Pressure", "nameFr": "Pression de service", "nameJa": "動作圧力", "nameKo": "작동 압력", "valueAr": "MAX. 20.7MPa", "valueEn": "MAX. 20.7MPa", "valueFr": "MAX. 20.7MPa", "valueJa": "MAX. 20.7MPa", "valueKo": "MAX. 20.7MPa"}, {"name": "滤芯", "value": "陶瓷，2.5nm", "nameAr": "عنصر الفلتر", "nameEn": "Element", "nameFr": "élément filtrant", "nameJa": "フィルターエレメント", "nameKo": "필터 요소", "valueAr": "السيراميك ، 2.5 نانومتر", "valueEn": "Ceramic, 2.5nm", "valueFr": "Céramique, 2,5 nm", "valueJa": "セラミック、2.5nm", "valueKo": "세라믹, 2.5nm"}, {"name": "连接", "value": "VCR", "nameAr": "الاتصال", "nameEn": "Connection", "nameFr": "Connexion", "nameJa": "接続", "nameKo": "연결", "valueAr": "VCR", "valueEn": "VCR", "valueFr": "VCR", "valueJa": "VCR", "valueKo": "VCR"}]', 25, 'published', NULL, '2026-09-07 10:59:24.54', '2026-09-07 11:54:25.732', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);


