INSERT INTO public.services ("siteId", id, slug, title, "titleEn", "titleJa", "titleKo", "titleFr", "titleAr", subtitle, "subtitleEn", "subtitleJa", "subtitleKo", "subtitleFr", "subtitleAr", description, "descriptionEn", "descriptionJa", "descriptionKo", "descriptionFr", "descriptionAr", features, "featuresEn", "featuresJa", "featuresKo", "featuresFr", "featuresAr", process, "processEn", "processJa", "processKo", "processFr", "processAr", icon, video, "sortOrder", status, "seoTitle", "seoTitleEn", "seoTitleJa", "seoTitleKo", "seoTitleFr", "seoTitleAr", "seoDescription", "seoDescriptionEn", "seoDescriptionJa", "seoDescriptionKo", "seoDescriptionFr", "seoDescriptionAr", "seoKeywords", "seoKeywordsEn", "seoKeywordsJa", "seoKeywordsKo", "seoKeywordsFr", "seoKeywordsAr", "geoRegion", "geoCity", "solutionFile", "solutionFileName", "solutionFileNameEn", "solutionFileNameJa", "solutionFileNameKo", "solutionFileNameFr", "solutionFileNameAr", "relatedProductSlugs", "relatedServiceSlugs", "createdAt", "updatedAt") VALUES (NULL, 1, 'technical-support', '技术支持', 'Technical Support', 'テクニカルサポート', '기술 지원', 'Support technique', 'الدعم الفني', '专业选型与技术咨询', 'Professional selection and technical consultation', '専門的な選択と技術コンサルティング', '전문 선택 및 기술 컨설팅', 'Sélection professionnelle et conseil technique', 'الاختيار المهني والاستشارات الفنية', '<p>阀门科技提供专业的阀门选型、技术咨询与系统解决方案服务，帮助客户选择最合适的阀门产品。</p>', '<p>VALVE TECH provides professional valve selection, technical consultation and system solutions to help customers choose the right valves.</p>', '<p>Valve Technology は、お客様が最適なバルブ製品を選択できるよう、専門的なバルブ選択、技術コンサルティング、システム ソリューション サービスを提供します。</p>', '<p>Valve Technology는 고객이 가장 적합한 밸브 제품을 선택할 수 있도록 전문적인 밸브 선택, 기술 컨설팅 및 시스템 솔루션 서비스를 제공합니다.</p>', '<p>Valve Technology fournit des services professionnels de sélection de vannes, de conseil technique et de solutions système pour aider les clients à choisir les produits de vannes les plus appropriés.</p>', '<p>توفر Valve Technology خدمات اختيار الصمامات الاحترافية والاستشارات الفنية وحلول النظام لمساعدة العملاء على اختيار منتجات الصمامات الأكثر ملاءمة.</p>', '["选型咨询", "技术方案设计", "现场勘察支持"]', '["Selection consultation", "Technical solution design", "On-site survey support"]', NULL, NULL, NULL, NULL, '[{"desc": "了解工况与需求", "title": "需求沟通", "descEn": "Understand service conditions", "titleEn": "Requirement"}, {"desc": "阀门选型与方案", "title": "方案设计", "descEn": "Valve selection and solution", "titleEn": "Design"}, {"desc": "报价与交期确认", "title": "报价交付", "descEn": "Pricing and delivery", "titleEn": "Quote"}]', NULL, NULL, NULL, NULL, NULL, 'support', NULL, 0, 'published', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-09-07 09:56:05.637', '2026-09-07 10:10:59.12');
INSERT INTO public.services ("siteId", id, slug, title, "titleEn", "titleJa", "titleKo", "titleFr", "titleAr", subtitle, "subtitleEn", "subtitleJa", "subtitleKo", "subtitleFr", "subtitleAr", description, "descriptionEn", "descriptionJa", "descriptionKo", "descriptionFr", "descriptionAr", features, "featuresEn", "featuresJa", "featuresKo", "featuresFr", "featuresAr", process, "processEn", "processJa", "processKo", "processFr", "processAr", icon, video, "sortOrder", status, "seoTitle", "seoTitleEn", "seoTitleJa", "seoTitleKo", "seoTitleFr", "seoTitleAr", "seoDescription", "seoDescriptionEn", "seoDescriptionJa", "seoDescriptionKo", "seoDescriptionFr", "seoDescriptionAr", "seoKeywords", "seoKeywordsEn", "seoKeywordsJa", "seoKeywordsKo", "seoKeywordsFr", "seoKeywordsAr", "geoRegion", "geoCity", "solutionFile", "solutionFileName", "solutionFileNameEn", "solutionFileNameJa", "solutionFileNameKo", "solutionFileNameFr", "solutionFileNameAr", "relatedProductSlugs", "relatedServiceSlugs", "createdAt", "updatedAt") VALUES (NULL, 2, 'custom-manufacturing', '定制加工', 'Custom Manufacturing', 'カスタム加工', '맞춤형 가공', 'Traitement sur mesure', 'معالجة مخصصة', '非标阀门与定制服务', 'Non-standard valves and customization', '非标准バルブとカスタマイズされたサービス', '비표준 밸브 및 맞춤형 서비스', 'Vannes non standard et services personnalisés', 'صمامات غير قياسية وخدمات مخصصة', '<p>支持非标阀门定制，包括特殊材质、特殊连接方式与特殊工况产品，满足客户个性化需求。</p>', '<p>Non-standard valve customization including special materials, connections and service conditions.</p>', '<p>お客様の個別のニーズを満たすために、特殊な材料、特殊な接続方法、特殊な作業条件の製品を含む非標準バルブのカスタマイズをサポートします。</p>', '<p>고객의 개인화된 요구 사항을 충족하기 위해 특수 재료, 특수 연결 방법 및 특수 작업 조건 제품을 포함한 비표준 밸브 맞춤화를 지원합니다.</p>', '<p>Prend en charge la personnalisation des vannes non standard, y compris des matériaux spéciaux, des méthodes de connexion spéciales et des produits dans des conditions de travail spéciales, pour répondre aux besoins individuels des clients.</p>', '<p>دعم تخصيص الصمامات غير القياسية ، بما في ذلك المواد الخاصة وطرق الاتصال الخاصة ومنتجات ظروف العمل الخاصة لتلبية الاحتياجات الفردية للعملاء.</p>', '["非标定制", "特殊材质加工", "小批量生产"]', '["Non-standard customization", "Special materials", "Small batch production"]', NULL, NULL, NULL, NULL, '[{"desc": "图纸与技术参数", "title": "需求确认", "descEn": "Drawings and parameters", "titleEn": "Requirement"}, {"desc": "样品制作与验证", "title": "打样生产", "descEn": "Sample making and validation", "titleEn": "Prototype"}, {"desc": "批量生产与质检", "title": "批量交付", "descEn": "Batch production and QC", "titleEn": "Production"}]', NULL, NULL, NULL, NULL, NULL, 'custom', NULL, 1, 'published', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-09-07 09:56:05.64', '2026-09-07 10:10:59.123');
INSERT INTO public.services ("siteId", id, slug, title, "titleEn", "titleJa", "titleKo", "titleFr", "titleAr", subtitle, "subtitleEn", "subtitleJa", "subtitleKo", "subtitleFr", "subtitleAr", description, "descriptionEn", "descriptionJa", "descriptionKo", "descriptionFr", "descriptionAr", features, "featuresEn", "featuresJa", "featuresKo", "featuresFr", "featuresAr", process, "processEn", "processJa", "processKo", "processFr", "processAr", icon, video, "sortOrder", status, "seoTitle", "seoTitleEn", "seoTitleJa", "seoTitleKo", "seoTitleFr", "seoTitleAr", "seoDescription", "seoDescriptionEn", "seoDescriptionJa", "seoDescriptionKo", "seoDescriptionFr", "seoDescriptionAr", "seoKeywords", "seoKeywordsEn", "seoKeywordsJa", "seoKeywordsKo", "seoKeywordsFr", "seoKeywordsAr", "geoRegion", "geoCity", "solutionFile", "solutionFileName", "solutionFileNameEn", "solutionFileNameJa", "solutionFileNameKo", "solutionFileNameFr", "solutionFileNameAr", "relatedProductSlugs", "relatedServiceSlugs", "createdAt", "updatedAt") VALUES (NULL, 3, 'maintenance-service', '维修保养', 'Maintenance Service', 'メンテナンス', '유지보수', 'Réparation et entretien', 'الإصلاح والصيانة', '阀门检修与备件供应', 'Valve overhaul and spares', 'バルブオーバーホールとスペアパーツの供給', '밸브 점검 및 예비 부품 공급', 'Entretien des vannes et fourniture de pièces détachées', 'صيانة الصمامات وتوريد قطع الغيار', '<p>提供阀门检修、密封件更换、安全阀整定校验与备件供应服务，保障阀门长期可靠运行。</p>', '<p>Valve overhaul, seal replacement, safety valve set-point testing and spares supply keep valves reliable.</p>', '<p>バルブのメンテナンス、シール交換、安全弁のセットアップと校正、スペアパーツの供給サービスを提供し、バルブの長期的かつ信頼性の高い動作を確保します。</p>', '<p>밸브의 장기적이고 안정적인 작동을 보장하기 위해 밸브 유지보수, 씰 교체, 안전 밸브 설정 검사 및 예비 부품 공급 서비스를 제공합니다.</p>', '<p>Fournir des services d''entretien des vannes, de remplacement des joints, de réglage et d''étalonnage des vannes de sécurité et de fourniture de pièces de rechange pour garantir un fonctionnement fiable à long terme des vannes.</p>', '<p>توفير صيانة الصمام ، واستبدال الختم ، وإعداد صمام الأمان والتحقق منه ، وخدمات توريد قطع الغيار لضمان التشغيل الموثوق به على المدى الطويل للصمام.</p>', '["阀门检修", "密封件更换", "安全阀整定校验"]', '["Valve overhaul", "Seal replacement", "Safety valve set-point testing"]', NULL, NULL, NULL, NULL, '[{"desc": "检测与问题定位", "title": "故障诊断", "descEn": "Inspection and troubleshooting", "titleEn": "Diagnosis"}, {"desc": "维修与部件更换", "title": "维修更换", "descEn": "Repair and part replacement", "titleEn": "Repair"}, {"desc": "压力测试与交付", "title": "测试交付", "descEn": "Pressure testing and delivery", "titleEn": "Testing"}]', NULL, NULL, NULL, NULL, NULL, 'maintenance', NULL, 2, 'published', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-09-07 09:56:05.642', '2026-09-07 10:10:59.125');
INSERT INTO public.services ("siteId", id, slug, title, "titleEn", "titleJa", "titleKo", "titleFr", "titleAr", subtitle, "subtitleEn", "subtitleJa", "subtitleKo", "subtitleFr", "subtitleAr", description, "descriptionEn", "descriptionJa", "descriptionKo", "descriptionFr", "descriptionAr", features, "featuresEn", "featuresJa", "featuresKo", "featuresFr", "featuresAr", process, "processEn", "processJa", "processKo", "processFr", "processAr", icon, video, "sortOrder", status, "seoTitle", "seoTitleEn", "seoTitleJa", "seoTitleKo", "seoTitleFr", "seoTitleAr", "seoDescription", "seoDescriptionEn", "seoDescriptionJa", "seoDescriptionKo", "seoDescriptionFr", "seoDescriptionAr", "seoKeywords", "seoKeywordsEn", "seoKeywordsJa", "seoKeywordsKo", "seoKeywordsFr", "seoKeywordsAr", "geoRegion", "geoCity", "solutionFile", "solutionFileName", "solutionFileNameEn", "solutionFileNameJa", "solutionFileNameKo", "solutionFileNameFr", "solutionFileNameAr", "relatedProductSlugs", "relatedServiceSlugs", "createdAt", "updatedAt") VALUES (NULL, 4, 'training-consulting', '培训咨询', 'Training & Consulting', '研修コンサルティング', '교육 컨설팅', 'Conseils en formation', 'استشارات التدريب', '阀门知识与操作培训', 'Valve knowledge and operation training', 'バルブの知識と操作トレーニング', '밸브 지식 및 운영 교육', 'Connaissance des vannes et formation au fonctionnement', 'معرفة الصمام والتدريب على التشغيل', '<p>为客户提供阀门选型、安装、操作与维护培训，提升客户团队的专业能力。</p>', '<p>Training on valve selection, installation, operation and maintenance to empower customer teams.</p>', '<p>お客様にバルブの選択、設置、操作とメンテナンスのトレーニングを提供し、お客様チームの専門能力を向上させます。</p>', '<p>고객에게 밸브 선택, 설치, 운영 및 유지 관리 교육을 제공하여 고객 팀의 전문 능력을 향상시킨다.</p>', '<p>Fournir aux clients une formation sur la sélection, l''installation, l''exploitation et la maintenance des vannes pour améliorer les capacités professionnelles de l''équipe client.</p>', '<p>تزويد العملاء بالتدريب على اختيار الصمامات وتركيبها وتشغيلها وصيانتها لتحسين القدرات المهنية لفريق العملاء.</p>', '["选型培训", "安装操作培训", "维护保养培训"]', '["Selection training", "Installation and operation training", "Maintenance training"]', NULL, NULL, NULL, NULL, '[{"desc": "培训需求与内容", "title": "需求调研", "descEn": "Training needs and content", "titleEn": "Survey"}, {"desc": "理论+实操培训", "title": "课程实施", "descEn": "Theory and hands-on training", "titleEn": "Delivery"}, {"desc": "考核与反馈", "title": "效果评估", "descEn": "Assessment and feedback", "titleEn": "Evaluation"}]', NULL, NULL, NULL, NULL, NULL, 'training', NULL, 3, 'published', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-09-07 09:56:05.644', '2026-09-07 10:10:59.128');


